window.__D("text/torat-shmuel/c053",{"p":[[2001910094,"שאלף הוא ר\"ת ארור<sup data-n=\"282\">108</sup>, אבל ב' הוא ר\"ת ברכה, וא\"כ לפי\"ז אינו מובן למה מ\"ת פתח בא', אך הענין הוא דהנה אלף הוא בחי' גבוה מאד שא' הוא ראש לכל אותיות<sup data-n=\"283\">109</sup>, אלף הוא בחי' פלא<sup data-n=\"284\">110</sup> בחי' כתר<sup data-n=\"285\">111</sup> ולכן לפי שהוא בחי' גבוה מאד ע\"כ אין תופס שם מקום כלל כדכתי' שממית בידים תתפש<sup data-n=\"286\">112</sup> והיא בהיכלי מלך לפי ששם כחשיכה כאורה<sup data-n=\"287\">113</sup> שוין, וזהו שא' ר\"ת ארור היינו שאפי' ארור שהוא סט\"א יכול ג\"כ לקבל יניקה משם לפי שאין תופס שם מקום כלל, ולזה ברה\"ע התחיל בבית שהוא סימן ברכה, ברכה הוא בחי' חכמה<sup data-n=\"288\">114</sup>, וזהו שת\"י בראשית בחוכמתא<sup data-n=\"289\">115</sup>, בחכ' יבנה בית בחכ' יבנה בי\"ת<sup data-n=\"290\">116</sup>, ונודע כי בבחי' חכ' שם יש בחי' בירור שאינו נמשך כ\"א למקום הראוי דוקא, ומ\"מ במ\"ת התחיל בא' והיינו מאחר שהי' ברה\"ע ע\"י אות ב' שהוא סימן ברכה כנ\"ל, ורומז לבחי' החכ' שבחכמה אתברירו כנודע, לכן אפי' כשנמשך אח\"כ מבחי' א' אינו יכול להיות משם יניקת החצוני' לפי שהמשכה זו אם היותה מבחי' גבוה מאד נעלה כו', מ\"מ הנה גם זה נמשך ע\"י חכ' דוקא, שמשם אינם יכולים לקבל כנ\"ל, וזהו ג\"כ שדרשו כנ\"ל א\"ת מה אלא מאה והיינו שע\"י מה שהוא בחי' ביטול בחי' חכ' יכול להיות נמשך גם בחי' א' ולא יהי' מזה יניקת החיצוני' כלל לפי שהמשכה זו נמשך ע\"י בחי' מה שהוא בחי' חכ', וגם זה אמת כי כדי להמשיך בחי' א' צריך לברך מאה ברכות דוקא, שע\"י מאה דוקא עי\"ז ממשיכים את הא' כו' לפי שמאה הוא בחי' בינה<sup data-n=\"291\">117</sup> והתגלות ע\"י הוא בבינה<sup data-n=\"292\">118</sup> כידוע כו'.\n(ד) <b>והנה</b> המאה הברכות הנ\"ל הוא בדבור, ובכלליות ענין מחדומ\"ע הנה הדבור הוא ביצירה<sup data-n=\"293\">119</sup> כנודע, וא\"כ ע\"י מה יהי' המשכה מהעלם אל הגילוי למטה הנה הוא ע\"י מעשה המצות, דהנה כל מצוה צריך לקיים בבחי' מח' ודבור ומעשה<sup data-n=\"294\">120</sup>, לפי שיש ג' עולמות בי\"ע וכמ\"ש כל הנקרא בשמי ולכבודי בראתיו",[["282","108","<b>בזהר . . שאלף הוא ר\"ת ארור</b>: ויגש רה, ב. ראה לקו\"ת פ' ראה יט, ב. סה\"מ תרל\"א ח\"א ס\"ע סא ואילך. וש\"נ. תר\"ם ח\"א ע' שו. וש\"נ. לקמן מאמר ד\"ה בגמ' וכו' קא מפלגי פ\"ב."],["283","109","<b>שא' . . לכל אותיות</b>: ראה מדרשים שבהערה 106."],["284","110","<b>אלף . . פלא</b>: ראה זהר בלק קצג, ב. ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'. שו\"ת אור זרוע בתחלתו אלפא ביתא א ס\"ג."],["285","111","<b>פלא בחי' כתר</b>: ראה תיקונים לז\"ח צח, ד."],["286","112","<b>שממית בידים תתפש</b>: משלי ל, כח."],["287","113","<b>כחשיכה כאורה</b>: ראה לקמן מאמר ד\"ה מגילה נקראת הערה 201."],["288","114","<b>ברכה . . חכמה</b>: ראה ערה\"כ לבעל סה\"ד מערכת חכמה."],["289","115","<b>שת\"י בראשית בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["290","116","<b>בחכ' יבנה בית . . בי\"ת</b>: משלי כד, ג. ראה גם סה\"מ תר\"ם ח\"א ע' שז. וש\"נ."],["291","117","<b>שמאה . . בינה</b>: ראה גם כסא מלך סתי\"ג אות ק. אוה\"ת שמות ע' פב. וראה גם סה\"מ תרל\"ג ח\"ב ע' תיז. וש\"נ."],["292","118","<b>והתגלות ע\"י הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי כרך א ע' שסד."],["293","119","<b>הדבור הוא ביצירה</b>: ראה בסמוך בפנים ובהערה 121."],["294","120","<b>כל מצוה . . מח' ודבור ומעשה</b>: ראה לקו\"ת חוקת נז, א. פינחס עה, א. סידור שחרית לא, ג ואילך. אוה\"ת חוקת מהדורת תשנ\"ח ע' תשנט. וראה גם לקו\"ש ח\"ז ע' 362.\nראה ספר הגלגולים פ\"ד. מ\"ח מסכת חיוב הנשמות פ\"א, מ\"א. הל' ת\"ת לאדה\"ז פ\"א, ס\"ד. אגה\"ק סכ\"ט. לקו\"ש קרח כרך יח ע' 192 הערה 55."]]],[2001910095,"יצרתיו אף עשיתיו<sup data-n=\"295\">121</sup>, בראתיו הוא בחי' מח', יצרתיו הוא בחי' דבור אף עשיתיו הוא בחי' עשי', והנה ע\"י כוונה של המצוה שהיא בחי' מח' נמשך בבריאה שהוא עולם המח', וע\"י הברכה של המצוה שהוא בחי' דבור נמשך בעולם היצי', וע\"י מעשה המצוה נמשך בעולם העשי'<sup data-n=\"296\">122</sup>, והיינו לפי שכדי שיומשך למטה צריך למשוך ממקום עליון יותר<sup data-n=\"297\">123</sup>, ולכן כדי שיומשך ממקום גבוה זהו מתעורר ע\"י מעשה דוקא לפי שמעשה ממשיך ממקום גבוה יותר וכמו שארז\"ל ודי לחכימא ברמיזא<sup data-n=\"298\">124</sup>, והיינו שכשהשכל עמוק מאד שא\"א לגלות אותו בדבור אזי ע\"י הרמיזא שהוא מעשה נרמז השכל, ומבין אותו ע\"י הרמיזא נמצא שיש כח במעשה שלמעלה מבחי' דבור, וז\"ע המצות שהם רק בחי' רמז למצות עליונות<sup data-n=\"299\">125</sup> כמו למשל תפילין שלנו הם רק בחי' רמז למה שהקב\"ה מניח תפילין<sup data-n=\"300\">126</sup> כי תפילין הם ד' מוחין<sup data-n=\"301\">127</sup> קדש בחי' חכ' והי' כי יביאך בחי' בינה ותפילין שלנו שהם ד' פרשיות הם רמז לד' מוחין עליונים, וכן ל\"ב חוטין דציצית שהם מצמר, הנה הצמר רומז לבחי' ושער רישי' כעמר נקי<sup data-n=\"302\">128</sup>, ול\"ב חוטין ל\"ב נ\"ח<sup data-n=\"303\">129</sup>, וכן כתי' ואתא<sup data-n=\"304\">130</sup> מרבבות קדש ששרש האותיות הם בבחי' רבבה<sup data-n=\"306\">132</sup> כו', כי יש בחי' יחידות עשירות מאות אלפים ורבבות, ואלפים הם",[["295","121","<b>כל הנקרא בשמי . . עשיתיו</b>: ישעי' מג, ז. ראה לקו\"ת בלק סז, א. סט, ד. תו\"ח בשלח ח\"א קמד, ב. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תא. וש\"נ."],["296","122","<b>מעשה . . בעולם העשי'</b>: והגם שנת\"ל שע\"י מאה ברכות נמשך גם בעשי' כו', י\"ל דזהו רק שנמשך רק מדרי' א' בעשי', וע\"י המעשה נמשך בחי' עצמות האור בעשי' — סה\"מ עזר\"ת כאן ע' קכז."],["297","123","<b>שכדי שיומשך למטה . . עליון יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["298","124","<b>ודי לחכימא ברמיזא</b>: ראה רשב\"ם ח\"ש כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב."],["299","125","<b>המצות . . רמז למצות עליונות</b>: ראה גם לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א. וש\"נ."],["300","126","<b>שהקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם תו\"א מקץ לה, ב ואילך. סה\"מ תרכ\"ז ע' מה. וש\"נ. ע' קיא. וש\"נ. תרל\"ג ח\"ב ע' תלד. וש\"נ. לקמן מאמר ד\"ה הוא אהרן ומשה על יד הערה 118. ד\"ה ועבדתם את ה\"א פ\"ד."],["301","127","<b>תפילין הם ד' מוחין</b>: ראה זהר ואתחנן רסב, א. פע\"ח שער התפילין שער ד, פ\"א ואילך. סידור שער התפילין ז, א. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ. תו\"ח נח עח, ד הערה 34."],["302","128","<b>ושער רישי' כעמר נקי</b>: ע\"פ דניאל ז, ט. ראה גם סה\"מ תרכ\"ז ע' תכא. תרל\"ג ח\"א ע' לה."],["303","129","<b>ול\"ב חוטין ל\"ב נ\"ח</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. לקו\"ת קרח נב, ב. ד."],["304","130","<b>ואתא</b>: וכ\"ה בחגיגה טז, רע\"א. יל\"ש בשלח רמז רמב. בהנחות ומאמרי כ\"ק אדה\"א. ובמאמרי אדה\"ז תקס\"ב ח\"א ע' מא (הועתק גם באוה\"ת יו\"כ ע' א'תקעד) מפרש הא' השני (שבתיבת ואתא).\n(לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 117. בלקו\"ת ר\"פ ברכה. ועוד: ואתה. אבל ראה לקו\"ת הוספות לויקרא נא, א. שה\"ש ה, ב."],["306","132","<b>ששרש האותיות . . רבבה</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לו. ע' מא. בוך בש\"ו 1063 כאן ע' קפג."]]],[2001910096,"בבחי' חכ'<sup data-n=\"307\">133</sup> וכמ\"ש אאלפך חכ'<sup data-n=\"308\">134</sup> ורבבות הם בכתר<sup data-n=\"309\">135</sup>, וזהו ואתא מרבבות קדש<sup data-n=\"305\">131</sup> ששרש האותיות הם מבחי' רבבה, לפי שאותיות הם בחי' אחרונה בחי' מעשה כו' (ויש עוד הרבה משלים ע\"ז כמו מענין אותיות החותם שאינם ניכר היטב כ\"א ע\"ג שעוה<sup data-n=\"310\">136</sup> דוקא וכן מענין פני ארי' ופני שור<sup data-n=\"311\">137</sup> שלמעלה פני ארי' הוא למעלה מבחי' פני שור כו', ואעפ\"כ למטה נעשים מבחי' פני ארי' חי' טמאה<sup data-n=\"312\">138</sup> כו', אלא שזהו כחותם המתהפך<sup data-n=\"313\">139</sup> כו', וכן מענין המשכת טפה גשמי' דוקא שנמשכת מעצמי' המוחין שלמעלה מבחי' השפעת השכל בדבור וכמ\"ש בד\"ה הקבצו ושמעו בני יעקב<sup data-n=\"314\">140</sup> כו', וש\"נ, וכידוע) וזהו שהמצות נק' בשם זריעה, והיינו כמו למשל הזריעה<sup data-n=\"315\">141</sup> שרוב מיני זריעה הוא זרעוני גינה שאין נאכלין שהוא רק גרעין שאין בו שום טעם מאכל וכשזורעין הגרעין בארץ ומתלבש בו כח הצומח שבארץ יצמח מזה פרי מאכל הגם שלא הי' עצם הגרעין בחי' מאכל כלל, וגם בתבואה מתוסף הרבה וכנ\"ל, וכ\"ש נטיעה שהגרעין שנוטעין אין בו ממהות האילן כלל, ואעפ\"כ אנו רואים שע\"י שנוטעין הגרעין בארץ נצמח ממנו אילן עם פירות שיש בהם טעם ותענוג כו' וע\"כ צריך לומר שיש בהגרעין בהעלם כל מהות האילן<sup data-n=\"316\">142</sup> שהרי בלתי גרעין לא הי'\n\n<i>בבוך 1108 בסיום המאמר נרשם:</i>\nמ\"ש אאלפך חכ', א\"כ גם אאלפך בינה[ftnref_8171_ח], ולמה נת\"ל שמאה בבינה ששם התגלות עת\"י, י\"ל שבינה שבאצי' הוא תרדל\"מ[ftnref_8172_ט] עם החכ' לכן שם גם בבינה אלפי', אבל ענין מאה זהו כמו שאימא מקננא בבריאה[ftnref_8173_י], שאם היות שגם שם התגלות עת\"י בבחי' בינה זו, מ\"מ הלא נודע שבמ\"א נת' שכערך ההפרש שבין בריאה לגבי האצי' כן ההפרש בין חכ' לבינה[ftnref_8174_יא] מטעם זה כו', וא\"כ לא יקשה כלום מדוע מאה בבינה כו'.",[["307","133","<b>ואלפים . . חכ'</b>: ראה גם כסא מלך סתי\"ג אות ק. אוה\"ת בראשית כרך ג' ריש ע' 1134. סה\"מ תרל\"א ח\"א ע' רפט. וככה תרל\"ז פקי\"ז. סה\"מ תרל\"ח ע' קפח."],["308","134","<b>אאלפך חכמה</b>: איוב לג, לג [ושם: ואאלפך]."],["309","135","<b>ורבבות הם בכתר</b>: ראה כסא מלך סתי\"ג אות ק. סה\"מ תרל\"ח ע' סד. וש\"נ."],["305","131","<b>ואתא מרבבות קודש</b>: ברכה לג, ב."],["310","136","<b>אותיות החותם . . ע\"ג שעוה</b>: ראה מאמרי אדה\"ז כתובים ח\"א ע' נז. אוה\"ת שמות ע' פו. וארא ע' רב. ע' ריד. שה\"ש ע' קא."],["311","137","<b>פני ארי' ופני שור</b>: ראה יחזקאל א, י."],["312","138","<b>פני ארי' חי' טמאה</b>: ראה אוה\"ח אחרי יז, יד. תו\"א וישלח כה, ג. סה\"מ תר\"ם ח\"א ע' כג. וש\"נ."],["313","139","<b>כחותם המתהפך</b>: ראה גם אגה\"ק ס\"כ (קלא, א). סה\"מ תר\"ם ח\"ב ע' תתטו הערה 78."],["314","140","<b>בד\"ה הקבצו ושמעו בני יעקב</b>: נדפס לפני מאמר זה ושם פ\"א."],["315","141","<b>כמו למשל הזריעה</b>: השוה תו\"א שמות נג, ד."],["316","142","<b>שיש בהגרעין . . האילן</b>: ראה גם תו\"ח בראשית כח, ג ובהערה 37. שער האמונה צב, א ובהערה 7. סה\"מ תר\"ם ח\"א ע' שטז וע' תמט.\n\n[ftn_8171_ח])אאלפך בינה: נסמן לקמן מאמר ד\"ה הוא אהרן ומשה הערה 111.\n\n[ftn_8172_ט])תרדל\"מ: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8.\n\n[ftn_8173_י])שאימא מקננא בבריאה: ת\"ז ת\"ו כג, א. ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ג. שער דרושי כללות אבי\"ע שמ\"ב, פי\"ג. תניא פל\"ט.\n\n[ftn_8174_יא])שכערך ההפרש . . בין חכ' לבינה: לקו\"ת סוכות פ, ב."]]],[2001910097,"נצמח מהארץ כ\"א עשבים או אילני סרק כו' וכדומה וע\"י הגרעין דוקא מצמיח הארץ אילן מוציא פירות הבלתי יערי כו', א\"כ מוכרח לומר שיש בכח בהעלם בגרעין כל מהות האילן וכו', וכמו\"כ הוא מעשה המצות שנק' בשם זריעה וכמ\"ש אור זרוע לצדיק היינו ששרש המצות הם מבחי' אור בחי' תר\"ך עמודי אור<sup data-n=\"317\">143</sup> וירדו ונתלבשו בדברים גשמים כמו תפילין על קלף גשמי וציצית מצמר גשמי וכדומה בשאר המצות כו' שאינם בערך כלל מכמו שהיו בשרשן בחי' תר\"ך עמודי אור אלא שהוא למשל כמו הזריעה שאע\"פ שאינו בערך אל האילן הנצמח ממנו, אעפ\"כ ע\"י הגרעין נצמח האילן וכמו\"כ מעשה המצות שאע\"פ שהם מלובשי' בדברים גשמי' אעפ\"כ ע\"י המצות נצמח אח\"כ בחי' תר\"ך עמודי אור כו', אך מ\"מ זהו דוקא כשאיש הישראלי עושה המצות כמו כשאיש ישראל מניח תפילין<sup data-n=\"318\">144</sup> על ראשו אז נתהוה ע\"י המצוה בחי' גילוי אלקותו ית', והיינו לפי שהוא כמו למשל הזריעה שאף שע\"י הגרעין נצמח הפרי אעפ\"כ צריך לזרוע הגרעין בארץ דוקא, ובלא ארץ לא יצמח מן הגרעין כלום, וגם צריך שיהי' הארץ מקום הראוי לזריעה, אבל במקום שאינו ראוי לזריעה אעפ\"י שיזרעו את הגרעין בארץ לא יצמח כלום, וכמו למשל עפר המדבר שאינו ראוי לזריעה<sup data-n=\"319\">145</sup>, וכך המצות שנק' בשם זריעה צריך לזרוע בארץ דוקא, ונש\"י נקראו בשם ארץ חפץ וכמ\"ש (מלאכי ג' י\"ב) ואשרו כו' כי תהיו אתם ארץ חפץ, חפץ הוא בחי' המצות, וכמ\"ש ה' חפץ למען צדקו<sup data-n=\"320\">146</sup>, וכל חפצים לא ישוו בה<sup data-n=\"321\">147</sup> שקאי על המצות שנקראו בשם חפץ לפי שהם בחי' פנימי' רצונו<sup data-n=\"322\">148</sup> ית', וחפץ זה מלובש בארץ דוקא שהם נש\"י כשישראל דוקא מקיים את המצות אזי יהי' מזה צמיחה, משא\"כ כשהתפילין מונחים על השולחן, וכן כשיניחם<sup data-n=\"323\">149</sup> מי שאינו מצווה ועומד מה\"ס<sup data-n=\"324\">150</sup> לא יצמח מזה שום גילוי כלל (ואפי' בישראל זהו דוקא כשמניח התפילין על ראשו והציצית בבגדו של ד' כנפות, משא\"כ כשמניח התפילין על פס ידו או על בטנו<sup data-n=\"325\">151</sup> לא יצמח מזה ג\"כ כלום והיינו לפי שהוא כמשל הזריעה שיש מקום שמיוחד לצמיחת גפנים, ויש מקום שמיוחד לצמיחת זתים<sup data-n=\"326\">152</sup> כו',",[["317","143","<b>ששרש המצות . . תר\"ך עמודי אור</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32. תקוני זהר חדש צו, ד. לקו\"ת להאריז\"ל משלי יא."],["318","144","<b>כשאיש הישראלי . . תפילין</b>: ראה תו\"א שם. סה\"מ תר\"ם ח\"א ע' שא. וש\"נ."],["319","145","<b>עפר המדבר . . לזריעה</b>: ראה חולין פח, ב. לקו\"ת מסעי צא, ב."],["320","146","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא. כתוב זה הובא במדרש שבהערה 70."],["321","147","<b>וכל חפצים לא ישוו בה</b>: משלי ח, יא. ראה מוע\"ק ט, ב."],["322","148","<b>חפץ . . פנימי' רצונו</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). לקו\"ת שה\"ש כח, ד. וש\"נ. תו\"ח בא ח\"א קכה, ד ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["323","149","<b>כשהתפילין מונחים על השולחן וכן כשיניחם</b>: ראה גם מאמר ד\"ה הבאים ישרש תשמ\"ג נעתק בחלקו במ\"מ לתו\"א שם."],["324","150","<b>וכן כשיניחם . . מה\"ס </b> [ מהר סיני]<b></b>: ראה תו\"א שם: וגם כשעכו\"ם מניח אותם. ועד\"ז בבוך בש\"ו 1063 כאן קפג, ב. ראה גם סה\"מ תר\"ם ח\"א ע' שב. וש\"נ."],["325","151","<b>כשמניח התפילין . . על בטנו</b>: עד\"ז בבוך בש\"ו. אוה\"ת שמות ע' פז. סה\"מ תרס\"ג כאן ע' קיז. עזר\"ת כאן ע' קכח. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 151."],["326","152","<b>מקום שמיוחד . . גפנים . . זתים</b>: ראה שבת פה, א."]]],[2001910098,"וכך שאעפ\"י שישראל נק' ארץ חפץ אעפי\"כ לא בכל מקום שיניח התפילין יהי' מזה צמיחה כ\"א שיניח התפילין ש\"י ע\"ג היד ותש\"ר על ראשו דוקא אז יהי' מזה צמיחה כו') ומה שנש\"י דוקא נק' ארץ חפץ היינו לפי שבנש\"י יש בהם בחי' ביטול בבחי' אתכפי' ואתהפכא ועי\"ז נק' ארץ חפץ שע\"י יוצמח גילוי בבחי' הפנימיות דוקא כו'.\n(ה) <b>וזהו</b> מ\"ש וזאת המצוה החוקים כו' לעשות בארץ<sup data-n=\"327\">153</sup>, שקאי על מצות ק\"ש<sup data-n=\"328\">154</sup> שנאמר אח\"כ, דלכאורה אינו מובן מה שייך מצות ק\"ש לארץ<sup data-n=\"329\">155</sup> שהרי ק\"ש הוא חובת הגוף<sup data-n=\"330\">156</sup> בכ\"ע ובכ\"ז<sup data-n=\"331\">157</sup>, ומה שייך ק\"ש להארץ, אך הענין דלכך נא' בק\"ש וזאת המצוה כו' לעשות בארץ, לפי שע\"י מצות ק\"ש עי\"ז הם נעשים בחי' ארץ שיוכל אח\"כ להיות בחי' צמיחה מהמצות, דהנה ארז\"ל למה קדמה פ' שמע לוהא\"ש<sup data-n=\"332\">158</sup> כדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עומ\"צ, והיינו לפי שהמצות צריך לקיים בבחי' עול<sup data-n=\"333\">159</sup> ולא בבחי' מצות אנשים מלומדה<sup data-n=\"334\">160</sup>, ולזה צריך לקבל עליו עומ\"ש תחלה, וע\"י עומ\"ש הם נעשים בחי' ארץ ואח\"כ יקבל עליו עול מצות שאז יכול להיות שיהי' השרשה וצמיחה במצות, משא\"כ בלתי קעומ\"ש לא יצמח כלום מהמצות ולזה נא' במצות ק\"ש בארץ לפי שע\"י ק\"ש הם נעשים בחי' ארץ כו', ואז ע\"י עשייתם דוקא במעשה המצות גשמי' דוקא יוכל להתהוות בחי' צמיחה הנ\"ל. וזהו סוף דבר, דהנה בברכת ק\"ש אנו מבקשים ותן בלבינו בינה להבין<sup data-n=\"335\">161</sup>, ונודע כי פי' בינה להבין דבר מתוך דבר<sup data-n=\"336\">162</sup>, תוך דבר הוא ממכ\"ע, ודבר הוא בחי' סוכ\"ע<sup data-n=\"337\">163</sup>, וזהו סוף הוא שיתגלה בחי' דבר הוא בחי' סוכ\"ע, וז\"ע כל עבודת האדם בירידת הנשמה בגוף שיומשך ע\"י עבודתו בחי' זה שנת\"ל<sup data-n=\"338\">164</sup> כו', ואיך יהי' גילוי ד\"ז הוא ע\"י ואת מצותיו שמור<sup data-n=\"339\">165</sup>, שהם הזריעה כמ\"ש ברבות זרע הקב\"ה כנ\"ל, והזריעה היא באדם ואיך יהי' האדם כלי לזה זהו ע\"י קבעומ\"ש שזה\"ע את האלקים ירא כו' קדימת שמע שהוא כענין הקדמת נעשה<sup data-n=\"340\">166</sup> דוקא כו'. וזהו מ\"ש קדש ישראל לה' ראשית תבואתו, שישראל הם בחי'",[["327","153","<b>וזאת המצוה . . לעשות בארץ</b>: ואתחנן ו, א."],["328","154","<b>וזאת המצוה . . ק\"ש</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בתחילתו. וש\"נ."],["329","155","<b>מה שייך . . לארץ</b>: ראה גם לקו\"ת תצא מ, סע\"ד. סה\"מ תר\"ם ח\"א ע' רסא. וש\"נ."],["330","156","<b>ק\"ש הוא חובת הגוף</b>: ראה קדושין לז, א וברש\"י שם. וראה גם לקו\"ש עקב כרך ט ע' 80 ואילך ובהערות שם. אחרי כרך יז ע' 190."],["331","157","<b>בכ\"ע ובכ\"ז</b>: כ\"ה בגוכתי\"ק. בסה\"מ עזר\"ת כאן: בכ\"מ ובכ\"ז."],["332","158","<b>למה קדמה פ' שמע לוהא\"ש</b>: ראה ברכות פ\"ב, מ\"ב (יג, א)."],["333","159","<b>שהמצות צריך לקיים בבחי' עול</b>: ראה לקו\"ת שלח לט, א. מ, א. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי פ\"ו."],["334","160","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם תניא פל\"ט (נג, ב). סה\"מ תר\"ם ח\"א ע' שט. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן פיסקא ומכ\"ז יובן."],["335","161","<b>ותן בלבינו בינה להבין</b>: ברכת אהבת עולם. ראה מאמר ד\"ה זה משנת תרס\"ט בסה\"מ ליקוט ח\"ג ע' קפ-קפא."],["336","162","<b>בינה להבין דבר מתוך דבר</b>: ראה חגיגה יד, א. תניא פ\"ג. אגה\"ק סט\"ו (קכד, רע\"א). וראה גם סה\"מ תרכ\"ט ע' רטז. וש\"נ."],["337","163","<b>תוך דבר הוא ממכ\"ע ודבר . . סוכ\"ע</b>: ראה סה\"מ תרל\"ח ע' רכב ואילך ובהנסמן שם."],["338","164","<b>שנת\"ל</b>: פ\"א."],["339","165","<b>ואת מצותיו שמור</b>: קהלת יב, יג."],["340","166","<b>הקדמת נעשה</b>: שבת פח, א. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רח. ש\"א נט, ב. מאמרי אדה\"א נ\"ך ע' רסא. סה\"מ תרכ\"ט ע' רנג. תר\"ם ח\"ב ע' תתלג."]]],[2001910099,"ראשית לתבואה כי תבואה הם בחי' תומ\"צ<sup data-n=\"341\">167</sup> וכמ\"ש ברבות ויתן לך האלקים<sup data-n=\"343\">169</sup> מטל השמים זה מקרא ומשמני הארץ זה משנה<sup data-n=\"344\">170</sup> ורוב דגן הם הלכות<sup data-n=\"345\">171</sup> ותירוש הם אגדות<sup data-n=\"342\">168</sup> שנק' בשם תבואת הארץ, וישראל הם ראשית לתבואה זו לפי שישראל הם בחי' ארץ חפץ שע\"י מצמיח התבואה ובלתי הארץ לא הי' שום צמיחה מהתבואה לכך הם ראשית לתבואה זו, שהם תבואת הארץ ופרי העץ שנת\"ל במשל<sup data-n=\"346\">172</sup>, וכ\"ה בנמשל ע' בד\"ה כי תבואו כו' ושבתה<sup data-n=\"347\">173</sup> בענין שעורה שיעור ה'<sup data-n=\"348\">174</sup> תבואת הארץ, שז\"ע חג הפסח, כמארז\"ל בפסח על התבואה<sup data-n=\"349\">175</sup>, חדש האביב<sup data-n=\"350\">176</sup>, אביב זמן בישול שעורים<sup data-n=\"351\">177</sup>, וענין אביב הוא אב י\"ב<sup data-n=\"352\">178</sup>, שי\"ב רומז לי\"ב שבטים מרכבתא תתאה דבריאה<sup data-n=\"353\">179</sup> כו', וחדש ניסן הוא אב לי\"ב חדשים<sup data-n=\"354\">180</sup> שהוא החדש הראשון<sup data-n=\"355\">181</sup>, ונק' החדש הזה<sup data-n=\"356\">182</sup> לפי שבו נגאלו אבותינו ממצרים והי' בו אותות ומופתים יוצאים מדרכי הטבע לגמרי כו', ופרי העץ ז\"ע חג השבועות שארז\"ל בעצרת על פירות האילן<sup data-n=\"357\">183</sup>, ורומז לבחי' כי האדם עץ השדה<sup data-n=\"358\">184</sup>, ואתם קרוים אדם<sup data-n=\"359\">185</sup> ע\"י קבעומ\"ש וקבעומ\"צ כו', וגם חטה ך\"ב אתוון דאורייתא<sup data-n=\"360\">186</sup> וכמ\"ד עה\"ד חטה היתה<sup data-n=\"361\">187</sup>, וב' בחי' אלו נכללו בלשון הפסוק בשם תבואתה בה' ונקוד חולם שי\"ל שהכוונה הוא על ב' בחי' הנ\"ל כו', ומ\"מ כתי' בה' כי תבואת הארץ כולל גם פרי העץ שלכן בשבועות זמן שתי הלחם<sup data-n=\"362\">188</sup> מטעם הנ\"ל דעה\"ד ולשארי מפרשים",[["341","167","<b>תבואה . . תומ\"צ</b>: ראה גם ערה\"כ לבעל סה\"ד מערכת תבואה."],["343","169","<b>ויתן לך האלקים</b>: תולדות כז, כח."],["344","170","<b>ומשמני הארץ זה משנה</b>: ראה לקו\"ת נשא כז, ד."],["345","171","<b>ורוב דגן הם הלכות</b>: ראה מאמרי אדה\"א דברים ח\"א ס\"ע רמד ואילך. אמרי בינה שער הק\"ש פנ\"ג."],["342","168","<b>וכמ\"ש ברבות . . הם אגדות</b>: ראה ב\"ר פס\"ו, ג (בשינויים קלים). יל\"ש עה\"פ רמז קטו."],["346","172","<b>שנת\"ל במשל</b>: פ\"ד."],["347","173","<b>בד\"ה כי תבואו כו' ושבתה</b>: סה\"מ תר\"ל ע' קלג."],["348","174","<b>שעורה שיעור ה'</b>: זהר בלק קפח, ב."],["349","175","<b>בפסח על התבואה</b>: ר\"ה פ\"א, מ\"ב (טז, א)."],["350","176","<b>חדש האביב</b>: משפטים כג, טו. תשא לד, יח. פ' ראה טז, א."],["351","177","<b>אביב זמן בישול שעורים</b>: ראה מנחות סח, ב. אבן עזרא משפטים כג, טז. לקו\"ש משפטים כרך לו ע' 109 ואילך."],["352","178","<b>אביב . . אב י\"ב</b>: ראה גם בחיי בא יג , ד. אוה\"ת בא ע' רסא. משפטים ע' א'קפא. פינחס ע' א'רטו. סה\"מ תר\"ל ריש ע' קלד. ע' רח. תרל\"ג ח\"א ע' קמט. תרל\"ו ח\"ב ע' שס. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 182. לקמן מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים פ\"ו (ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 33)."],["353","179","<b>לי\"ב שבטים מרכבתא תתאה דבריאה</b>: ראה תו\"א ויקהל קטו, ג. לקו\"ת צו יז, ב. סה\"מ תרל\"ח ע' יח. וש\"נ. לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ספ\"ב."],["354","180","<b>וחדש ניסן הוא אב לי\"ב חדשים</b>: ראה בחיי בא יג, ד."],["355","181","<b>ניסן . . שהוא החדש הראשון</b>: בא יב, ב וברש\"י שם. מג\"א ג, ז."],["356","182","<b>ונק' החדש הזה</b>: בא שם."],["357","183","<b>בעצרת על פירות האילן</b>: ר\"ה פ\"א, מ\"ב (טז, א)."],["358","184","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["359","185","<b>ואתם קרוים אדם</b>: יבמות סא, א. ראה גם תו\"ח יתרו ח\"ב רסב, א ואילך ובהערה 285. סה\"מ מלוקט ו' ע' פג. וש\"נ."],["360","186","<b>חטה ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["361","187","<b>עה\"ד חטה היתה</b>: ברכות מ, סע\"א. ראה גם לקו\"ת צו יז, ד. מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["362","188","<b>בשבועות זמן שתי הלחם</b>: אמור כג, טו ואילך. סהמ\"צ להרמב\"ם מ\"ע מו. רמב\"ם הל' תמידין ומוספין רפ\"ח."]]],[2001910100,"ופוסקים גם מצד הבאת ביכורים<sup data-n=\"363\">189</sup> כו', ומ\"מ לענין ברכת פרי העץ יוצא בדיעבד כשבירך בפה\"א<sup data-n=\"364\">190</sup> לבד בפרטי' כו'<sup data-n=\"365\">191</sup> ולכן כתי' תבואתה, וגם י\"ל שהה\"א רומז על חמשה חומשי תורה, והוא\"ו שנלמד מניקוד החולם היינו בחי' שיתא סדרי משנה כו', וזהו קדש ישראל שכל ענין ירידת הנשמה בגוף היא צורך עלי'<sup data-n=\"366\">192</sup>, והעלי' היא שיתעלו להיות בחי' ואנשי קדש תהיון לי<sup data-n=\"367\">193</sup> שזהו ע\"י קבעמ\"ש ועומ\"צ שזהו בחי' התבואה הנ\"ל, ולכן הם ראשית לתבואה זו דתומ\"צ הנ\"ל כו', וזהו מ\"ש מלך לשדה נעבד<sup data-n=\"368\">194</sup>, ששדה הוא מדריגה גבוה מאד שאפי' מלך נעבד ג\"כ לשדה עבדית ארעא או לא עבדית ארעא<sup data-n=\"369\">195</sup>, לפי שהעיקר הוא השדה, ולכך נק' ישראל ראשית תבואתו. וזהו* מ\"ש אשריכם זורעי על כל מים<sup data-n=\"370\">196</sup> שהזריעה צריך למים וזריעת המצות הם על כל מים דהיינו אפילו על מים שבג\"ע שנא' ונהר יוצא מעדן<sup data-n=\"371\">197</sup> להשקות את הגן, וזריעת המצות הם אפי' על מים שבג\"ע וכמ\"ש ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"372\">198</sup>, וגם י\"ל על כל מים היינו למעלה גם מבחי' מים אלו שבג\"ע וכמ\"ש לכל תכלה ראיתי קץ רחבה מצותך מאד<sup data-n=\"373\">199</sup>, וכל תכלה הוא ע\"ד מ\"ש ויכולו השמים והארץ<sup data-n=\"374\">200</sup>, ששמים וארץ הוא בחי' געה\"ת וגעה\"ע<sup data-n=\"375\">201</sup> שהם בבחי' כליון ותשוקה לשון כלתה נפשי<sup data-n=\"376\">202</sup> כו' ולכל תכלה ראיתי קץ שהם בבחי' קץ וגבול שלכל נשמה יש גבול להשגתה, משא\"כ מצותך רחבה מאד היינו שבחי' מצותך היא רחבה בבחי' כלי קיבול לקבל בחי' מאד בלי גבול<sup data-n=\"377\">203</sup>, שע\"י מעשה המצות יוכל לצמוח בבחי' גילוי בלי גבול, וזהו אשריכם זורעי על כל מים, היינו למעלה מבחי' מים שבג\"ע ונהר יוצא מעדן כו' וכנ\"ל.\n\n*) מכאן עד סיום המאמר העביר קו ובשולי היריעה נרשם בגוכתי\"ק:\nמן וזהו עד וכנ\"ל ל\"נ רק הועתק. וקטע זה הועתק גם בבוך תרמ\"א — 2086 כת\"י ר\"ש סופר.",[["363","189","<b>בשבועות זמן . . הבאת ביכורים</b>: ראה בכורים פ\"א, מ\"ג. סה\"מ תר\"ל כאן. סה\"מ מלוקט ה' ע' קסט הערה 10."],["364","190","<b>ברכת פרי העץ יוצא . . בפה\"א</b>: ברכות מ, א (במשנה). שו\"ע אדה\"ז הל' ברכת הפירות סר\"ו, ס\"א. סידור סדר ברכת הנהנין פ\"א, ה\"ד."],["365","191","<b>לבד בפרטי' כו'</b>: כ\"ה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן פיסקא וזהו קדש. סה\"מ תרנ\"ד כאן (ריש ע' קכד). ראה סידור שם ה\"ו [הובא בשו\"ע אדה\"ז שם, ס\"ב]."],["366","192","<b>ירידת . . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["367","193","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל."],["368","194","<b>מלך לשדה נעבד</b>: קהלת ה, ח. ראה זהר ח\"ש קכב, א ואילך. ביאוה\"ז שם קכט, ג ואילך. אוה\"ת ויצא כרך ה ס\"ע תתנח ואילך. ע' 1720 ואילך. ויגש כרך ה ע' תתקפד ואילך. שלח ע' תמו."],["369","195","<b>עבדית ארעא או לא עבדית ארעא</b>: ראה קה\"ר שם."],["370","196","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."],["371","197","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["372","198","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: שם ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["373","199","<b>לכל תכלה . . מצותך מאד</b>: תהלים קיט, צו. ראה גם אוה\"ת בראשית כרך ג ע' 1010 ואילך. סה\"מ תרס\"ו ע' כ."],["374","200","<b>ויכולו השמים והארץ</b>: בראשית ב, א."],["375","201","<b>ששמים וארץ . . געה\"ת וגעה\"ע</b>: ראה לקו\"ת פ' ראה כה, א. סה\"מ תרל\"ח ע' מו. וש\"נ."],["376","202","<b>כלתה נפשי</b>: תהלים פד, ג."],["377","203","<b>מאד בלי גבול</b>: ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."]]],[2001910101,"<h3>והי' אור הלבנה</h3>\n<b></b><b>בס\"ד ישעי' למד ךו ל\"נ</b>\n<b>והי'</b> אור הלבנה<sup data-n=\"378\">1</sup> כאור החמה<sup data-n=\"379\">2</sup>, ולהבין זה צ\"ל ענין סמיכת גאולה לתפילה<sup data-n=\"380\">3</sup>, דהנה כתי' והטוב בעיניך עשיתי<sup data-n=\"381\">4</sup>, וארז\"ל מאי והטוב בעיניך עשיתי שסמך גאולה לתפלה<sup data-n=\"382\">5</sup>, והענין הוא דהנה גאולה הוא בחי' יסוד<sup data-n=\"383\">6</sup>, דהנה יסוד נק' טוב<sup data-n=\"384\">7</sup> ע\"ש ההשפעה וכמ\"ש אמרו לצדיק כי טוב<sup data-n=\"385\">8</sup> וכתי' וצדיק יסוד עולם<sup data-n=\"386\">9</sup> וכתי' אם יגאלך טוב יגאל<sup data-n=\"387\">10</sup>, והיינו כי גאולה הוא בחי' התגלות אא\"ס, וע\"כ נק' טוב<sup data-n=\"388\">11</sup>, וכמ\"ש וירא אלקי' את האור כי טוב<sup data-n=\"389\">12</sup>, והשפעה זו היא ע\"י יסוד כי כל השפעה הוא ע\"י יסוד<sup data-n=\"390\">13</sup> כו', וע\"כ נק' גאולה יסוד כו', וסמיכות גאולה לתפלה היינו שיהי' השפעה זו בבחי' מל' כי מל' הוא בחי' תפלה<sup data-n=\"391\">14</sup> כי תפלה הוא מלשון התחברות כמו התופל כלי חרס<sup data-n=\"392\">15</sup>, דהנה מל' נעשה מקור לעולמות בי\"ע בע\"ג ואני תפילה<sup data-n=\"393\">16</sup> היינו שיהי' התחברות",[["378","1","<b>והי' אור הלבנה</b>: מאמר זה פרט להפתיחא והסיום נמצא בבוך בש\"ו 1063 ע' קצז ושם הפתיחא ולהבין בתוס' ביאור ענין ד' גאולות. סה\"מ תרל\"ד ע' קנד ושם הפתיחא מצה זו [וראה בהנסמן שם]. מאמר ד\"ה לכן אמור תרמ\"ב [יודפס בע\"ה בסה\"מ תרמ\"ב — והוא באו\"א קצת מכשנ\"ת בד\"ה והי' אור הלבנה תרמ\"א]. ובשינויים וכו' בסה\"מ תרנ\"ד ע' קכד. תרס\"ח ע' רלח. עת\"ר ע' רנא [ובמהדורת תשמ\"ה ע' דש].\nבוך בש\"ו הנ\"ל הוא הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים נק' בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד-תרט\"ו ע' שו-שז.\nבבוך זה 1130 הנה לפני מאמר זה בא ע' הוראות בגוכתי\"ק אדמו\"ר מהר\"ש איך להעתיק המאמר [מבוך בש\"ו הנ\"ל]. מאמר זה הוא כת\"י הר\"ש סופר פרט להסיום וכן איזה תיקונים שהם בגוכתי\"ק. בהכותרת כאן [וכמו\"כ בע' הוראות הנ\"ל] נרשם: ל\"נ לא נאמר. בבוך תרמ\"א 2086 — כת\"י מעתיק — לא העתיק את זה."],["379","2","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו (כנסמן בהכותרת כאן)."],["380","3","<b>סמיכת גאולה לתפילה</b>: ברכות ט, ב."],["381","4","<b>והטוב בעיניך עשיתי</b>: מלכים-ב כ, ג. ישעי' לח, ג."],["382","5","<b>שסמך גאולה לתפלה</b>: ברכות י, ב. ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' תקסה ובהנסמן במ\"מ לשם בח\"ב. מאמרי אדה\"א ויקרא ח\"א ע' שב. דברים ח\"ג ע' א'מ. וש\"נ.\nלעיל הערה 3 נכתב תיבת תפילה [ביו\"ד] משא\"כ מכאן ואילך. כי בהערה 3 הוא העתק מגוכתי\"ק [שנכתב בע' ההוראות — ראה לעיל הערה 1] משא\"כ כאן שהוא העתק מבוך בש\"ו, אף ששם כאן וכן לקמן נכתב תפילה [ביו\"ד], כנראה שלא דק בזה [וכיו\"ב] הר\"ש סופר."],["383","6","<b>גאולה . . יסוד</b>: ראה מאו\"א מערכת גאולה ס\"ד. אוה\"ת ויחי ח\"ב ע' 710. שלח ע' תרטו. בחוקותי ע' תרמא."],["384","7","<b>יסוד נק' טוב</b>: ראה זהר נח ס, א. מאמרי אדה\"א קונטרסים ע' רכד. וש\"נ."],["385","8","<b>אמרו לצדיק כי טוב</b>: ישעי' ג, י [ושם: צדיק — ראה גם לעיל מאמר ד\"ה קדש ישראל לה' על יד הערה ז. תו\"ח בשלח ח\"א קסו, ב. וש\"נ]."],["386","9","<b>וצדיק יסוד עולם</b>: משלי י, כה."],["387","10","<b>אם יגאלך טוב יגאל</b>: רות ג, יג."],["388","11","<b>גאולה . . התגלות אא\"ס . . טוב</b>: ראה גם סה\"מ תרס\"ח כאן ע' רלח. עת\"ר כאן ע' רנב ואילך."],["389","12","<b>וירא אלקי' . . טוב</b>: בראשית א, ד."],["390","13","<b>כל השפעה . . יסוד</b>: ראה גם סה\"מ תרנ\"ד כאן ע' קכד."],["391","14","<b>מל' . . תפלה</b>: ראה בסמוך הערה 16."],["392","15","<b>תפלה . . התופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה תו\"א תרומה עט, סע\"ד. סה\"מ תרל\"ח ע' רמב. וש\"נ. תר\"ם ח\"א ע' ש. וש\"נ. לקמן מאמר והנחה ד\"ה ועבדתם את ה\"א פ\"ג."],["393","16","<b>מל' . . ואני תפילה</b>: תהלים קט, ד. ראה זהר תזריע מט, ב. פע\"ח שער התפלה בתחלתו. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצב. סה\"מ תרכ\"ז ע' עב."]]],[2001910102,"הנפש המאיר בגוף עם שרש הנפש שאינה מתלבשת בגוף כלל (שהיא בחי' מזלי'<sup data-n=\"394\">17</sup> כו'), וזהו\"ע סמיכת גאולה לתפלה שיהי' השפעת היסוד בבחי' מל' דוקא ולכך אסור להפסיק בין גאולה לתפלה<sup data-n=\"395\">18</sup> אפי' היכא שמותר להפסיק בין הפרקים אעפ\"כ בין גאולה לתפלה אסור, והנה לפ\"ז משמע שגאולה הוא<sup data-n=\"396\">19</sup> למעלה מבחי' תפלה אבל לפעמים מצינו שתפלה היא למעלה, והענין הוא דבאמת תפלה הוא למעלה כו', אך כדי שיהי' העלאת התפלה זהו ע\"י סמיכות גאולה לתפלה שאומרים מקודם תהלות לאל עליון גואלם עי\"ז נעשה העלאת התפלה שהוא בחי' אתדל\"ע המעורר אתדל\"ת<sup data-n=\"397\">20</sup>, אבל אח\"כ ע\"י התפלה נעשה התחברות עצמות אא\"ס בבחי' מל'<sup data-n=\"398\">21</sup>, והנה כתי' המלאך הגואל אותי<sup data-n=\"399\">22</sup> כו' שא\"א לומר שקאי על מלאך נברא דאיך א' המלאך הגואל אותי כו' דאין זה בכח המלאך כו', אלא פי' המלאך הגואל קאי על בחי' מל' דאצי', שמל' נק' ג\"כ גואל. והענין הוא דהנה כשיש ריבוי ההשפעה בבחי' מל' מבחי' יסוד אזי עי\"ז נעשה מל' ג\"כ גואל. ועוד י\"ל כמ\"ש בזוהר דכד איהי שלוחא מלעילא<sup data-n=\"400\">23</sup> אזי נק' מלאך שניתוסף בה א' וא' הוא בחי' פלא<sup data-n=\"401\">24</sup> שהוא בחי' כתר<sup data-n=\"402\">25</sup>, וע\"כ ע\"י שמאיר בה בחי' כתר עי\"ז נעשה בחי' גואל כו'. וזהו המלאך הגואל אותי כו' וזה\"ע ד' גאולות<sup data-n=\"403\">26</sup> דהיינו מה שמל' נק' גואל ובחי' יסוד שנק' גאולה.\nב) <b>והנה</b> יש להבין ענין מספר ד' גאולות, הענין הוא דהנה כדי שיוכל להיות בחי' ד' גאולות והוצאתי והצלתי וגאלתי ולקחתי<sup data-n=\"404\">27</sup>, צריך שיהיה המשכה מקודם מבחי' חכמה כו', וזהו מ\"ש עד שנגלה עליהם מלך מלכי המלכים<sup data-n=\"405\">28</sup>, מלכים תרי מלכי תרי, דהנה מלכים הוא בחי' יסוד ומל'<sup data-n=\"406\">29</sup>, וכמ\"ש כי הנה המלכים נועדו<sup data-n=\"407\">30</sup>",[["394","17","<b>שרש הנפש . . מזלי'</b>: ראה שעה\"ק להרח\"ו ח\"ג, ש\"ה. לקו\"ת במדבר טז, א ואילך. תצא לו, ריש ע\"ב. האזינו עא, ד. שה\"ש טז, ד. סה\"מ תר\"ם ח\"א ע' קנה ואילך. וש\"נ."],["395","18","<b>אסור להפסיק בין גאולה לתפלה</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"ו, ס\"ט. ס\"י. הל' תפלה סקי\"א."],["396","19","<b>הוא . . היא . . הוא</b>: בבוך בש\"ו 1063 כאן: הוא . . הוא . . הוא. בסה\"מ תרל\"ד כאן ע' קנה: היא . . היא . . היא. ראה גם לעיל הערה 5 ד\"ה לעיל."],["397","20","<b>אתדל\"ע המעורר אתדל\"ת</b>: ראה תו\"א תצוה פב, סע\"א ואילך. לקו\"ת ויקרא ב, ב. וש\"נ."],["398","21","<b>התפלה . . עצמות אא\"ס בבחי' מל'</b>: ראה תו\"א ויחי מה, ג. מו, א."],["399","22","<b>המלאך הגואל אותי</b>: ויחי מח, טז. ראה גם סה\"מ תרנ\"ד כאן ע' קכו. עת\"ר כאן ע' רנה."],["400","23","<b>דכד איהי שלוחא מלעילא</b>: ראה זהר בלק קפז, א. ביאוה\"ז שם קמו, ג ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרצב ואילך. תקס\"ב ח\"ב ע' תפד ואילך. וע' תפט ואילך. תקס\"ז ע' רעא ואילך. אוה\"ת תשא ע' ב'ל ואילך."],["401","24","<b>וא' . . פלא</b>: ראה זהר בלק קצג, ב. ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'. שו\"ת אור זרוע בתחלתו אלפא ביתא א ס\"ג."],["402","25","<b>פלא . . כתר</b>: ראה תיקונים לז\"ח צח, ד."],["403","26","<b>ד' גאולות</b>: ראה לקמן רפ\"ב. בבוך בש\"ו 1063 ועד\"ז בסה\"מ תרל\"ד נזכרו ד' גאולות גם בתחילת המאמר."],["404","27","<b>והוצאתי . . ולקחתי</b>: וארא ו, ו. ז."],["405","28","<b>עד שנגלה . . המלכים</b>: נוסח ההגדה."],["406","29","<b>מלכים . . יסוד ומל'</b>: ראה אוה\"ת ויקרא כרך ג' ע' תשסט ואילך. סה\"מ תר\"ם ח\"א ע' קיט. וש\"נ. לקמן מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 95."],["407","30","<b>כי הנה המלכים נועדו</b>: תהלים מח, ה. זהר ויגש רו, א."]]],[2001910103,"זה יוסף ויהודה שהוא בחי' יסוד<sup data-n=\"408\">31</sup> ומל'<sup data-n=\"409\">32</sup>, ומלכי הוא בחי' חו\"ב<sup data-n=\"410\">33</sup>, והיינו שכדי שיהי' התגלות בחי' מלך מלכי המלכים שהוא בחי' התגלות עצמות אא\"ס צריך שיומשך ע\"י ד' בחי', וזהו ענין ד' אותיות ש' הוי'<sup data-n=\"411\">34</sup>. וזהו מ\"ש אז ראה ויספרה הכינה וגם חקרה<sup data-n=\"412\">35</sup> ויאמר לאדם<sup data-n=\"413\">36</sup>, שכשנמשכה למטה הוצרך להיות נמשך ע\"י ד' בחי'<sup data-n=\"414\">37</sup>, אז ראה הוא בחי' חכ' איזהו חכם הרואה את הנולד<sup data-n=\"415\">38</sup>, חכמים הם עיני העדה<sup data-n=\"416\">39</sup>, ויספרה הוא בחי' בינה, הכינה וגם חקרה הוא בחי' ז\"א ומל'<sup data-n=\"417\">40</sup>, והיינו לפי שכדי שיכול<sup data-n=\"418\">41</sup> להיות התגלות אא\"ס למטה הוצרך להיות נמשך ע\"י ד' אותיות ש' הוי' דוקא שהוא בחי' צמצום והתפשטות<sup data-n=\"419\">42</sup> המשכה והתפשטות כו', וזה\"ע ד' גאולות שהוא המשכה מבחי' חו\"ב וז\"א ומל'. ולהבין ענין זה בעבודה הענין הוא דהנה כתי' סור מרע ועשה טוב<sup data-n=\"420\">43</sup> בקש שלום ורדפהו, והנה ענין סור מרע דהנה כתי' עוונותיכם היו מבדילים ביניכם לבין אלקיכם<sup data-n=\"421\">44</sup>, דהנה אלקינו הוא בחי' כשמאיר אלקות בגילוי בנשמה, כמו שאנו אומרים אלקי אברהם<sup data-n=\"422\">45</sup> והיינו לפי שהי' מרכבה<sup data-n=\"423\">46</sup> לאלקות והי' מאיר אלקות בתוכם בגילוי ע\"כ נק' אלקי אברהם כו', וכן נק' אלקינו וכמ\"ש שמע ישראל הוי' אלקינו<sup data-n=\"424\">47</sup> כו', אך ע\"י עון נעשה מסך ומבדיל שלא יהי' מאיר אלקות בבחי' גלוי, וזה\"ע מסך מבדיל בחי' כתנות עור בעין<sup data-n=\"425\">48</sup> שמסתיר כו'. וזהו ענין מצות הסרת ערלה<sup data-n=\"426\">49</sup> כי ערלה הוא בחי' הסתר והעלם שמסתיר על בחי' גילוי אלקות וע\"כ צריך להסיר את הערלה כו', וזהו סור מרע שע\"י סו\"מ עי\"ז נק' אלקינו היינו שלנו שמאיר",[["408","31","<b>יוסף . . יסוד</b>: ראה זהר רע\"מ פינחס רלו, א. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יוסף."],["409","32","<b>ויהודה . . ומל'</b>: ראה זהר ויחי מז. א. הנסמן במאמרי אדה\"א בראשית ע' רצט."],["410","33","<b>ומלכי . . חו\"ב</b>: נסמן לעיל הערה 29."],["411","34","<b>ד' אותיות ש' הוי'</b>: ראה זהר רעיא מהימנא פינחס רמג, רע\"א. אגה\"ת פ\"ד."],["412","35","<b>אז ראה . . וגם חקרה</b>: איוב כח, כז."],["413","36","<b>ויאמר לאדם</b>: איוב שם, כח."],["414","37","<b>הוצרך . . ד' בחי'</b>: ראה לקו\"ת האזינו עא, ג. סה\"מ תרכ\"ט ע' שכז. וש\"נ. תרל\"ב ח\"א ע' נ. וש\"נ."],["415","38","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א."],["416","39","<b>חכמים הם עיני העדה</b>: שלח טו, ד. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. תו\"ח בא ח\"א קב, א ובהערה 248."],["417","40","<b>ויספרה . . בינה . . ומל'</b>: ראה סה\"מ תרס\"ח כאן ע' רמב ואילך."],["418","41","<b>שיכול</b>: כ\"ה בבוך בש\"ו 1063 כאן. תרנ\"ד כאן ע' קכז. בסה\"מ תרל\"ד כאן ע' קנה: שיוכל."],["419","42","<b>ד' אותיות . . צמצום והתפשטות</b>: ראה אגה\"ת פ\"ד. לקו\"ת נצבים מה, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתעז ואילך. סה\"מ תרל\"ח ע' קו. וש\"נ."],["420","43","<b>סור מרע ועשה טוב</b>: תהלים לד, טו. ראה (בנוסף להערה 1) לקו\"ת בלק עג, ב ואילך. סה\"מ תרנ\"ח ע' פז ואילך. תרע\"ח ע' קלט ואילך. תרפ\"ב ע' ב ואילך. תרפ\"ד ע' קצד ואילך. מאמר ד\"ה לכן אמור תשי\"ח. ד\"ה לכן אמור וד\"ה ועברתי באמ\"צ תשכ\"א. ד\"ה לכן אמור תשל\"ט."],["421","44","<b>עוונותיכם היו . . אלקיכם</b>: ישעי' נט, ב."],["422","45","<b>אלקי אברהם</b>: נוסח שמו\"ע."],["423","46","<b>אברהם . . מרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["424","47","<b>שמע . . אלקינו</b>: ואתחנן ו, ד."],["425","48","<b>כתנות אור בעין</b>: בראשית ג, כא. בב\"ר פ\"כ, יב: כתנות אור. ראה מאמרי אה\"א ויקרא ח\"ב ע' תצג. וש\"נ. שעה\"י קמ, א ואילך ובהערה 10. תו\"ח שמות ח\"א ח, ב."],["426","49","<b>מצות הסרת ערלה</b>: תזריע יב, ג. לך יז, י ואילך. ראה גם יבמות עא, ב. לקו\"ת תזריע כא, ב. סה\"מ תר\"ם ח\"א ע' רמד. וש\"נ."]]],[2001910104,"אלקי' בבחי' גילוי, אך הנה כ\"ז הגילוי הוא רק מבחי' ש' אלקי' שהוא בחי' מל'<sup data-n=\"427\">50</sup> בחי' ממכ\"ע, אך כדי שיהי' הגילוי מבחי' סוכ\"ע בחי' טוב בחי' יסוד זהו ע\"י ועשה טוב כו', שהוא בחי' מעשה המצות כו', וכמ\"ש מי האיש החפץ חיים<sup data-n=\"428\">51</sup> אוהב ימים לראות טוב שכדי שיראה בחי' טוב וירא אלקים את האור כי טוב כו' זהו ע\"י אוהב ימים שהוא בחי' יומין עילאין מעשה המצות לפי שבכל יום צריך לקיים את המצוה<sup data-n=\"429\">52</sup> וכאשר חסר יומא חדא חסר לבושא חדא<sup data-n=\"430\">53</sup>, ועי\"ז נמשך הגילוי מבחי' טוב שהוא בחי' סוכ\"ע את השמים ואת הארץ אני מלא<sup data-n=\"431\">54</sup> כו', ר\"ת את השמים ואת הארץ גימ' טוב<sup data-n=\"432\">55</sup>, שיהי' הוי' אלקינו שהוי' יהי' אלקינו דהיינו שהגילוי נמשך מבחי' ש' הוי' כו', וזהו ענין והוצאתי והצלתי, והוצאתי הוא בחי' סו\"מ שהוא להוציא מתחת סבלות מצרים<sup data-n=\"433\">56</sup> לצאת מהמצרים וגבולים<sup data-n=\"434\">57</sup> שמסתירים על בחי' גילוי אלקות והצלתי הוא בחי' ועשה טוב, כי בהצלתי יש שני פי' א' ל' הצלה, והב' ל' צל, וכמ\"ש במד\"ר ע\"פ כי ה' אלקיך מתהלך בקרב מחנך להצילך<sup data-n=\"436\">59</sup>, ופי' להיות צל על ראשך<sup data-n=\"435\">58</sup>, והיינו לפי שממעשה המצות נמשך בחי' מקיפים כו', וכמ\"ש ה' צלך על יד ימינך<sup data-n=\"437\">60</sup>, שע\"י ימינך שהוא בחי' מעשה המצות עי\"ז נעשה ה' צלך ואשים דברי בפיך ובצל ידי כסיתיך<sup data-n=\"438\">61</sup>, ואשים דברי בפיך הוא בחי' תורה<sup data-n=\"439\">62</sup>, ובצל ידי כסיתיך הוא בחי' מעשה המצות<sup data-n=\"440\">63</sup>, והנה עי\"ז שנמשך עליו בחי' מקיף עי\"ז נעשה הצלה ג\"כ לשמור מכל רע כי המקיף מסמא עיני החיצוני'<sup data-n=\"441\">64</sup> ומקיפו אותו מכל צד בכדי שלא יגיע עליו שום רע כו', ואח\"כ",[["427","50","<b>אלקי' . . מל'</b>: ראה זהר בראשית כב, א. אחרי סה, א. תו\"ח וארא ח\"א עה, ב הערה 202."],["428","51","<b>מי האיש החפץ חיים</b>: תהלים לד, יג."],["429","52","<b>שבכל יום . . המצוה</b>: ראה צוואת הריב\"ש [באגה\"ק סכ\"ה: ריב\"ש — ראה סה\"מ תרל\"ח ע' קעב. וש\"נ] ס\"א. סי\"ז. תו\"א משפטים עה, ד. מאמרי אדה\"א בראשית ס\"ע תלה ואילך. תו\"ח בשלח ח\"א קעו, א. סה\"מ מלוקט א' ע' רפט ואילך. לקו\"ש ח\"ד ע' 1193 ואילך ובהנסמן בהנ\"ל."],["430","53","<b>חסר יומא חדא חסר לבושא חדא</b>: כ\"ה בכ\"מ — ראה לקו\"ש ח\"ז ע' 331 שמציין זח\"א רכ\"ד א'. אוה\"ת בלק ע' תתקמח. וראה גם לקו\"ת יו\"כ סט, א. תו\"א ח\"ש טז, רע\"א. בהערה שלפנ\"ז."],["431","54","<b>את השמים . . מלא</b>: ירמי' כג, כד. ראה תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["432","55","<b>ר\"ת . . גימ' טוב</b>: ראה (בנוסף להערה 1) מאמרי אדה\"א דברים ח\"ג ע' תתקעד. וש\"נ. שמות ח\"ב ע' תפז. וש\"נ. קונטרסים ע' רכה. וש\"נ."],["433","56","<b>מתחת סבלות מצרים</b>: המשך הכתוב והוצאתי."],["434","57","<b>מצרים . . מהמצרים וגבולים</b>: ראה תו\"א בשלח סד, ב. סע\"ג. יתרו סז, סע\"ב. עא, ג."],["436","59","<b>כי ה' . . להצילך</b>: תצא כג, טו."],["435","58","<b>במד\"ר . . להצילך . . צל על ראשך</b>: ראה ויק\"ר פכ\"ד, ז־ ילקו\"ש ר\"פ קדושים רמז תרג [ושם: ראשו].\nאבל הלשון שבפנים הובא גם בילקוט ראובני תצא עה\"פ [אלא ששם חסרה תיבת: צל]. (בנוסף להערה 1) אוה\"ת וארא ע' רלז. סה\"מ תרל\"ב ח\"ב ע' תקפד [ושם: לעשות צל]. ע' תרלו. תרל\"ג ח\"ב ריש ע' תיז. תרע\"ח כאן ע' רמה."],["437","60","<b>ה' צלך . . ימינך</b>: תהלים קכא, ה."],["438","61","<b>ואשים דברי . . כסיתיך</b>: ישעי' נא, טז."],["439","62","<b>ואשים דברי . . תורה</b>: בסה\"מ תרע\"ח כאן ע' קמה: ירושלמי — ירושלמי תענית פ\"ד, סה\"ב."],["440","63","<b>ובצל ידי . . מעשה המצות</b>: ראה גם סה\"מ תרע\"ח כאן. תו\"א בראשית ב, ב. סה\"מ תרכ\"ז ע' רטו. ע' תצו. תרל\"ב ח\"א ע' נ. ע' ריב. לקו\"ת במדבר ב, ד."],["441","64","<b>המקיף מסמא עיני החיצוני'</b>: ראה מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לט]: כמ\"ש האריז\"ל שאור אבא מסמא. ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. סה\"מ תרל\"ח ע' שי ואילך. ע' תצט ואילך."]]],[2001910105,"כתי' בקש שלום ורדפהו בקש שלום הוא בחי' תורה וכמ\"ש או יחזיק במעוזי<sup data-n=\"442\">65</sup> יעשה שלום לי, שלום יעשה לי, שע\"י התורה נעשה שלום בפמליא שמ\"ע ובפשמ\"ט<sup data-n=\"443\">66</sup>, דהנה כי אל דעות הוי'<sup data-n=\"444\">67</sup> ד\"ע הוא שלמעלה היש ולמטה הוא אין<sup data-n=\"445\">68</sup>, וד\"ת הוא להיפך שלמעלה הוא האין ולמטה הוא היש, וע\"י התורה נמשך שיהי' גילוי בחי' ד\"ע בד\"ת שלמטה יהי' ג\"כ הגילוי שלמעלה הוא היש ולמטה הוא האין שכולו קמי' כל\"ח<sup data-n=\"446\">69</sup> כו'. והנה בתורה יש ג\"כ שני בחי' וכמ\"ש בזהר תלת קשרין<sup data-n=\"447\">70</sup> מתקשראן דא בדא ישראל באורייתא ואורייתא בקוב\"ה, וכולהו כו' סתים וגליא, וענין סתים וגליא שבישראל הוא בחי' יעקב וישראל<sup data-n=\"448\">71</sup> כו', ובאוריי' הוא בחי' חיצוני' התורה ופנימי' התורה<sup data-n=\"449\">72</sup>, וגם י\"ל שסתים שבתורה הוא בחי'<sup data-n=\"450\">73</sup> המאור שבה וכמ\"ש במד\"ר המאור שבה מחזירן למוטב<sup data-n=\"451\">74</sup> ואף שהמאור מלובש ג\"כ בתורה הנגלי' מ\"מ עיקר המאור הוא מלובש בפנימי' התורה, וזהו ענין ב' בחי' שבתורה, והנה עי\"ז ממשיך שיהי' בחי' אתה הוי' אלקינו שהוא בחי' עצמותו ומהותו, יהי' נמשך בבחי' הוי' אלקינו כו', וזהו ולקחתי אתכם לי לעם, וכ\"מ שנאמר לי<sup data-n=\"452\">75</sup> אינו זז לא בעוה\"ז ולא בעוה\"ב, לפי שהוא בחי' עצמותו ומהותו כו', וזהו ענין ד' גאולות שיש בנפש כו' שהוא ג\"כ כנגד ד' אותיות שם הוי'.\nג) <b>ועוי\"ל</b> שד' בחי' גאולות שבנפש זהו בחי' דחילו ורחימו רחימו ודחילו<sup data-n=\"453\">76</sup>, שהוא ג\"כ כנגד ד' אותיות שם הוי', דחילו הוא בחי' יר\"ת שהוא בחי' סו\"מ, כי יראה הוא שרש לשס\"ה ל\"ת, ורחימו הוא בחי' אהבה שהוא מקור ושרש לרמ\"ח מ\"ע<sup data-n=\"454\">77</sup>,",[["442","65","<b>או יחזיק במעוזי</b>: ישעי כז, ה."],["443","66","<b>שלום בפמליא שמ\"ע ובפמשמ\"ט</b>: סנהדרין צט, ב."],["444","67","<b>כי אל דיעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["445","68","<b>אין</b>: בבוך בש\"ו 1063 כאן. סה\"מ תרל\"ד כאן ע' קנז: האין."],["446","69","<b>שכולו קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["447","70","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צט. קונטרסים ע' שלט."],["448","71","<b>סתים וגליא . . יעקב וישראל</b>: ראה אוה\"ת לך כרך ד ע' תרפד וע' תרפט."],["449","72","<b>ובאוריי' . . חיצוני' התורה ופנימי' התורה</b>: ראה סידור שער הציצית ג, ד. אמרי בינה שם פג, ג. פט, ג ואילך. ביאוה\"ז בהקדמה. מאמרי אדה\"ז כתובים ח\"ב ע' ה."],["450","73","<b>בחי'</b>: בבוך בש\"ו 1063 כאן נכתבה תיבה זו הן בסוף השורה והן בראש שורה הבאה. ובבוך זה 1130 נכתבה ג\"כ ב\"פ. ולכאורה אחד מהם מיותר. וכ\"ה בסה\"מ תרל\"ד ותרנ\"ד כאן."],["451","74","<b>המאור שבה מחזירן למוטב</b>: ראה פתיחתא דאיכ\"ר ב. ירושלמי חגיגה פ\"א, ה\"ז. ראה גם תו\"ח שמות ח\"א טז, ג. וש\"נ. סה\"מ תרל\"ו ח\"ב ע' ש. תר\"ם ח\"ב ס\"ע תשב ואילך. לקמן מאמר ד\"ה אז ישיר משה ספ\"ב."],["452","75","<b>וכ\"מ שנאמר לי</b>: ראה ויק\"ר פ\"ב, ב. מדרש שמואל פי\"ט. ספרי בהעלותך יא, טז. לקו\"ת במדבר ט, ג."],["453","76","<b>דחילו ורחימו רחימו ודחילו</b>: ראה זהר רע\"מ נשא קכג, סע\"א. תו\"א מקץ מ, ד ואילך. מא, סע\"ג ואילך. לקו\"ת בלק עג, א. פ' ראה כא, ג. שה\"ש מו, א. ש\"א שער החנוכה מ, א ואילך. לקמן מאמר ד\"ה הוא אהרן ומשה על יד הערה 131. מאמר ד\"ה מגילה נקראת על יד הערה 83."],["454","77","<b>יראה . . לשס\"ה ל\"ת . . אהבה . . לרמ\"ח מ\"ע</b>: ראה תניא פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז, וש\"נ."]]],[2001910106,"ואח\"כ רחימו הוא בחי' אה\"ר ששרשה מבחי' בינה אימא עילאה<sup data-n=\"455\">78</sup>, ואח\"כ יר\"ע שהוא בחי' חכמ' כח מה<sup data-n=\"456\">79</sup> בחי' ביטול במציאות ממש כו', כי אהבה אע\"פ שהיא אהבה לאלקות אעפ\"כ הוא בחי' יש<sup data-n=\"457\">80</sup>, יש מי שאוהב<sup data-n=\"458\">81</sup>, משא\"כ חכ' הוא כח מה בחי' ביטול במציאות ממש, וכמ\"ש במשה ונחנו מה<sup data-n=\"459\">82</sup>, וזהו ע\"י התורה מגיעים לבחי' יר\"ע ביטול במציאות ממש, וזהו ענין ד' גאולות שביצ\"מ. ועד\"ז יובן לע\"ל דהנה יש שני בחי' הוי' וכמ\"ש ויקרא הוי' הוי' ופסיק טעמא בגווייהו<sup data-n=\"460\">83</sup> שיש שני בחי' הוי', הוי' שבסדר השתלשלות שנעשה מקור לעולמות, והוי' הב' הוא בחי' הוי' שלמעלה מסדר ההשתלשלות רק שעלה ברצונו שהוא בחי' הוי' דא\"א<sup data-n=\"461\">84</sup>, דהנה למטה באדם אף שעיקר הוא הרצון כי הרצון מושל על כל הכחות מ\"מ לא יתהווה כלום מהרצון אף שירצה כמה, משא\"כ למעלה כיון שעלה ברצונו מיד נתהווה כך, כי לא מחשבותי מחשבותיכם<sup data-n=\"462\">85</sup> כו', וכמ\"ש כל אשר חפץ ה' עשה<sup data-n=\"463\">86</sup>, והנה עתה אינו מאיר רק מבחי' ש' הוי' שבסדר ההשתל' אבל הוי' דלעילא אינו מאיר עתה שהפסיק טעמא מפסיק שהוא בחי' פרכת המפסיק וכמ\"ש והבדילה הפרכת<sup data-n=\"464\">87</sup> לכם בין הקדש ובין קדה\"ק, והנה לעתיד יהי' מאיר מבחי' ש' הוי' דלעילא, וכמ\"ש ביום ההוא יהי'<sup data-n=\"465\">88</sup> הוי' אחד שלא יהי' ב' בחי' הוי', אלא יהי' הוי' אחד שלא יהי' פסיק טעמא מפסיק (ושם הוי' דלעילא יהי' מאיר בגילוי בבחי' ש' הוי' דלתתא כו'), וממילא יהי' ג\"כ ושמו אחד, דהנה עתה לא כשאני נכתב אני נק'<sup data-n=\"466\">89</sup> נכתב בהוי' ונק' באד', לפי שהגילוי למטה הוא מבחי' ש' אד' שהוא בחי' אנת אשתמודע אדון על כולא<sup data-n=\"468\">91</sup> שהוא בחי' מל'<sup data-n=\"467\">90</sup>, וכמ\"ש וה' בהיכל קדשו<sup data-n=\"469\">92</sup> היכל גימ' אד'<sup data-n=\"470\">93</sup> ששם אד' הוא היכל לש' הוי' משא\"כ לע\"ל יהי' ושמו אחד,",[["455","78","<b>בינה אימא עילאה</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"ח."],["456","79","<b>חכמ' כח מה</b>: זהר רע\"מ צו כח, א. לד, א."],["457","80","<b>אהבה . . הוא בחי' יש</b>: ראה לקו\"ת מסעי צ, ב."],["458","81","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם תו\"א וארא נו, א. יתרו סז, ג. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["459","82","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ. לקמן מאמר ד\"ה הוא אהרן ומשה על יד הערה 140 ואילך."],["460","83","<b>ויקרא . . ופסיק טעמא בגווייהו</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה גם סה\"מ תרל\"ח ע' נה. וש\"נ."],["461","84","<b>ברצונו . . דא\"א</b>: ראה גם תניא פמ\"א [בהגהה נח, א]. תו\"א ויחי קג, ד. תו\"ח בשלח ח\"א רב, ד. וש\"נ."],["462","85","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה לקו\"ת שה\"ש יז, ג ואילך. (הועתק ב) סה\"מ תר\"ם ח\"א ע' קלט ואילך ובהנסמן שם. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ פ\"ג."],["463","86","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["464","87","<b>והבדילה הפרכת</b>: תרומה כו, לג."],["465","88","<b>ביום ההוא יהי'</b>: זכרי' יד, ט. ראה גם סה\"מ תרל\"ד כאן ע' קנח־ תרנ\"ד כאן ע' קכט־ תרנ\"ח כאן ע' צד־ תרע\"ח כאן ע' קמו. תרל\"ב ח\"א ע' נא. ס\"ע ריב ואילך. תרל\"ו ח\"ב ע' רפח וע' תקלו."],["466","89","<b>לא כשאני נכתב אני נק'</b>: ראה פסחים נ, א."],["468","91","<b>אנת אשתמודע אדון על כולא</b>: ת\"ז בהקדמה יז, ריש ע\"ב. ראה תו\"א מג\"א קיז, ג. לקו\"ת אמור לב, ב. שער היחוה\"א רפ\"ז."],["467","90","<b>ש' אד' . . מל'</b>: ראה זהר ויקרא יא, א. מאמרי אדה\"א בראשית ע' קצז. וש\"נ. תו\"ח נח סד, ג הערה 44."],["469","92","<b>וה' בהיכל קדשו</b>: חבקוק ב, כ."],["470","93","<b>היכל גימ' אד'</b>: ת\"ז תי\"ח (לב, א. לג, ב). ז\"ח יתרו לד, א. וראה גם זח\"ג ערב, ב. פרדס שעה\"כ שכ\"ג, פ\"ה מערכת היכל. מאו\"א מערכת היכל סי\"א ובי\"נ שם. לקו\"ת פקודי ד, א. נשא כא, ד."]]],[2001910107,"לפי שעתה אינו מאיר רק מבחי' ש' הוי' דלתתא ע\"כ הגילוי רק ע\"י ש' אד', משא\"כ לע\"ל כשיהי' מאיר גילוי בחי' ש' הוי' דלעילא אזי לא יהי' הגילוי ע\"י ש' אד' כו', שלא יהי' ש' אד' מסתיר כלל, וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"471\">94</sup> לפי שש' אד' אינו כלי כלל לגילוי ש' הוי' דלעילא, וזהו\"ע ד' גאולות של לע\"ל שהד' גאולות של לע\"ל יהי' נמשך מבחי' ד' אותיות ש' הוי' דלעילא שהוא ג\"כ ע\"י צמצום והתפשטות כו'. והנה בזה יובן ענין ח' פעמים אמת<sup data-n=\"472\">95</sup> ד' פעמים אמת קודם עזרת, וד\"פ אמת לאחר עזרת, והענין הוא דהנה אמת הוא בחי' התגלות אא\"ס, וא\"כ איך שייך לומר ד\"פ אמת או ח' פעמים כו', אך הענין הוא דהנה כתי' תתן אמת ליעקב<sup data-n=\"473\">96</sup> חסד לאברהם, ולכאורה ג\"ז אינו מובן, ולמה צריך יעקב לאמת שהרי יעקב עצמו הוא בחי' אמת וכמ\"ש ויעקב איש תם<sup data-n=\"474\">97</sup> הוא בחי' אמת<sup data-n=\"475\">98</sup>, כי יעקב הוא בריח התיכון מבריח מן הקצה אל הקצה<sup data-n=\"476\">99</sup>, שהוא בחי' אות ו' בחי'<sup data-n=\"478\">101</sup> ת\"ת<sup data-n=\"477\">100</sup>, וכתי' ונתתם לי אות אמת<sup data-n=\"479\">102</sup> ופי' בזהר דא אות ו' וא\"כ מה צריך יעקב לאמת שיתנו לו מלמעלה בחי' אמת. אך הענין הוא דזהו כמ\"ש יהב חכמתא לחכימין<sup data-n=\"480\">103</sup> דוקא, וכמ\"ש בלב כל חכם לב נתתי חכ'<sup data-n=\"481\">104</sup>, שהוא חכם בעצם אזי נותנים לו גם מלמעלה בחי' חכ', וכך יעקב לפי שהוא מדת אמת ע\"כ נותנים לו מלמעלה בחי' אמת, והיינו לפי שיש באמת הרבה מדרגות<sup data-n=\"482\">105</sup>, שיש בחי' אמת שלמעלה מבחי' אמת זה וכמו למשל יחו\"ת שהוא בחי' ביטול היש (של דעה התחתונה), שהוא ג\"כ בחי' אמת שהאמת ג\"כ כך הוא שהעולם נתהווה בחי' יש מאין, והביטול של היש הוא ג\"כ באמת, אך מ\"מ לגבי דיעה העליונה אינה אמת כ\"כ, שאמת לאמיתו הוא כמו בחי' דיעה העליונה שכולא קמי' כל\"ח ממש, והביטול צריך שיהי' בחי' ביטול במציאות ממש כמו בחי' יחו\"ע כו', וזהו ג\"כ משארז\"ל הדן דין אמת לאמיתו<sup data-n=\"483\">106</sup>, והיינו לפי שיש כמה בחי' באמת כו', וזהו ג\"כ החילוק שבין ד\"פ אמת שקודם עזרת לד\"פ שבעזרת, שד\"פ שקודם עזרת הוא מבחי' ד' אותיות של שם הוי' דלתתא, והנה ד\"פ",[["471","94","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["472","95","<b>ח' פעמים אמת</b>: ראה זהר ויקהל רטז, סע\"ב ואילך. אוה\"ת ויחי כרך ז ע' תתתעה."],["473","96","<b>תתן אמת ליעקב</b>: מיכה ז, כ. ראה גם (בנוסף לסה\"מ תרל\"ד ותרנ\"ד כאן) אגה\"ק ס\"ו. לקו\"ת שמע\"צ פג, א. אוה\"ת וארא כרך ז ע' ב'תקפז. סה\"מ תרכ\"ז ע' תצג. וש\"נ."],["474","97","<b>ויעקב איש תם</b>: תולדות כה, כז."],["475","98","<b>ויעקב . . אמת</b>: ראה זהר תולדות קלט, סע\"א. ויצא קסא, א. זח\"ג (תוספות) שב, א. תניא ספי\"ג ובמ\"מ הגהות והערות קצרות שם. אגה\"ק סוס\"ב."],["476","99","<b>יעקב הוא בריח . . אל הקצה</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. לקו\"ת שה\"ש יג, סע\"א ואילך. מאמרי אדה\"א שמות ח\"א ע' יט. וש\"נ. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["478","101","<b>אות ו' בחי' ת\"ת</b>: ראה פרדס שער האותיות שכ\"ז, פ\"ט. מאו\"א מערכת אות הו' ס\"א."],["477","100","<b>יעקב הוא . . ת\"ת</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג (תוספות) שב, א. פרדס שער הכנויים שכ\"ב, פ\"ד."],["479","102","<b>ונתתם לי אות אמת</b>: יהושע ב, יב. ראה זהר ויחי רמא, ב. ויקרא ב, א."],["480","103","<b>יהב חכמתא לחכימין</b>: דניאל ב, כא."],["481","104","<b>בלב כל חכם לב נתתי חכ'</b>: תשא לא, ו [ושם: ובלב — ראה תו\"ח וארא ח\"א פג, ב ובהערה 724]."],["482","105","<b>באמת הרבה מדרגות</b>: ראה לקו\"ת בהר מ, א. אוה\"ת ויחי כרך ב ע' 752. סה\"מ תרל\"ד כאן ע' קנט הערה 61. תרנ\"ד ע' קטז."],["483","106","<b>הדן דין אמת לאמיתו</b>: מגילה טו, ב (ותוס' ד\"ה זה). ראה לקו\"ש חנוכה כרך ל ע' 309. בהערה שלפנ\"ז."]]],[2001910108,"אמת יש בכח הנפש מעצמו להמשיך ע\"י ד' בחי' אותיות שם הוי' שבנפש וכמ\"ש לעיל, אך ד\"פ אמת שבעזרת הוא מבחי' ד' אותיות של ש' הוי' דלעילא שאין זה בכח הנפש להמשיך מצד עצמה באתדל\"ת רק שנותנים לו מלמעלה וזהו תתן אמת ליעקב שנותנים לו מלמעלה כו', ועיקר הגילוי מבחי' ד\"פ אמת אלו יהי' לע\"ל כו', ובזה יובן מ\"ש ג\"כ חכלילי עינים מיין<sup data-n=\"484\">107</sup> ות\"י<sup data-n=\"485\">108</sup> מה יאין הינון עינוי, והיינו כי החי\"ת מורה על בחי' ח' פעמים אמת<sup data-n=\"486\">109</sup>, וזהו שהחית הוא רבתי<sup data-n=\"487\">110</sup>, ולע\"ל יהי' מאיר ח\"פ אמת, וזהו שלע\"ל יהי' כינור של ח' נימין כי כינור של בהמ\"ק הי' משל ז' נימין<sup data-n=\"488\">111</sup>, וכינור של ימוהמ\"ש יהי' מח' נימין והיינו כי כוס הוא בחי' מל'<sup data-n=\"489\">112</sup> שהוא בחי' מקבל, ועכשיו המל' מקבל רק מבחי' ש' הוי' דלתתא, אך לע\"ל יהי' מקבל מבחי' ש' הוי' דלעילא וע\"כ יהי' בגימ' ארך<sup data-n=\"490\">113</sup> כו', שהוא בחי' ש' הוי' דלעילא, והיין יהי' בחי' יין המשומר בענבי' משי\"ב<sup data-n=\"491\">114</sup> שהוא בחי' בינה דא\"א<sup data-n=\"492\">115</sup> כו', וזהו והי'<sup data-n=\"493\">116</sup> אור הלבנה כאור החמה<sup data-n=\"494\">117</sup> כי הנה כתי' שמש ומגן ה' אלקים<sup data-n=\"495\">118</sup> שם הוי' נק' שמש וש' אלקים נק' מגן והוא ג\"כ בחי' לבנה<sup data-n=\"496\">119</sup>, ולע\"ל כתי' והי' הוי' לי לאלקים<sup data-n=\"497\">120</sup> והיינו ע\"י גילוי עצמיות<sup data-n=\"498\">121</sup> אוא\"ס שלמעלה מעלה מש' הוי' ואז<sup data-n=\"499\">122</sup> יהי' שם הוי' לגבי הגילוי שמעצמות אא\"ס כמו עכשיו ש' אלקים לגבי ש' הוי' וז\"ע והי' אור הלבנה דלעתיד שהוא ש' אלקים דלעתיד יהי' כאור החמה דהיינו ש' הוי' כמ\"ש והי' הוי' לי לאלקים.",[["484","107","<b>חכלילי עינים מיין</b>: ויחי מט, יב."],["485","108","<b>ות\"י</b>: ותרגום יונתן. הובא גם באוה\"ת ויחי כרך ב ע' 742־ (יהל אור) תהלים ע' פט [בהשמטת תיבת הינון]. ועד\"ז בסה\"מ תרל\"ב ח\"א ע' קמב. תרל\"ד כאן ע' קנט."],["486","109","<b>החי\"ת . . ח' פעמים אמת</b>: ראה גם אוה\"ת ויחי כרך ב ע' 752. סה\"מ שבהערה הבאה."],["487","110","<b>שהחית הוא רבתי</b>: מדרש ר' עקיבא על אותיות גדולות בשם י\"א. אוה\"ת ויחי שבהערות 108-109. וארא כרך ז ע' ב'תקפז. סה\"מ תרל\"ד כאן ע' קנט. תרנ\"ד כאן ע' קלא וע' קיז.\nראה גם אנציקלפדי' תלמודית חי\"ב מערכת ח ע' תנ הערה 82."],["488","111","<b>כינור של ח' נימין . . ז' נימין</b>: ערכין יג, ב. וראה גם לקו\"ת תזריע כא, ד. סה\"מ תרל\"ח ע' צט ואילך. וש\"נ."],["489","112","<b>כוס . . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ג מערכת כוס. מאו\"א מערכת כוס אות כא."],["490","113","<b>יהי' בגימ' ארך</b>: יומא עו, א. ראה מאמרי אדה\"א דברים ח\"א ע' כג. וש\"נ. שע\"ת כב, ג הערה 23. ראה גם לקמן מאמר ד\"ה ומעתה צ\"ל מפני מה כל הנשמה פיסקא והנה לע\"ל."],["491","114","<b>יין המשומר בענבי' משי\"ב</b>: ראה ברכות לד, ב. מאמרי אדה\"א דברים ח\"א ע' סז. וש\"נ. תו\"ח לך צא, ג הערה 32. סה\"מ תרל\"ד כאן ע' קנט הערה 68."],["492","115","<b>יין . . בינה דא\"א</b>: ראה גם סה\"מ תר\"ם ח\"א ע' רח ובהנסמן שם."],["493","116","<b>והי'</b>: מכאן ואילך לשון לקו\"ת פ' צו י, ג פ\"ב."],["494","117","<b>החמה</b>: בלקו\"ת כאן ניתוסף: ואור החמה יהי' שבעתים כו'."],["495","118","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. תו\"א ויצא כא, ד. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["496","119","<b>אלקים . . לבנה</b>: ראה זהר בראשית כ, א."],["497","120","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא."],["498","121","<b>עצמיות</b>: בלקו\"ת כאן עצמות."],["499","122","<b>ואז</b>: בלקו\"ת כאן ואזי."]]],[2001910109,"<h3>הוא אהרן ומשה</h3>\n<b>פ' בא</b>\n<b>הוא</b> אהרן ומשה<sup data-n=\"500\">1</sup> אשר אמר ה' להם הוציאו את בנ\"י מאמ\"צ<sup data-n=\"501\">2</sup> כו' הם המדברים אל פרעה מלך מצרים כו' הוא משה ואהרן<sup data-n=\"502\">3</sup>. וי\"ל למה נא' הוא אהרן ומשה בל' יחיד שהרי הי' צריך לכתוב הם אהרן ומשה, וקושי' זו מבואר בזהר<sup data-n=\"503\">4</sup>, וגם י\"ל למה נא' תחלה הוא אהרן ומשה שהרי משה הי' העיקר, והנה רבינו ז\"ל תירץ כך שלהוציא את בנ\"י ממצרים הי' אהרן העיקר לכך נא' הוא אהרן ומשה, ולדבר לפרעה מלך מצרים הי' משה עיקר<sup data-n=\"504\">5</sup> לכך בפ' זה נא' הוא משה ואהרן. ולהבין זה י\"ל מקודם מ\"ש אלה ראשי בית אבותם ולא קחשיב רק ג' שבטים ראובן שמעון ולוי, ורש\"י<sup data-n=\"505\">6</sup> מפרש בשם הפסיקתא גדולה<sup data-n=\"506\">7</sup> לפי שקינטרם<sup data-n=\"507\">8</sup> יעקב<sup data-n=\"508\">9</sup> לג' שבטים הללו בשעת מותו חזר<sup data-n=\"509\">10</sup> ויחסם כאן לבדם לומר שחשובים הם, ובספר פנים יפות תירץ דלכך לא מייחס רק לג' שבטים אלו לפי שכוונת הכתוב רק להודיע שמשה הוא דור שביעי מאברהם<sup data-n=\"510\">11</sup>, ולכך הי' משה חביב לפני הקב\"ה לפי שכל השביעי חביב<sup data-n=\"511\">12</sup> וכמו שאנו רואים שבימים",[["500","1","<b>הוא אהרן ומשה</b>: מאמר זה נמצא בבוך בש\"ו 1063 ע' רה [סודר שם בין הדרושים דפ' בא] עם איזה הגהות בגוכתי\"ק אדמו\"ר מהר\"ש.\nכמו\"כ צורף ע' נוסף שנרשם בגוכתי\"ק, כי בבוך בש\"ו 1063 שם נרשם המשך נוסף, וכ\"ק אדמו\"ר מהר\"ש צוה להשמיט את הנ\"ל, ובמקומו הוסיף מלקמן: ”והענין הוא שפרעה אותיות הערף\" (שעל יד הערה 134) עד התיבות ”הוא משה ואהרן\". ענין זה נעתק בבוך זה 1130 בכת\"י הר\"ש סופר. כמו\"כ צורף פתק קטן בגוכתי\"ק עם שני הערות שלא הועתק, ונדפסו כאן לקמן בפיסקא והנה מבחי' בשולי היריעה.\nהמאמר (מלקמן על יד הערה 31 עד על יד הערה 80) — לשון התו\"א וארא נו, ב בהוספות ושינויים.\nראה מאמר זה בשינויים וכו' בסה\"מ תרנ\"ה ע' סב ואילך. פר\"ת ע' רלא ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו [ושם הכותרת: ש\"פ בא תאמ\"ר לפ\"ק].\nמאמר זה הובא (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה ד\"ה אז ישיר משה על יד הערה 23.\nבוך בש\"ו [בראשית שמות ויקרא] הנ\"ל הוא הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים נק' בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד-תרט\"ו ע' שו-שז."],["501","2","<b>הוא אהרן ומשה . . מאמ\"צ</b>: וארא ו, כו."],["502","3","<b>הם המדברים . . הוא משה ואהרן</b>: שם ו, כז."],["503","4","<b>הוא אהרן ומשה . . בזהר</b>: וארא כו, ב. כז, א (אוה\"ת וארא ע' רכו)."],["504","5","<b>רבינו ז\"ל . . לפרעה . . משה עיקר</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכב ואילך. ע' קלג (תקס\"ב ח\"א ס\"ע רצ\"א ואילך). תו\"ח וארא ח\"א פב, ב. אוה\"ת שם ע' רכה."],["505","6","<b>אלה ראשי בית אבותם . . ורש\"י</b>: וארא ו, יד. ראה גם אוה\"ת וארא ע' רח."],["506","7","<b>בשם הפסיקתא גדולה</b>: פסיקתא רבתי פסקא ז ויהי המקריב. וראה רשב\"ם בשם המכילתא."],["507","8","<b>שקינטרם</b>: בפסיקתא: וקינתר . . שקינתרם. בבוך בש\"ו 1063־ רש\"י: שקנטרם [ראה גם לעיל מאמר ד\"ה והי' אור הלבנה הערה 5 ד\"ה לעיל]. בסה\"מ תרנ\"ה כאן כבפנים."],["508","9","<b>יעקב</b>: ברש\"י ופסיקתא ניתוסף: אביהם. בסה\"מ תרנ\"ה כבפנים."],["509","10","<b>חזר</b>: שם ניתוסף: הכתוב. בסה\"מ שם כבפנים."],["510","11","<b>ובספר פנים יפות . . שביעי מאברהם</b>: מובא גם באוה\"ת וארא ע' רכז. סה\"מ תרנ\"ה כאן. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן על יד הערה 8."],["511","12","<b>שכל השביעי חביב</b>: ויק\"ר פכ\"ט, יא."]]],[2001910110,"השביעי שהוא שבת הוא חביב ויברך אלקים את יום השביעי<sup data-n=\"512\">13</sup>, ובחדשים ובחדש השביעי באחד לחדש<sup data-n=\"513\">14</sup> שבו ר\"ה ויוכ\"פ וסוכות, וכן בשנים שנת השביעי הוא חביב ובשנה השביעית שבת שבתון<sup data-n=\"514\">15</sup> כו', וכך משה לפי שהי' דור שביעי לאברהם ע\"כ הי' חביב וזכה לגדולה זו ולכך נא' בו ומשה עלה אל האלקי'<sup data-n=\"515\">16</sup>, נמצא מובן מזה שכמו ששבת הוא למעלה מימי החול כמ\"כ משה הוא למעלה מאברהם שנק' בחי' שבת<sup data-n=\"516\">17</sup> לגבי', ולכאו' אינו מובן פי' זה, שהרי איתא ברבות פ' וירא<sup data-n=\"517\">18</sup> ובפ' שמות<sup data-n=\"518\">19</sup> שאברהם השיב להקב\"ה הנני<sup data-n=\"519\">20</sup>, הנני לכהונה הנני למלכות, וכן משה השיב הנני<sup data-n=\"520\">21</sup> שביקש להדמות לאברהם השיב לו הקב\"ה אל תקרב הלום<sup data-n=\"521\">22</sup> אל תתהדר לפני מלך ובמקום גדולים אל תעמוד<sup data-n=\"522\">23</sup>, משמע מזה שאברהם הוא למעלה ממשה עד שאמר לו במקום גדולים אל תעמוד כו'. אך הענין הוא דהנה כתי' וארא אל אברהם אל יצחק כו' באל שדי ושמי הוי' לא נודעתי להם<sup data-n=\"523\">24</sup>, ולכאו' אינו מובן שהרי נא' באברהם ג\"כ ש' הוי' וכמ\"ש ויקרא ה' אל אברם<sup data-n=\"524\">25</sup> וכן כתי' אלה תולדות השמים וארץ בהבראם<sup data-n=\"525\">26</sup> ופי' רז\"ל במד\"ר במקומו<sup data-n=\"526\">27</sup> ובזח\"ג שמיני דל\"ח ע\"א<sup data-n=\"527\">28</sup> בהבראם באברהם<sup data-n=\"528\">29</sup> וכתי' שם ביום עשות הוי' אלקים<sup data-n=\"529\">30</sup> ארץ ושמים הרי נא' באברהם ג\"כ שם הוי' כו', אך הענין הוא<sup data-n=\"530\">31</sup> דהנה אלקים הוא ל' רבים<sup data-n=\"531\">32</sup> כמ\"ש כי אלקים קדושים הוא<sup data-n=\"532\">33</sup>, והוי' אחד כו'.",[["512","13","<b>ויברך אלקים . . השביעי</b>: בראשית ב, ג."],["513","14","<b>ובחדש השביעי באחד לחדש</b>: פינחס כט, א."],["514","15","<b>ובשנה השביעית שבת שבתון</b>: וכ\"ה בסה\"מ תרנ\"ה כאן. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן על יד הערה 12 — בהר כה, ד. בויק\"ר שם הובא הכתוב (משפטים כג, יא) והשביעית תשמטנה ונטשתה."],["515","16","<b>ומשה עלה אל האלקי'</b>: יתרו יט, ג."],["516","17","<b>משה הוא למעלה מאברהם . . שבת</b>: ראה גם אוה\"ת וארא ע' רכח. תשא ע' ב'יט. לקמן בסיום המאמר."],["517","18","<b>איתא ברבות פ' וירא</b>: פנ\"ה, ו. באוה\"ת תשא שם פנ\"ו. וכנשצ\"ל כבאוה\"ת כאן פנ\"ה."],["518","19","<b>איתא ברבות . . ובפ' שמות</b>: ספ\"ב."],["519","20","<b>שאברהם השיב להקב\"ה הנני</b>: וירא כב, א."],["520","21","<b>משה השיב הנני</b>: שמות ג, ד."],["521","22","<b>אל תקרב הלום</b>: שם שם, ה."],["522","23","<b>אל תתהדר . . אל תעמוד</b>: משלי כה, ו."],["523","24","<b>וארא . . לא נודעתי להם</b>: וארא ו, ג. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רלח. אוה\"ת וארא ע' קיט. שם כרך ז ע' ב'תקנ. ע' ב'תקסד. כרך ח ע' ב'תתצד. תו\"ח בא ח\"א קיג, ב והערה 102. לקמן מאמר ד\"ה זכור פ\"ד. ד\"ה וידבר כו' קדושים תהיו פ\"א."],["524","25","<b>ויקרא ה' אל אברם</b>: וכ\"ה בסה\"מ תרנ\"ה כאן ע' סג. פר\"ת ע' רלא — וירא כב, טו [ושם: ויקרא מלאך ה' אל אברהם]. בבוך בש\"ו 1063 וירא ה' אל אברהם ותיקן כ\"ק אדמו\"ר מהר\"ש אברם — לך יב, ז. יז, א. ראה גם לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן על יד הערות 20-21."],["525","26","<b>אלה תולדות השמים וארץ בהבראם</b>: בראשית ב, ד [ושם: והארץ — וכ\"ה לקמן בפנים בין הערות 107-108. סה\"מ פר\"ת שם]."],["526","27","<b>במד\"ר במקומו . . בהבראם באברהם</b>: ב\"ר פי\"ב, ט."],["527","28","<b>ובזח\"ג שמיני דל\"ח ע\"א</b>: ראה גם זהר לך פו, ב ובדרך אמת אות א."],["528","29","<b>בהבראם באברהם</b>: ראה גם סה\"מ תרל\"ו ח\"ב ע' רנב."],["529","30","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["530","31","<b>אך הענין הוא</b>: להבא להלן עד לקמן על יד הערה 80 — ראה תו\"א וארא נו, ב ואילך בהוספות ושינויים (וראה גם הנסמן במ\"מ לשם)."],["531","32","<b>אלקים הוא ל' רבים</b>: רש\"י וירא כ, יג. וישלח לה, ז. ראה (בנוסף לתו\"א כאן) תו\"ח וארא ס, א ואילך. לקו\"ת אמור לא, ג. אוה\"ת וארא ע' רכג. סה\"מ פר\"ת כאן."],["532","33","<b>כי אלקים קדושים הוא</b>: יהושע כד, יט. [באוה\"ת וארא כרך ח ע' ב'תתפב: הם. וכשצ\"ל הוא כבתו\"א כאן]."]]],[2001910111,"<b>והענין</b> הוא, דהנה כתיב גדול הוי' ומהולל מאד<sup data-n=\"533\">34</sup> ולגדולתו אין חקר ואימתי הוא גדול כשהוא בעיר אלקינו<sup data-n=\"534\">35</sup>, כי גדול הוי' ומהולל מאד היינו שיש בחי' השגה איך שהוא מחיה ומהוה עולמות עד אין קץ ובאמת בשם הוי' למתב\"כ<sup data-n=\"535\">36</sup> ואין שייך בו שום השגה כלל ע\"כ לא שייך לאמר עליו לשון גדולה כלל, וזהו אימתי הוא גדול כשהוא בעיר אלקינו, עיר נק' מה שמקובץ מכמה בתים ובתים הוא צירופי אותיות וכמ\"ש בס\"י שתי אבנים בונות שתי<sup data-n=\"537\">38</sup> בתים<sup data-n=\"536\">37</sup> שכמו שהאבן הוא דומם כמו\"כ האותיות הם בחי' דומם<sup data-n=\"538\">39</sup> כו' ועיר אלקינו הוא בחי' כלליות עולם הדבור דהיינו כשנמשך ש' הוי' בבחי' דיבור שהוא בחי' מל'<sup data-n=\"539\">40</sup> עיר אלקינו אז נק' גדול הוי' ומהולל מאד מחמת ריבוי התחלקות החיות עד אין קץ, אבל לגדולתו אין חקר כו', והנה כתי'<sup data-n=\"540\">41</sup> מה רבו מעשיך<sup data-n=\"541\">42</sup> וכתי' מה גדלו מעשיך<sup data-n=\"542\">43</sup>, מה רבו מעשיך קאי על עולמות התחתונים<sup data-n=\"543\">44</sup> וכל הברואים שבעוה\"ז המתחלקים למיניהם בכמה מיני התחלקות רבוא רבבות מדרגות בדצ\"ח שכמה מיני דומם וכמה מיני צומח<sup data-n=\"544\">45</sup> כו' וכל מין ומין יש לו טעם בפ\"ע כמו אגוזים<sup data-n=\"545\">46</sup> ושקדים וכיוצא בהם בצומח שכל א' יש לו טעם בפ\"ע שאין הא' דומה לחבירו, וכן בכל מיני עשבים כל עשב יש לו טעם בפ\"ע, והטעם הוא רוחני ממזל השופע עליו שאין לך כל עשב<sup data-n=\"546\">47</sup> מלמטה שאין לו מזל מלמעלה<sup data-n=\"547\">48</sup> כו', וכ\"ז הוא מפסולת עולמות עליונים וכמ\"ש וכל קרבי את שם קדשו<sup data-n=\"548\">49</sup> שיש בחי' קרביים העליונים המבררים את הפסולת להשפיע לעוה\"ז הגשמי, וזהו ר\"ע כשראה כרך גדול של רומי מליאה תענוגים שחק וא' אם לעוברי רצונו<sup data-n=\"550\">51</sup> כך לעושי רצונו עאכ\"ו, והיינו אם לעוברי רצונו כך שהוא רק בחי' פסולת וחיצוני'<sup data-n=\"549\">50</sup> וכמ\"ש נטה ימינו וברא שמים<sup data-n=\"551\">52</sup> נטה שמאלו וברא ארץ שהארץ מקבל מבחי' שמאל",[["533","34","<b>גדול הוי' ומהולל מאד</b>: תהלים קמה, ג."],["534","35","<b>ואימתי הוא גדול כשהוא בעיר אלקינו</b>: תהלים מח, ב. ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ."],["535","36","<b>למתב\"כ</b>: ת\"ז בהקדמה יז, א."],["537","38","<b>בס\"י שתי אבנים . . שתי בתים</b>: ראה שם פ\"ד, מי\"ב."],["536","37","<b>וזהו אימתי . . שתי בתים</b>: לשון התו\"א וארא נו, סע\"ב."],["538","39","<b>האותיות הם בחי' דומם</b>: ראה גם תו\"א בראשית ד, א. סידור שער התפלה כג, ב. תו\"ח בראשית כא, ד."],["539","40","<b>דיבור . . מל'</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["540","41","<b>והנה כתי'</b>: לשון התו\"א כאן נו, ב (בשינויים קלים)."],["541","42","<b>מה רבו מעשיך</b>: תהלים קד, כד."],["542","43","<b>מה גדלו מעשיך</b>: תהלים צב, ו."],["543","44","<b>מה רבו . . עולמות התחתונים</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תצד. וש\"נ."],["544","45","<b>שכמה מיני דומם . . צומח</b>: ראה גם סה\"מ תר\"ם ח\"א ע' י. וש\"נ."],["545","46","<b>אגוזים</b>: בתו\"א כאן: תפוחים ואגוזים. וכ\"ה לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן בסמיכות להערה 36."],["546","47","<b>שאין לך כל עשב</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג."],["547","48","<b>שאין לו מזל מלמעלה</b>: ליתא בתו\"א."],["548","49","<b>וכל קרבי את שם קדשו</b>: תהלים קג, א. ראה גם שע\"ת סט, א ובהנסמן במ\"מ לשם."],["550","51","<b>ר\"ע . . אם לעוברי רצונו</b>: ראה מכות בסופה. לקו\"ת בהעלותך לג, ד. שלח מז, א."],["549","50","<b>וזהו ר\"ע . . וחיצוני'</b>: כ\"ז הוספה על התו\"א."],["551","52","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א כאן בפנים. לקמן מאמר ד\"ה ועבדתם את ה\"א ובהערה 81."]]],[2001910112,"ועכ\"ז יש תענוגי' הרבה עד אין שיעור, לעושי רצונו שהם מקבלים מבחי' פנימי' הרצון ממש דהיינו מבחי' מה גדלו מעשיך כו' וכמשי\"ת עאכו\"כ<sup data-n=\"552\">53</sup>, וע\"ז נא' מה רבו מעשיך, אך מה גדלו מעשיך קאי על עולמות העליונים<sup data-n=\"553\">54</sup> מלאכים ונשמות שמתענגי' על ה' ואין תענוג אחד דומה לחבירו כמארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות<sup data-n=\"554\">55</sup> שנא' להנחיל אוהבי יש<sup data-n=\"555\">56</sup> כו', ולכאו' אינו מובן למה צריך כל צדיק כ\"כ עולמות וכי לנכסים הוא צריך. אך הענין הוא דהנה<sup data-n=\"556\">57</sup> ש\"י הוא ב\"פ קנה, קנה חכ' קנה בינה<sup data-n=\"558\">59</sup> גימ' יש<sup data-n=\"557\">58</sup>, והיינו כי הש\"י עולמות נמשכים מבחי' חו\"ב, דהנה תרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך עמודי אור<sup data-n=\"559\">60</sup> שהוא בחי' כתר, והנה מה שיוכל להיות נמשך בגילוי תענוג זהו רק מבחי' חצי התחתון דכתר שהוא בחי' ש\"י אורות, וכדי שיהי' יכול לקבל מבחי' ש\"י אורות דכתר זהו ע\"י ש\"י עולמות שנמשכים מבחי' חו\"ב שהם כלים לבחי' ש\"י אורות דכתר כו', ולכן עתיד הקב\"ה להנחיל לכל צו\"צ* היינו כל חד לפושע\"ד<sup data-n=\"562\">62</sup> ולפ\"ע תורתו ועבודתו בעוה\"ז כן הוא ממשיך כו' לכן<sup data-n=\"561\">61</sup> כאו\"א הוא מדור בפ\"ע<sup data-n=\"560\">*61</sup> בבחי' זיו והשגה פרטיות מיוחדת אשר משיג ונהנה ומתענג על ה' תענוג פרטי מיוחד ונבדל מתענוג והשגת צדיק חבירו כי כל חד לפושע\"ד, וזיו השכינה כולל רבוא רבבות מדרגו' ומיני תענוג לנשמות עד אין קץ ותכלית ממש שהרי נמשך מאוא\"ס ב\"ה, והנה התחלקות החיות מאוא\"ס לכל העולמות בריבוי התחלקות המדרגות בהרבה מיני תענוג לכ\"ח לפושע\"ד הוא הנק' בשם אלקים ל' רבים ע\"ש ריבוי התחלקות בהתפשטות החיות מלמעלה, הוא הוא התפשטות גדולתו ית' בבחי' גילוי שיכירו וידעו גדולתו ותפארתו שע\"כ הם מתענגים לחזות בנועם ה'<sup data-n=\"563\">63</sup>. וזהו אימתי הוא גדול כשהוא בעיר אלקינו כשנמשך התפשטות גדולתו ומתחלק בכמה בחי' התחלקות וריבוי תענוגים בכל עולמות לכ\"ח לפושע\"ד ואז נק' אלקים ל' רבים ע\"ש ריבוי התחלקות בהתפשטות החיות בבחי' גילוי לעולמות<sup data-n=\"564\">64</sup> ונבראים, משא\"כ הוי' נק' אחד שהוי' הוא בחי' מקור כל הויות משרשא<sup data-n=\"565\">65</sup> דכולא קודם שבא לידי המשכה בבחי' גילוי בעיר אלקינו.",[["552","53","<b>ועכ\"ז . . עאכו\"כ</b>: הוספה על התו\"א."],["553","54","<b>מה גדלו . . עולמות העליונים</b>: ראה לעיל הערה 44."],["554","55","<b>עתיד . . ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["555","56","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["556","57","<b>דהנה</b>: מכאן ליתא בתו\"א."],["558","59","<b>קנה חכ' קנה בינה</b>: משלי ד, ה."],["557","58","<b>ש\"י הוא ב\"פ קנה . . גימ' יש</b>: ראה פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, סע\"א]. שער יוה\"כ שכ\"ז, פ\"ה. שער הפסוקים משלי ס\"ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרס. תקע\"א ע' עה. מאמרי אדה\"א דברים ח\"א ע' טז. וש\"נ. אוה\"ת בהעלותך ע' תטז."],["559","60","<b>תרי\"ג . . וז' . . תר\"ך עמודי אור</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' הערות 131-135."],["562","62","<b>כל חד לפושע\"ד</b>: ראה תניא בהקדמה (ד, א) ע\"פ זהר וירא קג, ריש ע\"ב. וראה גם זהר ח\"ש קכט, ב."],["561","61","<b>היינו . . לכן</b>: בתו\"א כאן: כו'. כי."],["560","*61","<b>לכל צו\"צ . . מדור בפ\"ע</b>: ראה שבת קנב, א. רו\"ר פ\"ג, ד."],["563","63","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["564","64","<b>לעולמות</b>: תו\"א כאן נו, רע\"ג."],["565","65","<b>משרשא</b>: בתו\"א כאן: ושרשא."]]],[2001910113,"<b>והנה</b> מבחי' אלקים נמשך למטה בחי' היראה וכמ\"ש והאלקים עשה שייראו מלפניו<sup data-n=\"566\">66</sup> וכתיב את האלקים ירא<sup data-n=\"567\">67</sup> וכתיב את ה' אלקיך תירא<sup data-n=\"568\">68</sup>, כי בבחי' הוי' למתב\"כ רק בבחי' אלקים הוא התפשטות גדולתו ית' תפול על האדם אימה ויראה בושת<sup data-n=\"569\">69</sup>, וכן האהבה נמשכת ע\"י בחי' אלקים דוקא וכמ\"ש הללוהו בגבורותיו<sup data-n=\"570\">70</sup> הללוהו כרוב גודלו, וכתיב ואהבת את ה' אלקיך<sup data-n=\"571\">71</sup> כו' להיות האהבה להוי' בבחי' ביטול במציאות לבחי' דלית מח' תב\"כ צ\"ל תחלה ע\"י בחי' שם אלקים שיתבונן בגדולת אוא\"ס ב\"ה והתפשטותו בנבראים ומזה ישוב לאהבה את ה' דלית מ\"ת כו', וזהו וידבר אלקים אל משה<sup data-n=\"572\">72</sup> ויאמר אליו אני הוי' שע\"י בחי' אלקים הוא גילוי שם הוי', ועי\"ז וארא אל אברהם ויצחק כו' הם המדות אהוי\"ר שנולדו מזה כי<sup data-n=\"573\">73</sup> אברהם יצחק ויעקב הם המדות חג\"ת<sup data-n=\"574\">74</sup> שהוא בחי' ירושה מאבותינו שיש לכל אחד בחי' אוי\"ר ורחמים<sup data-n=\"575\">75</sup>, אין קורין אבות<sup data-n=\"576\">76</sup> אלא לשלשה, לפי שבחי' אבות יש לכל אחד, אך הנה נודע כי האהבה שממטה למעלה עיקרה כדי להגיע שתהא באה על האדם מלמעלמ\"ט האהבה העליונה<sup data-n=\"577\">77</sup> שהיא העיקרית, וזהו שנא' בשה\"ש הנך יפה רעייתי<sup data-n=\"578\">78</sup> הנך יפה ב\"פ, והיינו כי יופי הוא התכללות מג' גוונים<sup data-n=\"579\">79</sup> דוקא, כי גוון א' אין לו יופי כ\"א כשהוא כלול מג' בחי' חיור סומק ירוק שהוא בחי' ג' מדות אוי\"ר ורחמים, וכתי' ב\"פ הנך יפה, היינו היופי שממטה למעלה והיופי שנמשך מלמעלה והיינו התגלות המדות עליונות מלמעלמ\"ט, בנפש האדם, וזהו וארא אל אברהם כו' המשכות התגלות אהוי\"ר מלמעלמ\"ט, ע\"י אוי\"ר שמעורר האדם מלמטה עי\"ז נמשך התגלות אוי\"ר מלמעלה. אך מי הגורם ומחבר אהבה העליונה שמאתעדל\"ע שהוא בחי' א\"ס להיות שורה ומתגלה באתעדל\"ת<sup data-n=\"581\">81</sup> בנפש האדם שהוא בחי' גבול ונברא יש מאין, והנה ע\"ז נא' באל שדי<sup data-n=\"580\">80</sup>, והיינו כי שדי הוא בחי' שין וד\"י, שין הוא בחי' ג' מדות<sup data-n=\"582\">82</sup>",[["566","66","<b>והאלקים עשה שייראו מלפניו</b>: קהלת ג, יד."],["567","67","<b>את האלקים ירא</b>: קהלת יב, יג."],["568","68","<b>את ה' אלקיך תירא</b>: ואתחנן ו, יג. עקב י, כ."],["569","69","<b>ויראה בושת</b>: ראה ת\"ז בהקדמה ה, ב. תכ\"ח. מאמרי אדה\"א בראשית ע' מ.\nבבוך בש\"ו 1063־ בתו\"א ובסה\"מ תרנ\"ה ע' סו: ויראת בושת. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה הערה 5 ד\"ה לעיל."],["570","70","<b>הללוהו בגבורותיו</b>: תהלים קנ, ב."],["571","71","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה. עקב יא, א."],["572","72","<b>וידבר אלקים אל משה</b>: וארא ו, ב."],["573","73","<b>כי</b>: מכאן ליתא בתו\"א."],["574","74","<b>אברהם יצחק ויעקב . . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. תו\"ח וארא ח\"א סא, ד. וש\"נ."],["575","75","<b>ירושה מאבותינו . . אוי\"ר ורחמים</b>: ראה גם תו\"א ר\"פ וארא. תו\"ח וארא ח\"א סה, ג. סח, א."],["576","76","<b>אין קורין אבות</b>: ברכות טז, ב. ראה תו\"א וארא נה, א. תו\"ח משפטים ח\"ב רפו, ד ואילך. לקו\"ש בלק כרך ד ע' 1068 הערה 12. ויצא כרך י ע' 97 הערה 48."],["577","77","<b>האהבה . . עיקרה . . האהבה העליונה</b>: ראה אגה\"ק ס\"ו קי, ב. אוה\"ת וארא ע' קמד."],["578","78","<b>הנך יפה רעייתי</b>: שה\"ש א, טו. ד, א."],["579","79","<b>יופי . . מג' גוונים</b>: ראה גם לקו\"ת שה\"ש יד, א. תו\"ח בראשית מ, א ובהערה 6. ראה גם תו\"א וישלח כה, סע\"א ואילך: כשמורכבים ב' וג' גוונים יחד הוא עיקר היופי. אגה\"ק סי\"ב קיז, ב. מאמרי אדה\"א דברים ח\"ב ע' תקג. נ\"ך ע' שכז. וש\"נ."],["581","81","<b>שמאתעדל\"ע . . באתעדל\"ת</b>: ראה גם לקמן במאמר ד\"ה להבין וכו' בענין הציץ הערה 215."],["580","80","<b>אך מי . . באל שדי</b>: לשון התו\"א כאן נו, ג. ע\"כ הוא לשון התו\"א כאן — ראה לעיל הערה 31."],["582","82","<b>שין . . ג' מדות</b>: ראה מאו\"א מערכת אות השי\"ן ס\"א וביאיר נתיב שם."]]],[2001910114,"וד\"י הוא בחי' מה שא' לעולמו די<sup data-n=\"583\">83</sup> שנעשה מקור לעולמות, והיינו ששם שדי הוא כלול מב' הבחי' דהיינו מבחי' המדות שהוא בחי' א\"ס ומבחי' הנעשה מקור לעולמות ע\"כ יכול לחבר שיהי' המשכת אוי\"ר עליונים למטה בבחי' אוי\"ר שבנפש האדם שהוא גבול ונברא כו', וזהו ג\"כ מ\"ש היא מתהלכת בין החיות<sup data-n=\"584\">84</sup>, והיינו כי ידוע שיש בחי' חיון עילאין וחיון תתאין<sup data-n=\"585\">85</sup> שהוא מרכבתא תתאה ומרכבתא עילאה<sup data-n=\"586\">86</sup>, מרכבתא תתאה הוא בבריאה שהם בחי' האבות הן המרכבה<sup data-n=\"587\">87</sup> שהאבות עצמן הם<sup data-n=\"588\">88</sup> בבריאה* כו' (ע' בס' המתחיל כי ידעתיו<sup data-n=\"589\">89</sup> בד\"ה קיצור מד\"ה וידבר כו' וארא<sup data-n=\"590\">90</sup> סעי' ד', וססעי' ה') וחיון עילאין הוא בחי' מרכבתא עילאה דהיינו בחי' מדות עליונות, וכדי שיתחברו החיות יחד זהו ע\"י בחי' הוא<sup data-n=\"591\">91</sup> שהוא בחי' מל'<sup data-n=\"592\">92</sup> המתהלכת בין החיות דהיינו בין חיון עילאין ובין חיון תתאין, כי המל' מקבל מבחי' מדות עליונות ומשפעת לחיון תתאין מרכבה דבריאה כו', ובעבודה ב' בחי' יופי הוא ענין פסוד\"ז ובחי' ק\"ש, כי פסוד\"ז הוא בחי' אוי\"ר שבאה ע\"י עבודת האדם בבחי' התבוננות גדול הוי' ומהולל מאד כו', וק\"ש הוא בחי' אוי\"ר הבאה מלמעלה בבחי' אתעדל\"ע, אך ושמי הוי' לא נודעתי להם כי שם הוי' לא נתגלה רק ע\"י יצ\"מ ומ\"ת וכמ\"ש לכן<sup data-n=\"593\">93</sup>\n\n*)שהאבות[ftnref_8175_א] עצמן הם בבריאה, צ\"ל הטעם מפני כי אברהם אברהם פסיק טעמא[ftnref_8176_ב].",[["583","83","<b>שא' לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["584","84","<b>היא מתהלכת בין החיות</b>: יחזקאל א, יג."],["585","85","<b>חיון עילאין וחיון תתאין</b>: ראה זהר ויקהל ריא, א. ריג, א. לקו\"ת תזריע כב, ד. סידור שחרית סד, א. ביאוה\"ז בשלח מב, סע\"ב ואילך. ויקרא סב, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שט. מאמרי אדה\"א ויקרא ח\"ב ע' תסט ואילך."],["586","86","<b>מרכבתא תתאה ומרכבתא עילאה</b>: ראה זח\"א רע\"מ בהשמטות רסו, ב. ואתחנן רסב, ב. ת\"ז תס\"ט קי, ב. סידור ביאוה\"ז ולקו\"ת שם. מאמרי אדה\"א ויקרא ח\"א ע' רכג. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["587","87","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["588","88","<b>שהאבות עצמן הם בבריאה</b>: ראה גם תו\"ח וארא ח\"א סב, א ובהנסמן שם. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 72."],["589","89","<b>ע' בס' המתחיל כי ידעתיו</b>: על הכריכה נרשם בגוכתי\"ק [חו]רף תרט\"ז. נסמן בספריית ליובאוויטש מס' 1023 ע' קח-קט."],["590","90","<b>בד\"ה קיצור מד\"ה . . וארא</b>: נדפס באוה\"ת וארא ע' קמב ואילך [ושם וכן במפתח המאמרים שבריש הספר נדפס: קיצור סד\"ה. וכנשצ\"ל כבפנים]."],["591","91","<b>הוא</b>: בבוך בש\"ו 1063־ לעיל בפנים על יד הערה 84־ אוה\"ת בהערה הבאה: היא. בסה\"מ תרנ\"ה כאן ע' סז כבפנים. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה הערה 5 ד\"ה לעיל."],["592","92","<b>היא . . מל'</b>: ראה עבודת הקודש ח\"ד, פי\"ט (כפי שהובא באוה\"ת שם ע' קמד־ יתרו ע' תתקפ). פרדס שער הטעמים שכ\"ט, פ\"ד ד\"ה רפה דגש. ראה גם לקו\"ת במדבר י, א. מאמרי אדה\"א במדבר ח\"ב ע' תתלח. המשך תער\"ב ח\"ב ס\"ע א'יט. פלח הרמון בחוקותי ס\"ע תצב."],["593","93","<b>לכן אמור לבנ\"י</b>: וארא ו, ו.\n\n[ftn_8175_א]) נרשם בגוכתי\"ק אדמו\"ר מהר\"ש בפתק בפ\"ע — ראה לעיל הערה 1.\n\n[ftn_8176_ב]) וירא כב, יא. ראה שמו\"ר פ\"ב, ו. תו\"א משפטים עו, ג. סה\"מ תר\"ם ח\"א ע' תכב. וש\"נ."]]],[2001910115,"אמור לבנ\"י אני הוי' והוצאתי אתכם כו' וידעו כי אני הוי'<sup data-n=\"594\">94</sup> כו', והיינו כי אף שנא' באברהם ג\"כ וירא ה'<sup data-n=\"595\">95</sup> כו' וארא אל אברהם כו', אך הנה כ\"ז הוא בחי' ש' הוי' המאיר בש' אלקים* וכמ\"ש ביום עשות הוי' אלקים כו', משא\"כ ע\"י התורה מתגלה עצמות ש' הוי' שלא ע\"י ש' אלקים וכמשארז\"ל ע\"פ מה יתרון לאדם בכל עמלו שיעמול תחת השמש<sup data-n=\"596\">96</sup> שאני עמלא דאורייתא דהיא לעילא מן שמשא<sup data-n=\"597\">97</sup>, והיינו כי שמש הוא בחי' מ\"ש כי שמש ומגן הוי' אלקים<sup data-n=\"598\">98</sup> שש' אלקים הוא בחי' מגן ונרתק על בחי' ש' הוי' ששם אלקים הוא מסתיר ומעלים כו', אך ע\"י התורה היא<sup data-n=\"599\">*99</sup> מתגלה עצמי' ש' הוי' שלמעלה שהוא לעילא מן שמשא בחי' שמש הוי' המאיר ע\"י ש' אלקים כו' וכמו שיהי' לע\"ל שעתיד הקב\"ה להוציא חמה מנרתיקה<sup data-n=\"600\">99</sup> שנא' ואוהביו כצאת השמש בגבורתו<sup data-n=\"601\">100</sup> כו'.\n<b>וביאור</b> הענין הוא, דהנה בפתח אלי' איתא אנת חכים ולא בחכ' ידיעא כו' חסד דרועא ימינא גבורה כו' ומסיים ולאו מכא\"מ כלל<sup data-n=\"602\">101</sup> ולא נא' מכל אינון חכ' ובינה, אך הענין הוא דהנה מדות הם שייכים לעולמות<sup data-n=\"603\">102</sup> שאם לא הי' העולם על מי הי' נקרא חנון ורחום<sup data-n=\"604\">103</sup> ועל מי הי' מתחסד כו', וזהו מ\"ש זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"605\">104</sup> שבחי' רחמים וחסדים הם רק השייכים לעולמות, וזהו\n\n*)וכשוארא ע\"י ש' שדי לג' אבות ונתחבר חוין[ftnref_8177_ג] עולאין[ftnref_8177_ג] עם חיון תתאין האורג על האבות הארת ש' הוי' כמו שמתגלה ע\"י שם אלקים.",[["594","94","<b>וידעו כי אני הוי'</b>: וכ\"ה בסה\"מ תרנ\"ה כאן. תצוה כט, מו. וארא ו, ז [ושם: וידעתם]. אבל לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 72 מובא הכתוב: וידעו מצרים כי אני הוי' — וארא ז, ה. ועוד."],["595","95","<b>וירא ה'</b>: לך יב, ז. יז, א. וראה לעיל הערה 25."],["596","96","<b>מה יתרון לאדם . . השמש</b>: קהלת א, ג. ראה גם תו\"ח וארא ח\"א סג, סע\"ב ואילך ובהנסמן בריש המאמר שם."],["597","97","<b>שאני עמלא דאורייתא . . שמשא</b>: זהר ויחי רכג, ב."],["598","98","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. תו\"א ויצא כא, ד. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["599","*99","<b>התורה היא מתגלה</b>: כ\"ה בהכת\"י."],["600","99","<b>שעתיד הקב\"ה להוציא חמה מנרתיקה</b>: ראה נדרים ח, ב. ראה גם שער היחוה\"א רפ\"ד. תו\"ח בראשית לה, א ובהערה 12. שמות ח\"א לט, ב. וש\"נ. מאמרי אדה\"א הנחות תקע\"ז ע' שי."],["601","100","<b>ואוהביו כצאת השמש בגבורתו</b>: ס' שופטים ה, לא."],["602","101","<b>אנת חכים . . ולאו מכא\"מ כלל</b>: ת\"ז בהקדמה יז, ב."],["603","102","<b>מדות הם שייכים לעולמות</b>: ראה גם אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ."],["604","103","<b>חנון ורחום</b>: יואל ב, יג. יונה ד, ב. ועוד."],["605","104","<b>זכור רחמיך . . מעולם המה</b>: תהלים כה, ו [בדילוג השם — בבוך בש\"ו 1063: זכור רחמיך ה'. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה הערה 5 ד\"ה לעיל]. ראה גם לקמן מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 32 ואילך.\n\n[ftn_8177_ג])כ\"ה בגוכתי\"ק.\n\n[ftn_8177_ג])כ\"ה בגוכתי\"ק."]]],[2001910116,"כי אמרתי עולם חסד יבנה<sup data-n=\"606\">105</sup>, שיש לפרש ב' פי'<sup data-n=\"607\">106</sup> הא' שיבנה קאי על העולם שע\"י החסד יבנה העולם, והב' שכדי שיהי' העולם צריך לבנות את החסד שעד שלא נבה\"ע אינו שייך בחי' חסד כלל כו', משא\"כ בחי' חכ' שייך גם אפי' אם לא הי' נבה\"ע כי חכ' שייך לעצמו<sup data-n=\"608\">107</sup> ואינו כמו המדות שהם רק לזולתו, משא\"כ החכ' הוא אפי' כמו שהוא בעצמו יכול ג\"כ להשכיל השכלות כו', ולזה לא נא' רק ולאו מכא\"מ הוא כלל לפי שמדות אינם שייכים רק לעולמות כו', משא\"כ חכ' לא שייך לעולמות. והנה באבות לא נתגלה רק בחי' ש' הוי' המאיר בש' אלקים, שהוא בחי' מדות עליונים, לפי שהאבות היו מרכבה לבחי' מדות שהוא בחי' השייך לעולמות, אלה תולדות השמים והארץ בהבראם ביום עשות הוי' אלקים כו' שהוא בחי' מדות עליונות, משא\"כ עצמות ש' הוי' כמו בחכ' וכמ\"ש הוי' בחכ'<sup data-n=\"609\">108</sup> לא נודעתי להם כו', אך ע\"י התורה נתגלה שם עצמיות ש' הוי' כמו שהוא בחכ' לפי שאורייתא מח\"ע נפקת<sup data-n=\"610\">109</sup> אלפיים שנה קדמה לעולם<sup data-n=\"611\">110</sup> אאלפך חכ' אאלפך בינה<sup data-n=\"612\">111</sup> כו' שלמעלה מבחי' מקור לעולמות כו', והיינו לפי שבתומ\"צ הוא התגלות עצמות המוחין. וזהו שביקש משה הראני נא את כבודך<sup data-n=\"613\">112</sup> והשיב לו הקב\"ה וראית את אחורי<sup data-n=\"614\">113</sup> ופני לא יראו וארז\"ל מלמד שהראהו קשר של תפילין<sup data-n=\"615\">114</sup>, והיינו שביקש הראני נא את כבודך הוא בחי' פנימי' ח\"ע כי כבוד בגימ' ל\"ב<sup data-n=\"616\">115</sup> נח\"ע<sup data-n=\"617\">116</sup> שהוא בחי' תפילין דמארי עלמא<sup data-n=\"618\">117</sup>, והיינו כי מארי עלמא הוא בחי' מדות עליונות שנעשים מקור לעולמות ותפילין דמארי עלמא הוא בחי' מוחי' שנמשכים במדות, וזהו הקב\"ה מניח תפילין<sup data-n=\"619\">118</sup> הקב\"ה הוא בחי' ז\"א<sup data-n=\"620\">119</sup> דאצי' שהוא בחי' קדוש ו' מניח תפילין שהם המשכת ד' מוחין<sup data-n=\"621\">120</sup> כו' שנמשכים במדות כו' וביקש משה הראני נא את כבודך שהוא בחי' ח\"ע,",[["606","105","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["607","106","<b>ב' פי'</b>: ראה סה\"מ תרכ\"ט ע' ט ועד\"ז ע' תו שמציין: ע' מזה בד\"ה ולקחתם אגודת אזוב (ך\"ח) [לא נדפס לע\"ע. וראה בהערת המו\"ל שם]. סה\"מ תרכ\"ז ע' קמ. וש\"נ. תרל\"ח ע' מז ואילך. תר\"ם ח\"ב ע' תתלו. לקמן מאמר ד\"ה כל אשר חפץ ה' עשה על יד הערה 10 ואילך. ד\"ה בעשרה מאמרות נבה\"ע על יד הערה 18 ואילך. ד\"ה שיר המעלות ממעמקים על יד הערה 7."],["608","107","<b>חכ' שייך לעצמו</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תקז. וש\"נ."],["609","108","<b>הוי' בחכ'</b>: משלי ג, יט."],["610","109","<b>שאורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["611","110","<b>אלפיים שנה קדמה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["612","111","<b>אאלפך חכ' אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["613","112","<b>הראני נא את כבודך</b>: תשא לג, יח."],["614","113","<b>וראית את אחורי</b>: תשא שם, כג."],["615","114","<b>מלמד שהראהו קשר של תפילין</b>: ראה ברכות ז, א."],["616","115","<b>כבוד בגימ' ל\"ב</b>: זהר רע\"מ צו לג, א."],["617","116","<b>כבוד בגימ' ל\"ב נח\"ע</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. לקו\"ת אחרי כה, ד. מאמרי אדה\"א בראשית ע' ג ואילך."],["618","117","<b>תפילין דמארי עלמא</b>: ראה ברכות ו, א. סה\"מ מלוקט ב' ע' פז הערה 10."],["619","118","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 126."],["620","119","<b>הקב\"ה הוא בחי' ז\"א </b>: ראה ע\"ח שער הכללים פי\"ב. לקוטי הש\"ס להאריז\"ל ברכות ו, א (ה, א בדפי הספר)."],["621","120","<b>תפילין . . ד' מוחין</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 127."]]],[2001910117,"תפילין דמארי עלמא, והשיב לו הקב\"ה כי לא יראני האדם וחי<sup data-n=\"622\">121</sup> והראה לו רק קשר של תפילין שהוא בחי' מל' דתבונה<sup data-n=\"623\">122</sup>, אבל תפילין עצמן א\"א שיומשכו בבחי' ראי' והשגה ממש, אך ע\"י שמניח אדם תפילין בגשמי' עי\"ז נמשך בחי' תפילין דמארי עלמא, נמצא שע\"י המצות נמשך בחי' עצמות המוחין שהוא בחי' עצמות ש' הוי' שלמעלה מבחי' ש' הוי' המאיר ע\"י שם אלקים כו' מה שלא נתגלה להאבות כו' וגם לא למשה בבחי' ראי' והשגה, אבל מה שנמשך ע\"י קיום המצות זה בודאי נמשך גם למשה כי משה קיים ג\"כ מצות תפילין רק שלא נמשך לו בבחי' ראי' ממש.\n<b>ועתה</b> י\"ל מ\"ש הוא אהרן ומשה, והענין הוא דהנה מתחלה צ\"ל ההפרש שבין אברהם לאהרן, דהנה אברהם הוא בחי' חסד<sup data-n=\"624\">123</sup>, והנה אהרן הוא ג\"כ בחי' חסד<sup data-n=\"625\">124</sup>, אך הענין הוא דהנה ידוע שאית חסד ואית חסד<sup data-n=\"626\">125</sup>, אית חסד דאקרי חסד עולם ואית חסד דאקרי רב חסד<sup data-n=\"627\">126</sup>, וזהו שבאברהם נא' הלוך ונסוע הנגבה<sup data-n=\"628\">127</sup> שכל עיקר עבודתו ותשוקתו הי' כדי לבא לבחי' הנגבה שהוא בחי' מנורה בדרום<sup data-n=\"629\">128</sup> דהיינו בחי' אהבה העליונה כו', אך הנה באהרן כתי' בהעלותך את הנרות<sup data-n=\"630\">129</sup> שהתחלה שלו הי' בבחי' מנורה, ואדרבה שהוא מעלה את המנורה, והיינו כי אברהם הוא בחי' חסד עולם דהיינו בחי' חסד השייך לעולמות, משא\"כ אהרן הוא בחי' רב חסד<sup data-n=\"631\">130</sup> שלמעלה מעולמות, והגם שנא' באברהם ג\"כ וארא שהוא בחי' התגלות ש' הוי' הבאה מלמעלה, אך יש שני בחי' וכמו שיש בשם הוי' גופא שני בחי' אוי\"ר, כי ד' אותיות ש' הוי' הוא בחי' דחילו ורחימו ורחימו ודחילו<sup data-n=\"632\">131</sup>, והיינו כי ו\"ה הוא בחי' דו\"ר, וי\"ה הוא בחי' רו\"ד, והנה באברהם שהי' בחי' התגלות אוי\"ר הוא בחי' דו\"ר שנמשך מבחי' ו\"ה, משא\"כ אהרן הוא ממשיך בחי' רחימו",[["622","121","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["623","122","<b>קשר של תפילין . . מל' דתבונה</b>: ראה אוה\"ת במדבר ע' כא ואיתא בכהאריז\"ל — ראה ע\"ח שער הכללים רפי\"ב. שער אח\"פ שער ד, ספ\"ג. שער לאה ורחל של\"ח, פ\"ו. פע\"ח שער התפילין פ\"ה. שער ההקדמות סוד מצות התפילין (קפז, ב). לקו\"ת תזריע כג, ב. סידור שער הק\"ש עח, ד צויין אליו באוה\"ת שם, וכן הבא להלן. מאמרי אדה\"ז תקס\"ט ע' קמ. הנחות הר\"פ ע' קנט [הובא גם בתוס' הגהות וכו' באוה\"ת ואתחנן ע' שכ]."],["624","123","<b>אברהם . . חסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["625","124","<b>אהרן . . חסד</b>: ראה ת\"י ברכה לג, ח. שמו\"ר פ\"ה, י. תו\"ח שמות ח\"א לז, ג. וש\"נ."],["626","125","<b>שאית חסד ואית חסד</b>: זהר אד\"ר נשא קלג, ב. ראה אגה\"ק ס\"י. סוסי\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעז. וש\"נ."],["627","126","<b>דאקרי רב חסד</b>: שם אמר חסד דלגאו אך פשוט דר\"ל רב חסד דהרי פי' זה על תיקון השישי מי\"ג מדה\"ר שהוא ורב חסד — אוה\"ת תצוה ע' א'תקפז [ושם מציין: דקל\"ז ע\"ב. וכנשצ\"ל כבהערה שלפנ\"ז קלג, ב]."],["628","127","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר לך פ, א. פד, א. אוה\"ת לך כרך ד ע' 1398."],["629","128","<b>מנורה בדרום</b>: תרומה כו, לה. פקודי מ, כד. יומא לג, ריש ע\"ב."],["630","129","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה אוה\"ת וארא ע' קמד."],["631","130","<b>רב חסד</b>: ע\"פ תשא לד, ו. ראה אוה\"ת שם ע' קמה."],["632","131","<b>דחילו ורחימו ורחימו ודחילו</b>: ראה זהר רע\"מ נשא קכג, סע\"א. תו\"א מקץ מ, ד ואילך. מא, סע\"ג ואילך. לעיל מאמר ד\"ה והי' אור הלבנה רפ\"ג. וש\"נ."]]],[2001910118,"ודחילו מבחי' י\"ה שמאיר בו\"ה מבחי' רב חסד כו'. והנה אהרן הוא שושבינא דמטרוניתא<sup data-n=\"633\">132</sup> ומשה הוא שושבינא דמלכא<sup data-n=\"634\">133</sup>, והיינו שאהרן הוא מעלה את נש\"י והיינו כי כדי שיהי' המשכת ש' הוי' שלמעלה מבחי' שמש הוי' צריך שיהי' העלאה לזה דהיינו שיהי' לו רצון ותשוקה לעצמותו ית' כו', וזהו ע\"י אהרן שניתן לו כח מלמעלה שיכול להעלות את נש\"י, ומשה הוא בחי' שושבינא דמלכא שהוא ממשיך את בחי' ש' הוי' מלמעלה למטה. ובזה יובן התירוץ של רבינו ז\"ל שכדי להוציא בנ\"י ממצרים הי' אהרן העיקר והיינו לפי שתחלה צריך שיהי' העלאה מלמטה למעלה ועי\"ז יוכל אח\"כ להיות המשכת ש' הוי', ואהרן הוא שושבינא דמטרוניתא שהוא המעלה את נש\"י ע\"כ בפסוק הוא אהרן נא' מתחלה הוא אהרן ומשה, אך לדבר אל פרעה מלך מצרים הי' משה עיקר. והענין הוא שפרעה אותיות הערף<sup data-n=\"635\">134</sup> בחי' עקשות קשה עורף<sup data-n=\"636\">135</sup> והגביה א\"ע בחוצפא לומר לא ידעתי את הוי', מי הוי'<sup data-n=\"637\">136</sup> כו', שזהו בחי' גיאות מאד, ולכן הי' צריך להיות נמשך מבחי' כי גאה גאה, שמתגאה על גיוותנייא<sup data-n=\"638\">137</sup>, אך בחי' כי גאה גאה אינו שורה כ\"א במי שבטל אצלו בתכלית, וכמו שהשראת אוא\"ס הוא בחכמה לפי שחכ' הוא כח מה<sup data-n=\"640\">139</sup> ביטול כמ\"ש בסש\"ב פל\"ה בהג\"ה<sup data-n=\"639\">138</sup>, וזהו בחי' משה דוקא שהי' בבחי' מה בחי' ביטול וכמ\"ש ונחנו מה<sup data-n=\"641\">140</sup>, והגם שקאי על אהרן ג\"כ, וכתי' ואהרן מה הוא<sup data-n=\"642\">141</sup>, מ\"מ אהרן הוא בחי' ב\"ן דמ\"ה ומשה הוא בחי' מ\"ה דמ\"ה<sup data-n=\"643\">142</sup>, לכן המדבר אל פרעה הי' משה עיקר, וזהו שבפסוק הם המדברים כו' מסיים הוא משה ואהרן. והנה מ\"ש הוא אהרן ומשה, הוא משה ואהרן שהי' צריך לכתוב הם משה ואהרן, הענין הוא דהנה עתה ש' הוי' ושם אלקים הם שני בחי' ששם אלקים מסתיר על ש' הוי' וכמ\"ש כי שמש ומגן הוי' אלקים שהוא בחי' מאור הגדול ומאור הקטן<sup data-n=\"644\">143</sup>, אך במשה ואהרן הי' שני הבחי' של ש' הוי' ושם אלקים הכל בחי' א' וכמ\"ש וידעת היום<sup data-n=\"645\">144</sup> כו' כי הוי' הוא האלקים שכולא חד<sup data-n=\"646\">145</sup> כו', וכמ\"ש ויעש אלקים את שני המאורות",[["633","132","<b>אהרן הוא שושבינא דמטרוניתא</b>: ראה זהר רע\"מ ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["634","133","<b>ומשה הוא שושבינא דמלכא</b>: ראה זהר שם. מצורע נג, ב. רע\"מ שופטים ערה, ב. תו\"ח שמות ח\"א יא, ג הערה 510."],["635","134","<b>שפרעה אותיות הערף</b>: ראה לקו\"ת להאריז\"ל שמות עה\"פ (א, ח) ויקם מלך חדש בתחילתו. שער הפסוקים פ' וישב (לט, א) סט\"ל. סה\"מ תר\"ם ח\"ב ע' תרנה. וש\"נ."],["636","135","<b>קשה עורף</b>: לשון הכתוב תשא לג, ג."],["637","136","<b>לא ידעתי . . מי הוי'</b>: שמות ה, ב [בהיפך הסדר]."],["638","137","<b>כי גאה גאה . . גיוותנייא</b>: בשלח טו, א. ראה ת\"א שם."],["640","139","<b>שחכ' הוא כח מה</b>: זהר רע\"מ צו כח, א. לד, א."],["639","138","<b>אוא\"ס הוא בחכמה . . פל\"ה בהג\"ה</b>: ראה גם לקמן מאמר ד\"ה ובירך את לחמך ובהערה 11."],["641","140","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ. לעיל מאמר ד\"ה והי' אור הלבנה על יד הערה 82."],["642","141","<b>ואהרן מה הוא</b>: קרח טז, יא."],["643","142","<b>אהרן . . ב\"ן דמ\"ה ומשה . . מ\"ה דמ\"ה</b>: ראה תו\"א מג\"א צט, ג. אוה\"ת תצוה ע' א'תרו. ע' א'תרכג. סה\"מ תר\"ם ח\"א ע' קעח. וש\"נ."],["644","143","<b>הוי' אלקים . . מאור הגדול ומאור הקטן</b>: זהר בראשית כ, א."],["645","144","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם סה\"מ תר\"ם ח\"א ע' קט ואילך."],["646","145","<b>הוי' הוא האלקים שכולא חד</b>: ראה זהר בהקדמה יב, א. וארא כו, ב. תרומה קסא, א ואילך. רע\"מ ואתחנן רסד, א. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. תו\"ח וארא ח\"א ס, א. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ."]]],[2001910119,"הגדולים<sup data-n=\"647\">146</sup> שקודם החטא היו שניהם שוים כו', וכך במשה ואהרן הי' מאיר בחי' ש' הוי' בעצמו ולא הי' שם אלקים מסתיר כלל, לפי ששניהם הם בחי' המאורות הגדולים וע\"כ נא' הוא משה ואהרן ששניהם שוין שכולא חד כו'.\n<b>ומעתה</b> יובן ג\"כ מ\"ש שלא מנה רק ג' שבטים אלו, היינו כדי רק להודיע שמשה הי' דור שביעי שהוא כמו שבת לגבי חול כנגד אברהם שמשמע מזה שהוא גדול מאברהם, ומהמדרש שא\"ל במקום גדולים אל תעמוד משמע שאברהם גדול ממשה. אך הענין הוא דהנה כתי' אלה תולדות מלא והיינו שבשעת בריאת העולמות הי' מאיר בחי' הששה מדות בבחי' גילוי כו' ואח\"כ ע\"י חטא אדה\"ר כתי' תולדת חסר ו'<sup data-n=\"648\">147</sup> שאינו מאיר המדות בבחי' גילוי כו', ולכך נחסר ו' דברים<sup data-n=\"649\">148</sup> כו', אך תולדות השמים והארץ בהבראם באברהם היינו שאברהם המשיך את בחי' ו' מדות בבחי' גילוי כמו קודם חטא עה\"ד וכמו שהיו מאירים בשעת בריאת העולמות שהי' תולדות מלא כו', וכך אברהם המשיך את המדות בגילוי כו', אך מ\"מ הששה מדות נק' ששת ימי החול וכמ\"ש כי ששת ימים עשה<sup data-n=\"650\">149</sup> כו', משא\"כ בשבת כתי' ויברך אלקים את יום השביעי שהוא שביעאה דהיינו בחי' בינה<sup data-n=\"651\">150</sup>, וגם שבת דיומא<sup data-n=\"652\">151</sup> הוא בחי' מוחין דאבא<sup data-n=\"653\">152</sup> שלמעלה הרבה מבחי' מדות שאינם בערך כלל, לפי שמדות לגבי בינה נק' בחי' בריאה מאין ליש וכמ\"ש מי ברא אלה<sup data-n=\"654\">153</sup>, אלה הוא ו\"ק<sup data-n=\"655\">154</sup>, ופ\"ו הוא בגימ' אלה, מבטן מי יצא הקרח<sup data-n=\"656\">155</sup> כו', נמצא ששבת הוא אינו בערך לגבי בחי' מדות כו', והנה משה שהי' דור שביעי הוא כמו בחי' שבת לגבי אברהם, לפי שמשה הוא בחי' חכ'<sup data-n=\"657\">156</sup> שהוא בחי' שבת, והגם שאהרן הי' ג\"כ דור שביעי כו', אך י\"ל ההפרש שבין משה לאהרן הוא כמו בין שבת ליו\"ט<sup data-n=\"658\">157</sup> שביו\"ט העיקר הוא מוחין דאימא רק שנמשך הארה מבחי' מוחין דאבא לבחי' מוחין דאימא וכמ\"ש מקרא קדש<sup data-n=\"659\">158</sup> כו', משא\"כ שבת העיקר הוא מוחין דאבא כו', וזהו ג\"כ ההפרש שבין",[["647","146","<b>ויעש . . המאורות הגדולים</b>: בראשית א, טז. ראה רש\"י שם מחולין ס, ב."],["648","147","<b>אלה תולדות מלא . . חסר ו'</b>: ראה ב\"ר שבהערה הבאה. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ ובהערה 101."],["649","148","<b>נחסר ו' דברים</b>: ראה ב\"ר פי\"ב, ו. סה\"מ תר\"ם ח\"א ע' קה. וש\"נ."],["650","149","<b>כי ששת ימים עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["651","150","<b>שביעאה . . בינה</b>: ראה זהר בשלח סג, ב. יתרו פח, א. בראשית מז, ב. לקו\"ת צו יא, א. אוה\"ת בראשית כרך ג' ס\"ע 1024 ואילך. ע' 1026. המשך תער\"ב ח\"ב ע' א'פח ואילך."],["652","151","<b>שבת דיומא</b>: זהר בהקדמה ה, ב."],["653","152","<b>שבת . . מוחין דאבא</b>: ראה בסמוך הערה 157."],["654","153","<b>מי ברא אלה</b>: ישעי' מ, כו. ראה גם סה\"מ תרל\"ח ע' רז ובהנסמן שם."],["655","154","<b>אלה הוא ו\"ק</b>: ראה גם לקו\"ת פקודי ד, ג. ז, א. תו\"ח נח נו, ב ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268. לקמן מאמר והנחה ד\"ה בגמ' וכו' קא מפלגי פ\"ג."],["656","155","<b>מבטן מי יצא הקרח</b>: איוב לח, כט."],["657","156","<b>שמשה . . חכ'</b>: ראה בסמןך הערה 159."],["658","157","<b>ההפרש . . בין שבת ליו\"ט</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. לקו\"ת צו יא, ד. בחוקותי מז, ג. שע\"ת צח, ב (בשם הע\"ח). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. סה\"מ תרכ\"ז ע' תפט. וש\"נ."],["659","158","<b>מקרא קדש</b>: בא יב, טז. ועוד."]]],[2001910120,"אהרן למשה ששניהם הם בחי' דור שביעי, אך אהרן הוא בחי' מוחין דאימא בחי' בינה ומשה הוא בחי' מוחין דאבא בחי' חכ'<sup data-n=\"660\">159</sup> שהוא בחי' שבת, נמצא שמשה הי' למעלה מאברהם, אך אעפ\"כ מה שמשה הוא למעלה ונק' שבת אין זה מצד כח עצמו רק שניתן לו כח וגדולה מלמעלה וכמשארז\"ל ע\"פ לך רד כלום נתתי<sup data-n=\"661\">160</sup> לך גדולה אלא בשביל ישראל ולא שזכה לגדולה זו מצד עצמו, משא\"כ אברהם זכה לבחי' זו מצ\"ע וכמ\"ש באברהם התהלך לפני<sup data-n=\"662\">161</sup> כו' שהי' הולך מצ\"ע בלי סיוע מלמעלה, והגם שנא' בנח ג\"כ את האלקים התהלך נח<sup data-n=\"663\">162</sup>, אך מ\"מ כתי' את האלקים שהיו מסייעין אותו מלמעלה, משא\"כ אברהם התהלך בכח עצמו בלי סיוע מלמעלה, וכל מה שהגיע למעלה הי' הכל ע\"פ אתעדל\"ת שלו בלי סיוע מלמעלה, ובבחי' אתעדל\"ת הי' אברהם גדול ממשה. והנה משה רצה להדמות א\"ע לאברהם באתעדל\"ת ועבודה שלו לזה א' לו אל תתהדר לפני מלך ובמקום גדולים אל תעמוד אף שהי' משה למעלה מאברהם אך זהו מצד הכח והגדולה שניתן לו מלמעלה אבל לא מצ\"ע כו' כי בבחי' זו הי' אברהם גדול ממשה אחד הי' אברהם<sup data-n=\"664\">163</sup>, האדם הגדול בענקים<sup data-n=\"665\">164</sup>, שבבחי' זו אברהם נק' גדול, וע\"כ במקום גדולים אל תעמוד כו'.",[["660","159","<b>אהרן . . בינה ומשה . . חכ'</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רמא. סה\"מ תרל\"ח ע' רז. וש\"נ."],["661","160","<b>לך רד כלום נתתי</b>: תשא לב, ז. ברכות לב, א. רש\"י תשא שם."],["662","161","<b>התהלך לפני</b>: לך יז, א. ראה הערה הבאה."],["663","162","<b>את האלקים התהלך נח</b>: נח ו, ט. ראה תנחומא נח ה. ב\"ר פ\"ל, י. רש\"י נח שם."],["664","163","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["665","164","<b>האדם הגדול בענקים</b>: יהושע יד, טו וברש\"י שם (בשם מדרש אגדה) ובאיוב לב, ב. ב\"ר פי\"ד, ו. במדב\"ר פי\"ג, ג. סה\"מ תרל\"ח ע' ר. וש\"נ."]]],[2001910121,"<h3>אז ישיר משה</h3>\n<b>פ' בשלח</b>\n<b>אז</b> ישיר משה<sup data-n=\"666\">1</sup> ובנ\"י כו' וצ\"ל מ\"ש ישיר לשון יחיד דהל\"ל ישירו לשון רבים<sup data-n=\"667\">2</sup> כו', הנה כתיב כמגדל דוד צוארך<sup data-n=\"668\">3</sup>, וארז\"ל ברבות במקומו מה שגידל אתכם דוד בספרו, ומה גידל אתכם דוד בספרו לגוזר ים סוף לגזרים (תילים קל\"ו י\"ג),",[["666","1","<b>אז ישיר משה</b>: מאמר זה וכן המאמר שנדפס לאח\"ז מאמר ד\"ה זכור את יום השבת מיוסדים על מאמר ד\"ה אז ישיר משה בסה\"מ תרכ\"ט ע' קמד. וש\"נ. ראה גם סה\"מ תרצ\"ב ע' ר. וש\"נ.\nמאמר זה נרשם בגוכתי\"ק ומתחילה הפתיחה היתה: כמגדל דוד צוארך (והכותרת שבריש המאמר היתה: בס\"ד שה\"ש ד' ד' ) אלא שאח\"כ ניתוסף ממעל לפסוק זה הפסוק אז ישיר וכו' כבפנים. בבוך תרמ\"א 2086 — כת\"י מעתיק — הכותרת: פ' בשלח.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו.\nהמאמר נזכר בהמאמר שלאח\"ז ד\"ה זכור את יוה\"ש פ\"ב . פ\"ו."],["667","2","<b>אז ישיר משה ובנ\"י . . ישירו לשון רבים</b>: בשלח טו, א. ראה שמו\"ר פכ\"ג, ט."],["668","3","<b>כמגדל דוד צוארך</b>: שה\"ש ד, ד. שהש\"ר שם."]]],[2001910122,"ולכאורה צ\"ל מהו מעלת ענין הגדלה זו שסיפר שהים נגזר לגזרים, הלא בפ' בשלח בסיפור קרי\"ס נא' באריכות יותר איך ששם הים לחרבה, ושהלכו בנ\"י בתוך הים ביבשה כו', דכתיב ואתה הרם כו' ויבואו בנ\"י בתוך הים ביבשה<sup data-n=\"669\">4</sup>, וכתיב אח\"כ ויט כו' וישם את הים לחרבה<sup data-n=\"670\">5</sup> כו', ויבואו בנ\"י בתוך הים והמים להם חומה<sup data-n=\"671\">6</sup> כו', ומה הגדיל כ\"כ דוד בספרו באמרו לגוזר י\"ס כו', אך הנה עכ\"פ מזה מובן שמעלת בנ\"י הוא למעלה יותר מבחי' הים, ופעם מצינו שע\"י הים נתעלו בנ\"י ונתגדלו וכענין שארז\"ל ברבות ראה הפחות שבפחותים בימי משה מה שלא ראה הגדול שבנביאים<sup data-n=\"672\">7</sup>, ורש\"י ז\"ל פי' ע\"פ זה אלי<sup data-n=\"673\">8</sup> ראתה שפחה על הים מה שלא ראו נביאים, והוא מהמכילתא הובא בילקוט רמז רמ\"ד, והיינו כי בנביאים כתי' וביד הנביאים אדמה<sup data-n=\"674\">9</sup> שהוא בחי' כה, כדמותינו<sup data-n=\"675\">10</sup>, רק משה נתנבא בזה<sup data-n=\"676\">11</sup>, ובשעת קרי\"ס כל או\"א הראה באצבע<sup data-n=\"677\">12</sup> ואמר זה אלי שזכו כולם לידי גילוי בחי' זה שהוא כערך נבואת משה<sup data-n=\"678\">*13</sup>, ולכן שבחו ברבות יורדי הים שאמרו כמה גדולים יורדי הים<sup data-n=\"679\">13</sup> שמשה רבן של כל הנביאים<sup data-n=\"680\">14</sup> כמה נתחבט עד שביקש הראיני נא את כבודך<sup data-n=\"681\">15</sup> כו', ויורדי הים זכו כולם לגילוי בחי' זה אלי, ונמצא מכ\"ז מובן שישראל נתגדלו ע\"י הים, וממ\"ש כמגדל דוד, שגידל אתכם דוד בספרו משמע שישראל הם גדולים מהים, וכתי'<sup data-n=\"682\">16</sup> בוקע ים לפני משה<sup data-n=\"683\">17</sup> שכיון שראה הים משה ובנ\"י נתבטל ונקרע לפניהם, וכן ברבות בשלח פך\"א<sup data-n=\"684\">18</sup> משמע שהים גדול ממשה שא\"ל אני גדול ממך שאני נבראתי בשלישי, ואתה<sup data-n=\"685\">19</sup>",[["669","4","<b>ואתה הרם . . ביבשה</b>: בשלח יד, טז."],["670","5","<b>ויט . . הים לחרבה</b>: בשלח שם כא."],["671","6","<b>ויבואו בנ\"י . . להם חומה</b>: שם שם, כב [בדילוג]."],["672","7","<b>ברבות ראה הפחות . . שבנביאים</b>: וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן. סה\"מ תרכ\"ט כאן ע' קמה. ובחלק הדרושים שנסמנו בסה\"מ שם בריש המאמר — דב\"ר פ\"ז, ח.\nבדב\"ר שם: ראה הפחות בימי משה מה שלא ראה יחזקאל גדול בנביאים בני אדם שדברה עמהם שכינה פנים בפנים שנאמר (ואתחנן ה, ד) פנים בפנים דבר ה' עמכם וגו'. ובסה\"מ קיץ ה'ש\"ת כאן ע' 58 כותב ע\"ז בהערה: וצ\"ע."],["673","8","<b>ורש\"י . . זה אלי</b>: בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. תו\"ח בשלח ח\"א קצד, ב ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך."],["674","9","<b>וביד הנביאים אדמה</b>: הושע יב, יא."],["675","10","<b>כדמותינו</b>: לשון הכתוב בראשית א, כו. ראה גם לקו\"ת נצבים מז, ב. לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א."],["676","11","<b>משה נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29. אוה\"ת מטות ע' א'תצד. וראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"א."],["677","12","<b>כל או\"א הראה באצבע</b>: ראה שמו\"ר שבהערה 13."],["678","*13","<b>שהוא כערך נבואת משה</b>: ראה גם אוה\"ת בשלח ע' תמב — נדפס גם בביאוה\"ז להצ\"צ כרך ב' ע' תשמז. סה\"מ תרל\"א שבהערה שלאח\"ז. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["679","13","<b>ברבות . . כמה גדולים יורדי הים</b>: ראה שמו\"ר פכ\"ג, טו. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ז. סה\"מ תרל\"א ח\"א ע' רסז ואילך."],["680","14","<b>שמשה רבן של כל הנביאים</b>: לשון שמו\"ר פכ\"א, ד. דב\"ר פ\"ב, א. רמב\"ם הל' יסודי התורה פ\"ז, ה\"ו."],["681","15","<b>הראיני נא את כבודך</b>: תשא לג, יח."],["682","16","<b>וכתי'</b>: מצינו בכמה מקומות בחז\"ל על נוסח תפלה עתיקה הביטוי ”דכתיב\" (זח\"א לד, א. ובכ\"מ. תוד\"ה נשים ברכות כ, ב) — סה\"מ תש\"ט ע' 150 בהערה ע\"ש. הערות ותיקונים לתניא ספל\"ו."],["683","17","<b>בוקע ים לפני משה</b>: נוסח ברכת אמת ואמונה (תפלת ערבית)."],["684","18","<b>ברבות בשלח פך\"א</b>: סימן ו."],["685","19","<b>ואתה</b>: וכ\"ה בסה\"מ תרל\"א ח\"א ריש ע' רעח. סה\"מ תרנ\"ה כאן ע' פא. עטר\"ת ע' רח. ש\"ת כאן ס\"ע 60. ובשמו\"ר שם: ואת."]]],[2001910123,"נבראת בששי, ומ\"מ ממה שא' אח\"כ וישב הים כו' לאיתנו<sup data-n=\"686\">20</sup> שפי' לתנאו<sup data-n=\"687\">21</sup> שתנאי התנה הקב\"ה עם הים שיקרע לפני בנ\"י משמע שישראל גדולים יותר מהים. אך הענין הוא דהנה כדוגמא זו מצינו בתורה ג\"כ שפעם מצינו שנש\"י גדולים ממעלת התורה, ופעם בהיפך שהתורה גבהה<sup data-n=\"688\">22</sup> מעלתה על נש\"י, דהנה בתד\"א אמר שני דברים קדמו לעולם<sup data-n=\"689\">23</sup> תורה וישראל וא\"י איזהו מהם קדום, היינו שבשני דברים אלו עצמן איזהו מהם קדום, אומר אני שישראל קדמו, והראי' לזה<sup data-n=\"690\">24</sup> מפני שכל התורה מדבר בציוי ישראל, צו את בנ\"י<sup data-n=\"691\">25</sup>, דבר אל בנ\"י<sup data-n=\"692\">26</sup>, וא\"כ ישראל קדמו, וכ\"ה ברבות ג\"כ בענין ז' דברים קדמו לעולם שחשיב בז' דברים אלו גם התורה, ועכ\"ז אומר אח\"כ שמחשבתן של ישראל<sup data-n=\"693\">27</sup> קדמו<sup data-n=\"694\">28</sup> לכ\"ד, שנמצא שישראל עלו במחשבה<sup data-n=\"695\">29</sup> תחילה, וכן מובן ממ\"ש תורה צוה לנו משה מורשה<sup data-n=\"696\">30</sup> כו', וארז\"ל א\"ת מורשה אלא מאורסה<sup data-n=\"697\">31</sup>, שהתורה נק' כלה מאורסה לאיש, שנמצא נק' כנס\"י בשם חתן, וא\"כ נש\"י הם משפיעים בבחי' תורה, ופעם משמע בהיפך שהרי איתא בזהר תלת קשרין<sup data-n=\"698\">32</sup> מתקשראין דא בדא ישראל מתקשראין באורייתא, ואורייתא בקוב\"ה, נמצא שמעלת התורה גבוה יותר ממעלת נש\"י שהרי ע\"י אמצעית התורה מתקשראין נש\"י להקב\"ה, שענין בחי' האמצעית זו הוא מה שהתורה היא ממוצע לחבר נש\"י להקב\"ה.\nב) <b>והענין</b> הוא שבאמת שניהם אמת, ואלו ואלו דא\"ח<sup data-n=\"699\">33</sup>, דהנה לא כל הנשמה מלובש בגוף<sup data-n=\"700\">34</sup>, שמה שמלובש בגוף הנה הוא רק הארה ומקצת מהנשמה, שהרי הנשמה גבוה מהמלאך<sup data-n=\"701\">*35</sup> כנודע ששרש המלאכים הם מבחי'",[["686","20","<b>וישב הים כו' לאיתנו</b>: בשלח יד, כז."],["687","21","<b>לאיתנו שפי' לתנאו</b>: ראה לעיל הערה 18. ראה גם לקו\"ש בשלח כרך ו' ע' 86 ואילך. וש\"נ."],["688","22","<b>שנש\"י גדולים . . שהתורה גבהה</b>: ראה גם (בנוסף להמצויין בהערה 1) לקו\"ת שה\"ש טז, ד. יז, ד ואילך."],["689","23","<b>בתד\"א אמר שני דברים קדמו לעולם</b>: רבא קרוב לספי\"ד בשינויים. ראה גם סה\"מ תר\"ם ח\"ב ס\"ע תקכא ואילך. וש\"נ."],["690","24","<b>והראי' לזה</b>: ראה ב\"ר פ\"א, ד. לקו\"ת שה\"ש טז, ד. סה\"מ תר\"ם שם ע' תקכב הערה 358."],["691","25","<b>צו את בנ\"י</b>: ויקרא כד, ב. ועוד."],["692","26","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["693","27","<b>ברבות . . ז' דברים . . שמחשבתן של ישראל</b>: ראה ב\"ר פ\"א, ד. פי' מהרז\"ו הארוך שם. מאמרי אדה\"א דברים ח\"ב ע' שע בהערה. סה\"מ תרל\"ט ח\"ב ע' תנד. וש\"נ."],["694","28","<b>קדמו</b>: כ\"ה בגוכתי\"ק. וכ\"ה בסה\"מ עטר\"ת כאן."],["695","29","<b>שישראל עלו במחשבה</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו רפ\"ב ובהנסמן שם."],["696","30","<b>תורה צוה לנו משה מורשה</b>: ברכה לג, ד."],["697","31","<b>א\"ת מורשה אלא מאורסה</b>: ברכות נז, א. ראה גם שער האמונה סט, א הערה 12. סה\"מ תרל\"ח ע' קנה."],["698","32","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צט. קונטרסים ע' שלט."],["699","33","<b>ואלו ואלו דא\"ח</b>: ערובין יג, ב. ראה גם מאמרי אדה\"א נ\"ך ע' שלט ואילך. תו\"ח תצוה ח\"ב שמט, ד. לקו\"ש ויצא כרך טו ע' 233 ואילך. וש\"נ."],["700","34","<b>לא כל הנשמה מלובש בגוף</b>: ראה תו\"א תשא פו, ב. לעיל מאמר ד\"ה והי' אור הלבנה הערה 17."],["701","*35","<b>הנשמה גבוה מהמלאך</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' והערה 46."]]],[2001910124,"חיצוניות הכלים, והנשמות הם מבחי' פנימיות הכלים<sup data-n=\"702\">35</sup>, ועכ\"ז המלאך בשליש העולם עומד<sup data-n=\"703\">36</sup>, ואיך הנשמה שגבוה מבחי' המלאך יכילנה גוף קטן כמו האדם, אלא שעיקר הנשמה היא למעלה שע\"ז נא' ונוזלים מן לבנון<sup data-n=\"704\">37</sup> שהיא בבחי' לובן העליון<sup data-n=\"705\">38</sup> ומשם היא נוזלת ומטפת הארה לבחי' הנשמה שמלובשת בגוף כו', ומזה נופלים לאדם הרהורי תשובה, שאע\"ג דאיהו לא חזי מזליהו חזי<sup data-n=\"706\">39</sup> ששם היא רואה ושומעת הכרוזים שלמעלה שמעוררי' על התשובה, וכן מ\"ש בפ\"ו דאבות שבי\"ו ויום<sup data-n=\"707\">40</sup> ב\"ק יוצאת מהר חורב ומכרזת ואומרת אוי להם לבריות מעלבונה של תורה כו', שמזליה שומעת הכרוז וגם רואה<sup data-n=\"708\">41</sup> כמ\"ש במ\"א עי\"ז נופלים לאדם הרהורי תשובה מפני שמטפת הארתה לבחי' הנשמה המלבשת<sup data-n=\"709\">42</sup> בגוף כו'. וע\"פ הקדמה זו יובן איך ששניהם אמת, שמחמת הארת הנשמה המלובשת בגוף, והגוף והנה\"ב מעלימים ומסתירים על הארת אור הנשמה שעז\"נ יונתי בחגוי הסלע<sup data-n=\"710\">43</sup> בסתר המדריגה כמ\"ש במ\"א, התורה היא למעלה מישראל, וישראל מתקשראין באורייתא, וע\"י אמצעות התורה מתקשרת הנשמה שמלובשת בגוף להקב\"ה, ועי\"ז נמשך המשכת אלקות בעולמות כמ\"ש הליכות עולם לו<sup data-n=\"711\">44</sup> שיש בזה ב\"פ<sup data-n=\"712\">45</sup> הא' מלמטלמ\"ע ע\"י התפילה<sup data-n=\"713\">46</sup> כו' כמ\"ש במ\"א והב' מלמעלמ\"ט ע\"י התורה, שישראל מתקשראין באורייתא ועי\"ז נמשך הארת אוא\"ס בחי' קוב\"ה בעולם ע\"י התורה שהיא הממוצע לחבר ולהמשיך אוא\"ס בעולם, וכמ\"ש עוטה אור כשלמה שקאי על בחי' תורה<sup data-n=\"714\">47</sup> שנק' שלמה לשון",[["702","35","<b>המלאכים . . חיצוניות . . פנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. תו\"א יתרו עב, ב. לקו\"ת פ' ראה כו, סע\"ג ואילך. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. תו\"ח בשלח ח\"א רמ, ד ואילך."],["703","36","<b>המלאך בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. מורה נבוכים ח\"ב, פ\"י. לקו\"ת האזינו עד, סע\"ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' ק [ובמהדורת תשס\"ד ע' רד] ”שהוא ק\"ס שנה\". סידור שער החנוכה רעו, א ”קס\"ו וב\"ש שנה\"."],["704","37","<b>ונוזלים מן לבנון</b>: שה\"ש ד, טו. ראה לקו\"ת האזינו עא, ד."],["705","38","<b>לבנון . . לובן העליון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפ. תקס\"ב ח\"א ע' פו. תקס\"ד ע' קעד."],["706","39","<b>שאע\"ג דאיהו . . מזליהו חזי</b>: מגילה ג, א."],["707","40","<b>בפ\"ו דאבות שבי\"ו </b> [שבכל יום]<b> ויום</b>: ה\"ב. בגוכתי\"ק אינו ברור כ\"כ ואולי כצ\"ל."],["708","41","<b>שמזליה שומעת הכרוז וגם רואה</b>: ראה ס' חרדים מצות התשובה פ\"ז. הובא בשל\"ה דרך חיים תוכחת מוסר רמג, ב. כש\"ט קה\"ת סקמ\"ו. סרנ\"ה. לקו\"ת תצא לו, ד. האזינו עא, ד. שה\"ש כד, א. שלח מו, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלג. מאמרי אדה\"א דברים ח\"ד ע' א'קעא ואילך ובהנסמן שם. המשך מים רבים תרל\"ו פקפ\"א (ריש ע' רג). המשך תרס\"ו ע' שצט."],["709","42","<b>המלבשת</b>: אוצ\"ל: המלובשת."],["710","43","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד. בסה\"מ קיץ ה'ש\"ת כאן ע' 66 מציין: וראה לקו\"ת ע\"פ זה. ראה גם סה\"מ תר\"ם ח\"ב ע' תקסג ובהנסמן שם."],["711","44","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["712","45","<b>שיש בזה ב\"פ</b>: ראה גם תו\"א וישב ל, ד. מאמרי אדה\"ז תקס\"ט ע' קלא ואילך ובהנסמן שם. תו\"א מקץ לח, ג. שע\"ת קב, ג. סה\"מ תרל\"ג ח\"ב ע' תכג ואילך (ובהנסמן בריש המאמר שם). תר\"ם ח\"ב ע' תרמה."],["713","46","<b>מלמטלמ\"ע ע\"י התפילה</b>: ראה גם סה\"מ תרס\"ה כאן ריש ע' קכב."],["714","47","<b>עוטה אור כשלמה . . תורה</b>: תהלים קד, ב. ראה גם לקו\"ת שמע\"צ פו, א. מאמרי אדה\"ז תק\"ע ע' פג. סידור שער הציצית ג, סע\"ד. אמרי בינה שם פג, ג. ש\"א לט, א ובהערה 1. סה\"מ תרנ\"ה כאן ע' פב בשולי הגליון."]]],[2001910125,"לבוש שהיא לבושו של הקב\"ה<sup data-n=\"715\">48</sup> שע\"י שמתלבש בלבוש התורה עי\"ז נמשך המשכת אוא\"ס בעולם.\n<b>וענין</b> ב' בחי' אור ושלמה שבתורה, יובן ע\"פ משנ\"ת שהתורה היא ממוצע בין הקב\"ה לישראל, וכן היא ממוצע בין אוא\"ס לעולמות<sup data-n=\"716\">49</sup> כמ\"ש בזהר אסתכל באורייתא וברא עלמא<sup data-n=\"717\">50</sup> וכמ\"ש בראשית וארז\"ל בשביל התורה<sup data-n=\"718\">51</sup> שנק' ראשית, וע' ברבות בהתחלתו בענין ואהי' אצלו אמון<sup data-n=\"719\">52</sup> שהתורה היא כלי אומנתו של הקב\"ה, וכל ממוצע צ\"ל כלול משני הבחי' שמחברם<sup data-n=\"720\">53</sup> יחד, וז\"ע אור ושלמה שבתו', שבחי' אור דתורה זהו מה שהיא כלולה מבחי' אור א\"ס הבלתי בע\"ג ובלתי בעת\"כ, ובחי' שלמה שהוא בחי' הלבוש דתורה זהו שרש ומקור בחי' הגבול שהרי כל דיני הלכות התורה הם מוגבלים אלו טרפות ואלו כשרות<sup data-n=\"721\">54</sup>, וזהו מה שישראל מתקשראין באורייתא, ואורייתא בקוב\"ה, שהנשמה המלובשת בגוף מוגבל כו' וכדי שיתחבר לאוא\"ס הבלתי בע\"ג שזהו בחי' קוב\"ה זהו ע\"י התורה שיש בה ב' הבחי' דאור ושלמה, שהם ב' בחי' שבהממוצע כו'. ולכן ארז\"ל בפתיחתא דאיכה הלואי אותי עזבו ותורתי שמרו<sup data-n=\"723\">56</sup> המאור<sup data-n=\"722\">55</sup> כו', שהגם אם ח\"ו אותי עזבו כבי', מ\"מ המאור שבה היינו בחי' אור* שבתורה מחזירן למוטב, שיש בכח התורה לקשר הנשמה שבגוף\n\n)\n<i>נרשם בשולי היריעה כאן ולא נסמן מקומו בפנים, ואולי שייך לכאן:</i>\nאור ומאור חשיב לברי'[ftnref_8178_א] א', כי שניהם מע\"י כי או\"ת זהו גשם[ftnref_8179_ב] שבעתיים כאור זה\"י[ftnref_8180_ג] שנת' בד\"ה תורה צוה שזהו ז\"ת דעת\"י[ftnref_8181_ד], ומאור י\"ל שזהו ג\"ר דעתיק, או ת\"ת דעת\"י, ובכלל שניהם הם בחי' שעשועי המלך[ftnref_8182_ה] כו' שלא ידע אנוש ערכה[ftnref_8183_ו] בחי' מאד עמקו מחשבותיך[ftnref_8184_ז] שנת' בד\"ה דוד זמירות קרית[ftnref_8185_ח], שי\"ל איך אמר אח\"כ שעשועי' יום יום[ftnref_8186_ט] אאלפך חכ'[ftnref_8187_י], זהו מפני שפנימיות אבא פנימיות עת\"י[ftnref_8188_יא].",[["715","48","<b>תורה . . לבושו של הקב\"ה</b>: ראה תניא פנ\"ב."],["716","49","<b>שהתורה . . ממוצע בין אוא\"ס לעולמות</b>: ראה גם אוה\"ת ואתחנן כרך ו ע' ב'רסה. המשך תער\"ב ח\"א ע' שכד ואילך."],["717","50","<b>אסתכל באורייתא וברא עלמא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט ואילך."],["718","51","<b>בראשית וארז\"ל בשביל התורה</b>: בראשית א, א. ראה רש\"י שם. לקו\"ש נח כרך ג ע' 755 בהערה."],["719","52","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["720","53","<b>ממוצע צ\"ל כלול . . שמחברם</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. סידור שער הל\"ג בעומר שו, ב. אוה\"ת בשלח ע' תקע ואילך."],["721","54","<b>אלו טרפות ואלו כשרות</b>: חולין פ\"ג, מ\"א. מ\"ב."],["723","56","<b>הלואי אותי עזבו ותורתי שמרו</b>: פי' הכתוב ירמי' טז, יא [ושם: ואותי . . ואת תורתי לא שמרו]."],["722","55","<b>בפתיחתא דאיכה . . המאור</b>: איכ\"ר שם ב. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה ספ\"ב. וש\"נ.\n\n[ftn_8178_א])<i>לברי':</i> אולי כתוב לבחי'.\n\n[ftn_8179_ב])<i>כי או\"ת [ אור תורה] זהו גשם: </i>ראה גם סה\"מ תרל\"ח ע' קס ובהנסמן שם.\n\n[ftn_8180_ג])<i>שבעתיים כאור זה\"י:</i> ישעי' ל, כו.\n\n[ftn_8181_ד])<i>בד\"ה תורה צוה . . דעת\"י:</i> ראה סה\"מ תרל\"ג ח\"ב ע' תקנו. ראה גם סה\"מ תר\"ם ח\"ב ע' תשפ ובהנסמן שם.\n\n[ftn_8182_ה])<i>שעשועי המלך:</i> ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ.\n\n[ftn_8183_ו])<i>שלא ידע אנוש ערכה:</i> איוב כח, יג.\n\n[ftn_8184_ז])<i>מאד עמקו מחשבותיך:</i> תהלים צב, ו.\n\n[ftn_8185_ח])<i>בד\"ה דוד זמירות קרית:</i> קונטרס אחרון לתניא קס, ב ואילך.\n\n[ftn_8186_ט])<i>שעשועי' יום יום:</i> משלי ח, ל.\n\n[ftn_8187_י])<i>אאלפך חכ':</i> איוב לג, לג [ושם: ואאלפך].\n\n[ftn_8188_יא])<i>שפנימיות אבא פנימיות עת\"י:</i> ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן ובהערה 66."]]],[2001910126,"לאוא\"ס ב\"ה בחי' קוב\"ה כו'. וסדר העבודה בלימוד התורה הוא כמארז\"ל (פסחים דס\"ח) מעקרא כי עביד אינש אדעתי' דנפשי' קעבד<sup data-n=\"724\">57</sup>, פי' אדעתי' דנפשא הוא בכדי לקשר הנפש הוא בחי' הארת הנשמה המלובשת בגוף להקב\"ה שאם<sup data-n=\"725\">58</sup> היות שירדה להחיות הגוף מ\"מ תהא אחוזה וקשורה בו ית', אך אח\"כ צ\"ל עבודת לימוד התורה לשמה היינו לשם התורה<sup data-n=\"726\">59</sup> עצמה. והענין הוא דהנה התורה נתלבשה למטה בדברים גשמיים כמו המחליף פרה בחמור<sup data-n=\"727\">60</sup>, וכן ד' רשויות לשבת<sup data-n=\"728\">61</sup> שא\"א לומר שהתורה כמו שהיא למעלה היא ג\"כ בענינים כאילו, אלא שד' רשויות רה\"ר הוא בחי' עולם התהו, ורה\"י הוא בחי' עולם התיקון<sup data-n=\"729\">62</sup>, וע' בד\"ה לא תחרוש בשור וחמור יחדיו<sup data-n=\"730\">63</sup> מענין ב' בחי' דשור וחמור למעלה, וכשנתלבשה בדיני ההלכות ירדה ונתלבשה בדברים גשמיים, וצריכים לחבר בחי' התורה כמו שהיא למטה לבחי' התורה כמו שהיא למעלה כו'.\nג) <b>ועוי\"ל</b> לשמה לשם התורה כמו שהיא למעלה, והיינו להמשיך בחי' המשכת אוא\"ס בתורה שלמעלה ע\"ד מ\"ש בס' הבהיר דוד הי' מחבר תורה",[["724","57","<b>פסחים דס\"ח . . דנפשי' קעבד</b>: ע\"ב. ראה גם (בנוסף להערה 1) מאמרי אדה\"א שמות ח\"ב ע' שסז. וש\"נ. תו\"ח בשלח ח\"א רלז, א."],["725","58","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["726","59","<b>לשמה היינו לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. (בנוסף להערה 1) מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. שה\"א סט, ב ובהערה 26. סה\"מ תרכ\"ז ס\"ע רסח ואילך. וש\"נ. תרל\"ג ח\"ב בשולי היריעה ע' שעד ואילך. לקמן מאמר ד\"ה ובירך את לחמך פ\"ו."],["727","60","<b>המחליף פרה בחמור</b>: משנה ב\"מ ק, רע\"א. ראה גם (בנוסף להערה 1) סה\"מ תרל\"ה ח\"ב ע' תנב הערה 69. המשך וככה תרל\"ז פ\"ו. פ\"ז. סה\"מ תרל\"ח ע' קסא ואילך."],["728","61","<b>ד' רשויות לשבת</b>: שבת ו, א."],["729","62","<b>רה\"ר . . התהו ורה\"י . . התיקון</b>: כ\"ה בע\"ח שער שבה\"כ פ\"ב. ובלקוטי הש\"ס מהאריז\"ל (לשבת ו, א) מבואר דרה\"י עולם האצי' שהוא עיקר התיקון, ורה\"ר בריאה דז' מל' דתהו נפלו במקום עולם הבריאה כידוע, וכרמלית יצי', ומקום פטור עשי' — סה\"מ תרנ\"ה כאן ע' פג."],["730","63","<b>בד\"ה לא תחרוש בשור וחמור יחדיו</b>: בסה\"מ תרס\"ה כאן ע' קכג: בס' רל\"ב — לפנינו בהספרי' נמצאים הביכלאך מס' 1076. 1106. ובוך הנחות מס' 1074. ושם לא נרשם דרוש בפתיחא זו. ראה גם מאמר ד\"ה זה בסה\"מ תרכ\"ז ע' שצח ואילך. וש\"נ."]]],[2001910127,"שלמעלה בהקב\"ה<sup data-n=\"731\">64</sup>, דהנה אורייתא מחכמה נפקת<sup data-n=\"732\">65</sup>, ובאמת לגבי אוא\"ס אפי' ח\"ע ג\"כ אין ערוך לך כלל, וכמ\"ש כולם בחכ' עשית<sup data-n=\"733\">66</sup> שהחכ' נחשב לפניו כעשייה הגשמי'<sup data-n=\"734\">67</sup>, שכשם שהעשי' אין ערוך לך כך החכ' ג\"כ אין ערוך לך כלל, וזהו שהתורה נק' לבוש כנ\"ל<sup data-n=\"735\">68</sup> בענין אור ושלמה שבתורה, וכמ\"ש במ\"א שהתו' נק' משל הקדמוני<sup data-n=\"736\">69</sup>, שענין משל הוא לבוש כו', והנה בלבוש יש הפרש בין כשהמלך לבוש בלבוש זה, או כשאינו לבוש בו, שהגם שבזמן שאינו לבוש בו הוא ג\"כ לבוש המלך כמ\"ש יביאו לבוש מל'<sup data-n=\"737\">70</sup> אשר לבש בו המלך, הגם שעכשיו אינו מלובש בו מ\"מ נק' לבוש מל', אך כשמלובש בו כעת בלבוש הוא נראה ונגלה לעין כל שהוא לבוש המלך כו', ועד\"ז יובן בענין התורה שנק' לבושו של הקב\"ה הנה עבודת נש\"י להמשיך שיתלבש אוא\"ס ב\"ה בלבושי התורה שז\"ע לחבר תושמ\"ע בהקב\"ה שיתלבש בלבוש תושמ\"ע כו'. והגם שארז\"ל שלש שעות ראשונות יושב ועוסק בתורה<sup data-n=\"738\">71</sup>, י\"ל שזהו בחי' אור שבתורה, וגם אפי' אם נאמר שזהו ג\"כ מבחי' לבוש שהוא בחי' שלמה, הנה ע\"י והגית בה יומם ולילה<sup data-n=\"739\">72</sup> לשמה ממשיכים שיתלבש אוא\"ס ב\"ה בלבושי התורה כל היום וכל הלילה ולא רק ג\"ש ראשונות לבד. והכח שיש לנש\"י להמשיך בחי' אוא\"ס שיתלבש בלבושי התורה, זהו מפני שהתורה נק' ראשית כמ\"ש בראשית בשביל התורה שנק' ראשית, וכתיב ה' קנני ראשית דרכו<sup data-n=\"740\">73</sup> שמזה למדו שהתורה קדמה לעולם, ונודע כי ראשית לשון נוק' שהיא בחי' מקבל, אבל ישראל הוא לי ראש<sup data-n=\"742\">*75</sup> לשון דכר<sup data-n=\"741\">74</sup>, והיינו שממשיכים בבחי' ראשית שהיא התורה מבחי' אשר שהוא בחי' תענוג<sup data-n=\"743\">75</sup> עליון, וז\"ע לשמה לשם התורה להמשיך אוא\"ס ב\"ה בתורה. אך איך יוכל האדם גשמי שמלובש בגוף גשמי וניזון מאו\"ש הגשמיים לבא לידי מעלה ומדריגה גבוה כזו, לזה צריך תחילה להעלות נפשו המלובשת בגוף,",[["731","64","<b>בס' הבהיר דוד . . בהקב\"ה</b>: ראה ס' הבהיר סקצ\"ו ובאור בהיר לשם. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ה: ברע\"מ פ' פנחס דף רך\"ב ע\"ב. לקו\"ת שלח נא, א. סה\"מ תר\"ם ח\"א ע' פד. וש\"נ."],["732","65","<b>אורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["733","66","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["734","67","<b>שהחכ' . . כעשייה הגשמי'</b>: ראה שער היחוד והאמונה פ\"ט. הנסמן במאמרי אדה\"א קונטרסים ע' רנב. סה\"מ תרל\"ח ע' קג הערה 223. סה\"מ תר\"ם ח\"א ע' תלג. וש\"נ. לקמן מאמר ד\"ה וירא ישראל את היד הגדולה על יד הערה 67. ד\"ה הים ראה וינוס על יד הערה 60."],["735","68","<b>כנ\"ל</b>: פ\"ב."],["736","69","<b>שהתו' נק' משל הקדמוני</b>: שמו\"א כד, כג וברש\"י שם. ראה תו\"א מג\"א צח, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרל\"ח ע' רפז."],["737","70","<b>יביאו לבוש מל'</b>: אסתר ו, ח."],["738","71","<b>שלש שעות . . ועוסק בתורה</b>: ראה ע\"ז ג, ב. ראה גם סה\"מ תרס\"ה כאן ע' קכג ואילך."],["739","72","<b>והגית בה יומם ולילה</b>: יהושע א, ח [ושם: בו — וכ\"ה בכ\"מ ומהם: תו\"ח מקץ רכז, א ובהערה 18. סה\"מ תרל\"ח ע' שלה. וש\"נ. סה\"מ תר\"ם ח\"א ע' שצו]. ראה הל' ת\"ת לאדה\"ז פ\"ג, ה\"ה ואילך."],["740","73","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["742","*75","<b>ישראל הוא לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["741","74","<b>ראשית לשון נוק' . . ראש לשון דכר</b>: ראה תו\"א יתרו ע, א. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"ג. וש\"נ."],["743","75","<b>אשר . . תענוג</b>: ראה תו\"א תולדות יח, סע\"ב. ויצא כג, ג. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."]]],[2001910128,"וכמו שאמר רב ששת (בפ\"ח דפסחים דס\"ח) חדאי נפשאי<sup data-n=\"744\">76</sup> לך קראי לך תנאי, וכאמרם שם שמעקרא כי עביד אינש אדעתי' דנפשא קעבד היינו בכדי להעלות נפשו לשרשה ומקורה בחי' לובן העליון שזהו ע\"י התורה שע\"י שישראל מתקשראין באורייתא עי\"ז מתקשראין בקוב\"ה וכנ\"ל<sup data-n=\"745\">77</sup>, ולאחר שכבר נקשר נפשו ונתעלה בשרשה העליון שקדמה לכל דבר כנ\"ל אז יכולים להמשיך אוא\"ס בתורה, וזהו דכתי' כ\"א בתורת ה' חפצו ובתורתו יהגה<sup data-n=\"746\">78</sup> כו', שא' ב' בחי' בתורה תורת ה', ותורתו, והיינו שמתחילה נק' תורת ה' שהתורה גבוה יותר מישראל, וע\"י התורה מתקשראין בקוב\"ה, ואח\"כ כשלומד לשמה אזי נק' בתורתו להיותו משפיע המשכת אוא\"ס בתורה, וכמו שנק' תורת משה כמ\"ש זכרו תורת משה עבדי<sup data-n=\"747\">79</sup> שזהו מפני שמשה המשיך בחי' אוא\"ס בתורה, וכן כשלומד לשמה לשם התו' ממשיך ג\"כ המשכת אוא\"ס בתורה לכן נק' על שמו שז\"ע בתורתו כו', ונמצא מבואר ששניהם אמת שישראל מתקשראין באורייתא שהתו' היא למעלה מישראל, ומ\"מ ג\"ז אמת שכנס\"י נק' חתן ומשפיעים בתורה שנק' כלה מאורסה כו'.\nד) <b>והנה</b> כמו שהוא בתורה כ\"ה במעהמ\"צ ג\"כ, דהנה בברכת המצות אנו מברכין אשר קדשנו במצותיו<sup data-n=\"748\">80</sup> שמזה משמע שהמצות הם למעלה מהאדם העושה אותם, והיינו מפני כי רמ\"ח פקודין הם רמ\"ח אברים דמלכא<sup data-n=\"749\">81</sup> בחי' המלך הקדש<sup data-n=\"750\">82</sup>, ופעם ארז\"ל בזהר ח\"ג פ' בחקתי דקי\"ג ע\"א ע\"פ ועשיתם אותם<sup data-n=\"751\">83</sup>, אתם כתיב, מעלה אני עליכם כאילו עשאוני כבי', שנש\"י ממשיכים בחי' ציור אדם שהרי באמת כי לא אדם הוא<sup data-n=\"752\">84</sup> כו', ונמצא גדלה מעלת נש\"י על המצות, וע' במד\"ר פ' בחקתי פל\"ה<sup data-n=\"753\">85</sup>, ובתנחומא סדר תבא<sup data-n=\"754\">86</sup>. אך באמת שניהם אמת הם, דהנה בשבת אנו מבקשים בנוסח התפלה קדשנו במצותיך<sup data-n=\"755\">87</sup>, ולכאור' אינו מובן הלא אנו מברכין אשר קדשנו במצותיו ומהו הבקשה קדשינו במצותיך, אלא שיש במצות ב' בחי' הא' הם בחי' מצות הוי', והב' הוא בחי' מצותיך<sup data-n=\"756\">88</sup> ממש כבי' מה שהוא עצמו מקיים המצות כמארז\"ל הקב\"ה",[["744","76","<b>שאמר רב ששת (בפ\"ח דפסחים דס\"ח) חדאי נפשאי</b>: [במאמרי אדה\"ז הקצרים ע' תקע: בר\"א] ראה שם ע\"ב. בסמוך הערה 78."],["745","77","<b>וכנ\"ל</b>: ספ\"א."],["746","78","<b>כ\"א בתורת ה' חפצו ובתורתו יהגה</b>: תהלים א, ב. ע\"ז יט, א. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שסז. וש\"נ. סה\"מ תרכ\"ט כאן ע' קמז. וש\"נ."],["747","79","<b>זכרו תורת משה עבדי</b>: מלאכי ג, כב."],["748","80","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["749","81","<b>רמ\"ח פקודין הם רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["750","82","<b>המלך הקדש</b>: לשון הגמ' ברכות יב, ב. ראה זהר בשלח נה, א ובמק\"מ שם. לקמן מאמר ד\"ה ובירך את לחמך ובהערה 16."],["751","83","<b>ועשיתם אותם</b>: בחוקותי כו, ג."],["752","84","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["753","85","<b>במד\"ר פ' בחקתי פל\"ה</b>: סימן ז."],["754","86","<b>ובתנחומא סדר תבא</b>: סוף ס\"א."],["755","87","<b>קדשנו במצותיך</b>: תפלת העמידה לשבת ויו\"ט. ראה גם (בנוסף להערה 1) לקו\"ת ר\"פ בשלח. במדבר ט, ג. מאמרי אדה\"א שמות ח\"א ע' רה. אוה\"ת עקב ע' תריב. פלח הרמון אמור ע' שנד."],["756","88","<b>במצות ב' בחי' . . מצות הוי' . . מצותיך</b>: ראה גם (בנוסף להערה 1) לקו\"ת במדבר ט, ג. סידור שער הציצית ד, ד. ה, ג. סה\"מ תרל\"ח ע' שלב. וש\"נ."]]],[2001910129,"מניח תפילין<sup data-n=\"757\">89</sup> הקב\"ה מצלי<sup data-n=\"758\">90</sup> כו', וכמ\"ש ברבות משפטים<sup data-n=\"759\">91</sup> ע\"פ מגיד דבריו ליעקב<sup data-n=\"760\">92</sup> כו' מה שהוא עושה אומר לישראל לעשות, פי' מצות הוי' הוא בחי' רמ\"ח פקודין רמ\"ח אברים דמלכא שהוא בחי' ט\"ס דז\"א כנודע שז\"א הוא בעל ט\"ס<sup data-n=\"761\">93</sup>, וטפ\"ט הם פ\"א, ורת\"ס הם רמ\"ג וה\"ח<sup data-n=\"762\">94</sup> המגדילים הם רמ\"ח שז\"ע רמ\"ח מ\"ע שנק' בשם אברים היינו בחי' כלים דט\"ס דז\"א, אבל יש בחי' מצותיו היינו מה שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך עמודי אור<sup data-n=\"763\">95</sup> בחי' כתר, ונת\"ל<sup data-n=\"764\">96</sup> שנש\"י כמו שהם למטה בגוף התו' גבוה מהם, וכן המצות ג\"כ גבוהים מהם ולכן מברכין אשר קדשנו במצותיו דהמלך הקדש כו' בחי' רמ\"ח פקודין שע\"י המצות מתעלים נש\"י לשרשן, ואחר שמתעלים אז נש\"י הם למעלה מהמצות כי נש\"י ממשיכים בבחי' מצות הוי' ט\"ס דז\"א מבחי' אוא\"ס ב\"ה ממש היינו בחי' תר\"ך ע\"א כו' וזהו כאילו עשאוני כבי', שי\"ל הפי' שממשיכים מבחי' כי לא אדם הוא בבחי' כמראה אדם<sup data-n=\"765\">97</sup> כו'.\n<b>ובזה</b> יובן מ\"ש וזכרתם את כל מצות הוי'<sup data-n=\"766\">98</sup>, שמצות הוי' נק' זכרי'<sup data-n=\"767\">99</sup> משפיעים לנש\"י, ואח\"כ כתי' למען תזכרו<sup data-n=\"768\">100</sup> ועשיתם את כל מצותי, והיינו שמתחלה המצות הם בחי' דכר ונק' מצות הוי' להגביה הנשמה המלובש בגוף, וכשמתעלים לשרשן אז למען תזכרו כו' מצותי, שנש\"י הם בחי' דכר<sup data-n=\"769\">101</sup> שממשיכים ומשפיעים מבחי' מצותי ממש תר\"ך ע\"א לבחי' מצות הוי' ט\"ס דז\"א כו', ונמצא כי התומ\"צ הם ע\"ד והחיות נושאות, שארז\"ל נושאות ומנושאות<sup data-n=\"770\">102</sup>, או מארז\"ל בארון נושאיו\n\n<i>נרשם בשולי היריעה ולא נסמן מקומו בפנים:</i>\nיש להעיר מענין שהמצות נק' אברים שהאבר ממשיך החיות[ftnref_8189_יב], וזהו תר\"ך ע\"א.",[["757","89","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 126."],["758","90","<b>הקב\"ה מצלי</b>: ברכות ז, א: מכאן שהקב\"ה מתפלל. מאי מצלי. ראה גם אוה\"ת בלק ס\"ע תתקכ. ע' תתקנד. סה\"מ תרכ\"ז ע' שנז. ע' תעז."],["759","91","<b>ברבות משפטים</b>: ראה שמו\"ר פ\"ל, ט."],["760","92","<b>מגיד דבריו ליעקב</b>: תהלים קמז, יט."],["761","93","<b>שז\"א הוא בעל ט\"ס</b>: בלקו\"ת שה\"ש יח, א מציין: ”כמ\"ש במ\"א בד\"ה אלפי שנאן בפ' יתרו [תו\"א יתרו עב, א] ועיין בזהר נח דס\"ה א' ובע\"ח שער א\"א פ\"ב\"."],["762","94","<b>ט\"ס . . וה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. תו\"א מקץ לז, סע\"ד ואילך. שע\"ת מב, ב ובהערה 13."],["763","95","<b>שתרי\"ג . . וז' . . תר\"ך עמודי אור</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' ובהערות 131-135."],["764","96","<b>ונת\"ל</b>: פ\"ב."],["765","97","<b>כמראה אדם</b>: יחזקאל א, כו."],["766","98","<b>וזכרתם את כל מצות הוי'</b>: שלח טו, לט."],["767","99","<b>וזכרתם . . זכרי'</b>: ראה גם שמו\"א א, יא וזכרתני ובמדרש שמואל (פ\"ב שם) וזכרתני בזכרים."],["768","100","<b>למען תזכרו</b>: שלח שם, מ."],["769","101","<b>למען תזכרו . . שנש\"י . . דכר</b>: ראה גם (בנוסף להערה 1) לקו\"ת שלח מה, ב. מז, ג."],["770","102","<b>והחיות . . נושאות ומנושאות</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג. מאמרי אדה\"ז תקס\"ד ע' כג. שה\"א ע, א. תו\"ח פקודי ח\"ב תנט, א. וש\"נ.\n\n[ftn_8189_יב]) שהאבר ממשיך החיות: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר הא' על יד הערה 45. סה\"מ תרל\"א ח\"א ע' רלח. וש\"נ. תרל\"ח ע' מט. וש\"נ."]]],[2001910130,"נשא<sup data-n=\"771\">103</sup>, שמתחלה הם נושאים, ואח\"כ מנושאים, כך התומ\"צ תחלה הם נושאים לשרשן ואח\"כ הם מנושאים שנש\"י ממשיכים בתומ\"צ תוס' וריבוי אור כו'.\nה) <b>ועפ\"ז</b> יובן ענין קרי\"ס ג\"כ שפעם משמע שנש\"י נתעלו על הים, ופעם משמע שהים נתבטל לפניהם ושניהם אמת, דהנה ים ויבשה הוא בחי' עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"772\">104</sup>, וכל מה שיש ביבשה<sup data-n=\"773\">105</sup> יש בים ג\"כ חוץ כו', רק שההפרש שביניהם שהברואים שבים מובלעים הם במי הים, וא\"א להם כלל להיות נפרדים מן הים, אבל הברואים שביבשה הגם שהם ג\"כ מקבלים חיות מן היבשה עכ\"ז הם נפרדים מן היבשה, ועד\"ז יובן למעלה בענין עלמא דאתכסי' ועלמא דאתגלי' ששרש ההפרש ביניהם הוא כמו ההפרש שבין ברואים שבים לברואים שביבשה כו'. והנה נש\"י כמו שנמשכו למטה הם נק' בשם ארץ כמ\"ש כי תהיו אתם ארץ חפץ<sup data-n=\"774\">106</sup>, והארץ לעולם עומדת<sup data-n=\"775\">107</sup>, עמד וימודד ארץ<sup data-n=\"776\">108</sup>, ויש פי' שקאי על נש\"י שמדד שיקבלו את התורה, והיינו לפי שכמו שירדו למטה להתלבש בגוף הם בבחי' יש ודבר נפרד לכן נק' ארץ, וכנ\"ל שהברואים שביבשה הם נפרדים.\n<b>וענין</b> קרי\"ס הוא מה שהים בחי' עלמא דאתכסיא נעשה יבשה בחי' עלמא דאתגליא, ולכן בני ישראל שהלכו ביבשה בתוך הים<sup data-n=\"777\">109</sup> שנתגלה להם בחי' עלמא דאתכסיא נתעלו ע\"י זה עד שזכו לנבואה ואמרו זה אלי כו' כ\"א מראה באצבע כו' מחמת הגילוי הנ\"ל, כי ענין נבואה הוא גילוי ההעלם וכשנתגלה העלם דבחי' עדאת\"כ זכו כולם לגילוי נבואה ע\"ד משה נתנבא בזה כו' ולא בבחי' כדמותינו לבד שביד הנביאים אדמה בלבד כו', מפני עוצם הגילוי שהי' ממה שנתגלה בחי' ההעלם דעלמא דאתכסיא בשעת קרי\"ס כו'.\n<b>ואמנם</b> הנה זה שהים גבוה יותר מנש\"י שנק' ארץ, זהו מצד בחי' הנשמה שמלובשת בגוף ונמשכה למטה, אבל שרש הנשמות הם למעלה מהים כי מעלת הים שהוא בחי' עלמא דאתכסיא כנ\"ל עכ\"ז הנה גם הוא מבחי' עלמין כו', אבל נש\"י קדמו לעולם וכנ\"ל<sup data-n=\"778\">110</sup> בענין ז\"ד שקדמו שמחשבתן ש\"י קדמו לכל דבר כו', וגם כי ים ויבשה שניהם נבראו מבחי' דבור, משא\"כ נש\"י עלו במחשבה",[["771","103","<b>בארון נושאיו נשא</b>: ראה סוטה לה, א. מאמרי אדה\"א בראשית ע' שעג. וש\"נ."],["772","104","<b>ים ויבשה . . דאתכסי' . . דאתגלי'</b>: ראה (בנוסף להערה 1) לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי רפ\"ז. ד\"ה הים ראה וינוס על יד הערה 16 ואילך. ד\"ה כי תבואו וכו' ושבתה הארץ פ\"ד. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ. תו\"ח בשלח ח\"א קלח, ג הערה 312. פלח הרמון ויקרא ע' פב. וש\"נ."],["773","105","<b>וכל מה שיש ביבשה</b>: חולין קכז, א. ראה גם תו\"ח שמות ח\"א יח, ג הערה 770."],["774","106","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["775","107","<b>והארץ לעולם עומדת</b>: קהלת א, ד."],["776","108","<b>עמד וימודד ארץ</b>: חבקוק ג, ו. ראה יל\"ש שם (רמז תקסג). שמיני יא, ב (רמז תקלה). ילקוט המכירי חבקוק שם. ויק\"ר פי\"ג, ב [ושם: דור המדבר — אבל ראה מהדורת מרגליות שם]. סה\"מ תש\"ה ע' 192 [נזכר גם בסה\"מ תרפ\"ט ע' 258]."],["777","109","<b>בני ישראל . . הים</b>: בשלח יד, טו."],["778","110","<b>וכנ\"ל</b>: פ\"א."]]],[2001910131,"שלמעלה מהדבור, ופי' עלו במחשבה זהו בחי' העליונה שבמחשבה כמ\"ש בביאור שני דיונתי שבלקו\"ת פ\"א<sup data-n=\"779\">111</sup>, וכתי' בעבר הנהר<sup data-n=\"780\">112</sup> ישבו אבותיכם ששרש הנשמות הם למעלה אפי' מבחי' נהר ג\"כ, כי ים הוא נק' ים סוף שהוא סופא דכל דרגין<sup data-n=\"781\">113</sup> בחי' מל' מל' כל עולמים<sup data-n=\"782\">114</sup>, אבל נהר הוא בחי' בינה<sup data-n=\"783\">115</sup>, ושרש הנשמות הם למעלה אפי' מבחי' נהר ג\"כ, שהרי הם מבחי' עבר הנהר כו', ולכן מצד שרש נשמתם נתבטל הים לפניהם לפי שבים הי' הגילוי בכל ישראל מבחי' שרש ומקור הנשמה כמו שהיא למעלה בבחי' לבנון הנ\"ל, וזהו משה ובנ\"י, בנ\"י הם בחי' הנשמה כמו שהיא למטה, ומשה הוא הממשיך מבחי' שרש ומקור הנשמה כמ\"ש כי תקנה עבד עברי<sup data-n=\"784\">116</sup>, עבד הוא בחי' הנשמה כמו שהיא למטה שנק' עבד כמ\"ש יעקב עבדי<sup data-n=\"785\">117</sup>, עברי הוא בחי' שרש הנשמה כמו שהיא למעלה בחי' בעבר הנהר ישבו אבותיכם כו', ומשה הוא הממשיך מבחי' שרש הנשמה למטה, וזהו כי תקנה עבד עברי, קנין הוא בחי' המשכה מהעלם אל הגילוי<sup data-n=\"786\">118</sup>, וכי תקנה קאי על משה<sup data-n=\"787\">119</sup>, כי משה הוא בחי' דעת<sup data-n=\"788\">120</sup> ולכן הוא ממשיך מבחי' שרש הנשמה למטה בהנשמה המלובש בגוף כו', והיינו שממשיך בחי' דעת דזרע אדם גם בנשמות דזרע בהמה<sup data-n=\"789\">121</sup>. וזהו דכתי' ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה<sup data-n=\"790\">122</sup> כו' ומקשינן אטו יראה מלתא זוטרתא היא, אין לגבי משה מלתא זוטרתי היא<sup data-n=\"791\">123</sup>, ולכאו' אינו מובן שהרי מעמך כתיב, אלא לפי שבחי' משה יש בכאו\"א<sup data-n=\"792\">124</sup> שהוא בחי' דעת שבכאו\"א, שהרי כאו\"א מברך ברכת חונן הדעת<sup data-n=\"793\">125</sup> כו', וע\"י בחי' הדעת נמשך מבחי' שרש הנשמה למטה בהנשמה שמלובש בגוף. וזה\"ע משה ובנ\"י שרש הנשמה והנשמה המלובש בגוף. ונמצא מתורץ מ\"ש אז ישיר לשון יחיד ולא ישירו, לפי שמשה ובנ\"י הם בחי' אחת כו'.",[["779","111","<b>בביאור שני דיונתי שבלקו\"ת פ\"א</b>: שה\"ש יט, ב."],["780","112","<b>בעבר הנהר</b>: יהושע כד, ב."],["781","113","<b>ים סוף . . דכל דרגין</b>: ראה זהר בשלח נו, א. רע\"מ פינחס רנה, א."],["782","114","<b>מל' כל עולמים</b>: תהלים קמה, יג."],["783","115","<b>נהר הוא בחי' בינה</b>: ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]."],["784","116","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["785","117","<b>יעקב עבדי</b>: ישעי' מד, א. ב [ושם: עבדי יעקב — וכ\"ה שם מה, ד. ירמי' ל, י. מו, כז. כח]."],["786","118","<b>קנין . . המשכה מהעלם אל הגילוי</b>: ראה גם תו\"א משפטים עה, ד. עו, ב. תו\"ח שם רעח, ג. רפד, ב."],["787","119","<b>וכי תקנה קאי על משה</b>: תו\"א ר\"פ משפטים עד, ג. תו\"ח שם רעח, ג. רפד, א."],["788","120","<b>משה . . דעת</b>: ראה תניא פמ\"ב. מאמרי אדה\"א בראשית ע' ר. וש\"נ. תו\"ח וארא ח\"א פה, ד. וש\"נ."],["789","121","<b>דזרע אדם . . דזרע בהמה</b>: ראה תו\"א ר\"פ משפטים. תו\"ח שם ח\"ב רעז, א ואילך. רפ, א. רפא, ג ואילך. לקו\"ת צו ח, ב. סה\"מ תר\"ם ח\"א ע' תכא. וש\"נ. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' על יד הערה 66 ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן קרוב לסופו."],["790","122","<b>ועתה ישראל . . כ\"א ליראה</b>: עקב י, יב."],["791","123","<b>אטו יראה . . מלתא זוטרתי היא</b>: ברכות לג, ב."],["792","124","<b>משה יש בכאו\"א</b>: ראה (בנוסף להערה 1) תניא פמ\"ב. ש\"א מא, ב ובהערה 26. אוה\"ת בשלח כאן ע' תצד. וראה גם בענין משה שבכאו\"א לקו\"ת פקודי ה, סע\"ד תו\"ח בשלח ח\"א קנו, סע\"ד. וש\"נ."],["793","125","<b>ברכת חונן הדעת</b>: בתפלת שמונה עשרה."]]],[2001910132,"<h3>זכור את יום השבת</h3>\n<b>בס\"ד פ' יתרו</b>\n<b>זכור</b> את יום השבת<sup data-n=\"794\">1</sup> לקדשו<sup data-n=\"795\">2</sup>, ששת ימים תעבוד ועשית<sup data-n=\"796\">3</sup> כו', שמנושא הענין משמע שהעבודה בששת ימי החול הוא ציווי ובאמת איננו ציווי כלל<sup data-n=\"797\">4</sup>, ובכדי להבין זה צ\"ל מארז\"ל במד\"ר בראשית פי\"א<sup data-n=\"798\">5</sup> תני רשב\"י אמרה שבת לפני הקב\"ה רבש\"ע, לכולן יש בן זוג ולי אין בן זוג, א\"ל הקב\"ה כנס\"י היא בן זוגך, וכיון שעמדו ישראל לפני הר סיני, א\"ל הקב\"ה זכרו הדבר שאמרתי לשבת כנס\"י היא בן זוגך, היינו דבור זכור את יוה\"ש לקדשו, מזה משמע שנש\"י משפיעים בשבת, וכן כתי' ושמרו כו' לעשות את השבת<sup data-n=\"799\">6</sup> שישראל עושים את השבת, ולכאורה אינו מובן שהרי שבת מקדשא וקיימא<sup data-n=\"800\">7</sup>, ואינו כמו יו\"ט שתלוי בישראל דאינהו דקדשינהו לזמנים<sup data-n=\"801\">8</sup> ולכן מברכים מקדש ישראל והזמנים<sup data-n=\"802\">9</sup>, ישראל תחלה ואח\"כ זמנים, וכמארז\"ל במשנה ט' פ\"ב דר\"ה ע\"פ אשר תקראו אתם<sup data-n=\"803\">10</sup> בין בזמנם בין שלא בזמנם אין לי מועדות אלא אלו, ובגמ' על משנה זו דך\"ה ע\"א ג\"פ כתי' אותם<sup data-n=\"805\">12</sup> חסר<sup data-n=\"804\">11</sup>, אתם אפי' שוגגים כו' אתם אפי' מוטעים<sup data-n=\"806\">13</sup>, שתלוי קביעות המועדים בישראל, וכמארז\"ל במד\"ר בא פט\"ו<sup data-n=\"807\">14</sup> ע\"פ החדש הזה לכם<sup data-n=\"808\">15</sup>, שא' הקב\"ה למאה\"ש אני ואתם נסכים<sup data-n=\"809\">16</sup> על מה",[["794","1","<b>זכור את יום השבת</b>: מאמר זה וכן המאמר שנדפס לפנ\"ז מאמר ד\"ה אז ישיר משה מיוסדים על מאמר ד\"ה אז ישיר משה בסה\"מ תרכ\"ט ע' קמד. וש\"נ.\nהמאמר נמצא בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש וגם בכת\"י הר\"ש סופר (שבהעתקתו לא העתיק את שולי הגליון שנדפסו כאן להלן. אבל כן הועתקו בבוך תרמ\"א 2086 — כת\"י מעתיק — פרט לד\"ה: כ\"א עמלק שעל יד הערה יב).\nהכותרת שבריש המאמר שנכתבה בגוכתי\"ק היא: בס\"ד. ובבוך 2086 הכותרת היא פ' יתרו.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו.\nלקמן בריש וסוף פ\"ב. רפ\"ג. רפ\"ו. מזכיר את המאמר שנדפס לפנ\"ז ד\"ה אז ישיר. לקמן מאמר ד\"ה ועבדתם את הוי' אלקיכם פ\"א מציין למאמר זה."],["795","2","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח."],["796","3","<b>ששת ימים תעבוד ועשית</b>: יתרו שם, ט. ואתחנן ה, יג. ראה גם לקמן פ\"ו."],["797","4","<b>שהעבודה . . ציווי . . איננו ציווי כלל</b>: ראה גם לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ובהערות 10-11."],["798","5","<b>במד\"ר בראשית פי\"א</b>: ס\"ח.\nמובא בכ\"מ ומהם: לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"ג. אוה\"ת בראשית כרך ג ע' 1014. בא ע' רצ [ושם נדפס: פמ\"א. וכשצ\"ל כבפנים]. יתרו ע' תתקכב ואילך. (שם כרך ז) ע' ב'תשיג ואילך. סה\"מ תרכ\"ז ע' קלא. תרכ\"ט ע' קנ. תר\"ל ע' רמד [במהדורת תשמ\"ג. ובמהדורת תשל\"ג ע' רמו] וס\"ע רנב [ושם: ס\"פ יו\"ד]. תרל\"א ח\"א ע' ו. וככה תרל\"ז ע' צח. עטר\"ת ע' מב. פר\"ת ע' רסב. ס' השיחות תשנ\"ב ריש ע' 421."],["799","6","<b>ושמרו . . את השבת</b>: תשא לא, טז."],["800","7","<b>ולכאורה . . שבת מקדשא וקיימא</b>: ביצה יז, א. ראה גם סה\"מ תרל\"א ח\"א ע' קנח. וש\"נ. לקמן פ\"ו. מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"ג. ד\"ה ושאבתם מים בששון פ\"א ואילך."],["801","8","<b>דאינהו דקדשינהו לזמנים</b>: ראה ברכות מט, א."],["802","9","<b>מקדש ישראל והזמנים</b>: נוסח ברכת היום דיו\"ט."],["803","10","<b>אשר תקראו אתם</b>: אמור כג, ד."],["805","12","<b>אותם חסר</b>: ראה רש\"י ר\"ה שם ד\"ה אתם."],["804","11","<b>ג\"פ כתי' אותם חסר</b>: אמור כג, ב. ד. לז."],["806","13","<b>אתם אפי' מוטעים</b>: ראה גם אוה\"ת במדבר ע' פח."],["807","14","<b>במד\"ר בא פט\"ו</b>: סימן ב."],["808","15","<b>החדש הזה לכם</b>: בא יב, ב."],["809","16","<b>נסכים</b>: בשמו\"ר כאן (במהדורת אמשטרדם ת\"א. ועוד): מסכים. אבל במהדורות אחרות כבפנים, וכ\"ה גי' ילקוט המכירי (תהלים קג, ח) בשמו\"ר כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 18. המשך תרס\"ו ס\"ע שיז."]]],[2001910133,"שישראל גומרים ומעברים את השנה שנא' (תילי' סי'<sup data-n=\"810\">17</sup> נ\"ז ג') אקרא לאלקים עליון לאל גומר עלי כו', א\"ל הקב\"ה לישראל לשעבר הי' בידי שנאמר עשה ירח למועדים (תילי' סי' ק\"ד י\"ט) אבל מכאן ואילך הרי מסורה בידכם אם<sup data-n=\"811\">18</sup> אמרתם הן הן כו' לאו לאו כו' לכך כתי' החודש הזה לכם, אבל שבת מקדשא וקיימא משי\"ב, וכמארז\"ל אטו שבת ישראל מקדשי ליה<sup data-n=\"812\">19</sup>, ולכן מברכין מקדש השבת<sup data-n=\"813\">20</sup> לבד ואין מזכירים שם ישראל מפני שמקדשי וקיימי משי\"ב, ולכן פי' רבינו ז\"ל ששבת גבוה מישראל<sup data-n=\"814\">21</sup>, ולכאורה אינו מובן הלא מהמד\"ר הנ\"ל שכנס\"י היא בן זוגך משמע שכנס\"י משפיעים בשבת שנמצא מעלת ישראל גדלה כו', ויובן בהקדם ענין מארז\"ל קשה לזווגם<sup data-n=\"815\">22</sup> כקריעת ים סוף דלכאורה אינו מובן מה שייך קרי\"ס לענין זיווגים עד שאומר שקשה ענין בחי' הזיווג כמו קרי\"ס שמזה מובן שענין הילוך בנ\"י בים סוף זהו ג\"כ בחי' זיווג כו' וצ\"ל זה.\nב) <b>ולהבין</b> זה צריך להקדים מארז\"ל הובא בילקוט בשלח רמז רמ\"א<sup data-n=\"816\">23</sup>, כל פרגמטיא<sup data-n=\"817\">24</sup> של משה לא היתה אלא באז כו' קינטורו באז, ומאז באתי\n\n<i>נרשם בשולי היריעה ולא נסמן מקומו בפנים:</i>\nהשביתה דשבת זהו גבוה מישראל נשמה שבגוף כמו כל רמ\"ח פקודין[ftnref_8190_א], וכשבא לשרש הנשמה אז זכור שמשפיע בשבת.\nנרשם בריש הדף (בהיפך) מלמטלמ\"ע ולא צויין מקומו בפנים<sup data-n=\"8191\">*</sup>:\nפרגמטיא של משה באז קינטר ובאז תיקן, באז קינטר ומאז באתי כו' בשמך הרע לעם, כי פרעה עורף דא\"א[ftnref_8192_ב] ואינו מניח לקשר שרש הנשמה שמא\"א בעבר הנהר, וא' לא ידעתי את הוי'[ftnref_8193_ג] כ\"א שמקבל מבחי' רם[ftnref_8194_ד] שכחשוכה כאורה[ftnref_8195_ה], וע\"י קי\"ס שידעו גם מצרים מש' הוי'[ftnref_8196_ו] שז\"ע אם תגבי' כו' אורידך נאום הוי'[ftnref_8197_ז], לכן תיקן באז ישיר שחיבר שרש הנשמה שהיא אז בבנ\"י שהוא הנשמה שבגוף, ע\"י בחי' הדעת שז\"ע כי תקנה עבד עברי[ftnref_8198_ח] שיומשך בו עברי מעבר הנהר כו' זהו באז תיקן.",[["810","17","<b>סי'</b>: כשמציינים לתנ\"ך לפעמים משתמשים בתיבת ”סימן\" [ראה גם בסמוך בפנים. תו\"א וירא יד, ד. מקץ לג, סע\"ג. מג\"א צז, ב. ויקהל קיד, ג. קיז, א. קיח א (ב\"פ). קיח ב (ב\"פ). מג\"א קכב, א (ג\"פ). קכג, סע\"ד. לקו\"ת בשלח א, ב (ב\"פ). פקודי ג, א ב\"פ). ועוד]. ולפעמים בתיבת ”קפיטל\" — ראה סה\"מ תר\"ם ח\"א ע' קמח. וש\"נ."],["811","18","<b>בידכם אם</b>: בשמו\"ר כאן: בידכם ברשותכם אם."],["812","19","<b>אטו שבת ישראל מקדשי ליה</b>: ביצה יז, א."],["813","20","<b>מקדש השבת</b>: נוסח ברכת היום דשבת."],["814","21","<b>פי' רבינו ז\"ל ששבת גבוה מישראל</b>: במאמר ד\"ה זכור תקס\"ט — תו\"א יתרו סט, ג ואילך. מאמרי אדה\"ז תקס\"ט ע' לב ואילך. תו\"ח יתרו ח\"ב רסד, א ואילך. לקמן פ\"ו."],["815","22","<b>קשה לזווגם</b>: סוטה ב, א. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רלב. ס\"ע רלד ואילך. מארז\"ל ע' צ. שער האמונה נד, ב ואילך. מאמרי אדה\"א ויקרא ח\"א ע' ערב."],["816","23","<b>בילקוט בשלח רמז רמ\"א</b>: בשלח טו, א. ושם לפנ\"ז בפ' שמות (ד, כו) רמז קעד [הובא באוה\"ת בשלח ע' תקה]. ובמהדורת ירושלים תשל\"ז רמז קעא."],["817","24","<b>פרגמטיא</b>: בילקוט: פרקמטיא. ראה ערוך מערכת פרגמטיא: עובר לסוחר (ח\"ש כג, טז) תרגום ירושלמי פרגמטיא, נפקת ספר אחר פרקמטיא. ושם מערכת פרקמטיא . . זהו פרגמטיא.\n\n[ftn_8190_א])<i>רמ\"ח פקודין:</i> נסמן לקמן פ\"ו קרוב לסופו."],["8191","*","ראה לקמן ריש ס\"ד.\n\n[ftn_8192_ב])<i>פרעה עורף דא\"א:</i> ראה לקמן פ\"ד הערה 84.\n\n[ftn_8193_ג])<i>לא ידעתי את הוי':</i> שמות ה, ב.\n\n[ftn_8194_ד])<i>רם:</i> תהלים קיג, ד. ראה לקמן בפנים פ\"ה.\n\n[ftn_8195_ה])<i>שכחשוכה כאורה:</i> ראה לקמן פ\"ה הערה 131.\n\n[ftn_8196_ו])<i>שידעו גם מצרים מש' הוי':</i> ראה לקמן הערה יא.\n\n[ftn_8197_ז])<i>אם תגבי' . . הוי':</i> עובדי' א, ד.\n\n[ftn_8198_ח])<i>כי תקנה עבד עברי:</i> משפטים כא, ב. ראה לקמן ספ\"ב ובהנסמן לשם."]]],[2001910134,"אל פרעה<sup data-n=\"818\">25</sup>, שירתו באז אז ישיר משה<sup data-n=\"819\">26</sup> ובנ\"י<sup data-n=\"820\">27</sup>. והענין יובן ע\"פ משנ\"ת בד\"ה אז ישיר<sup data-n=\"821\">28</sup> שמה שנש\"י נתעלו על הים זהו מצד בחי' הארת הנשמה המאירה בגוף להחיותו, שזהו מה שישראל נק' בשם ארץ<sup data-n=\"822\">29</sup> כו', וענין משה ובנ\"י נת' שמשה הוא הממשיך שרש ומקור הנשמה לבחי' הנשמה המלובשת בגוף, ע\"י בחי' הדעת, ויש הארת משה בכל אחד ואחד הוא בחי' הדעת<sup data-n=\"823\">30</sup> שבכאו\"א שעי\"ז מקשר הנשמה שמלובש בגוף לבחי' שרש הנשמה, ובשעת עמדם לפני הים האיר בהם שרש ומקור הנשמה, אשר לכן כשראה הים משה ובנ\"י נתבטל לפניהם ונתבקע, שהים אם<sup data-n=\"825\">32</sup> היותו בחי' עלמא דאתכסי'<sup data-n=\"824\">31</sup> עכ\"ז הוא בחי' עלמין ונברא מבחי' הדבור, אבל שרש הנשמות הם עלו במח'<sup data-n=\"826\">33</sup>, והם למעלה גם מבחי' נהר ג\"כ כמ\"ש בעבר הנהר ישבו<sup data-n=\"827\">34</sup>, גם מחשבתן של ישראל קדמו<sup data-n=\"828\">35</sup> לכל דבר כנ\"ל<sup data-n=\"829\">36</sup>, לכן נתבטל לפניהם כו', ומזה נמשך תוספת בבחי' עלמין אפי' בבחי' ים<sup data-n=\"830\">37</sup> בחי' עלמא דאתכסיא כמובן מהמד\"ר ע\"פ אז ישיר (ר\"פ ך\"ג<sup data-n=\"831\">38</sup>) הה\"ד (תילי' צ\"ג) נכון כסאך מאז<sup data-n=\"832\">39</sup>, א\"ר ברכיה בשם ר' אבהו אע\"פ שמעולם אתה לא נתיישב כסאך ולא נודעת בעולמך עד שאמרו בניך",[["818","25","<b>ומאז באתי אל פרעה</b>: שמות ה, כג."],["819","26","<b>אז ישיר משה</b>: בשלח טו, א."],["820","27","<b>ובנ\"י</b>: בילקוט כאן ליתא. אבל הובא ברמז קעד הנ\"ל [ובמהדורת ירושלים הנ\"ל ליתא]."],["821","28","<b>בד\"ה אז ישיר</b>: נדפס לפני מאמר זה ושם פ\"ה."],["822","29","<b>שישראל נק' בשם ארץ</b>: מלאכי ג, יב."],["823","30","<b>הארת משה בכל אחד ואחד . . הדעת</b>: ראה גם סיום המאמר שלפנ\"ז. וש\"נ."],["825","32","<b>אם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["824","31","<b>שהים . . עלמא דאתכסי'</b>: ראה גם המאמר שלפנ\"ז ובהערה 104."],["826","33","<b>שרש הנשמות הם עלו במח'</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו רפ\"ב ובהנסמן שם."],["827","34","<b>בעבר הנהר ישבו</b>: יהושע כד, ב."],["828","35","<b>מחשבתן של ישראל קדמו</b>: ב\"ר פ\"א, ד."],["829","36","<b>כנ\"ל</b>: מאמר ד\"ה אז ישיר ספ\"א."],["830","37","<b>נמשך תוספת . . אפי' בבחי' ים</b>: ראה גם אוה\"ת בשלח כרך ז ע' ב'תרסה."],["831","38","<b>מהמד\"ר ע\"פ אז ישיר (ר\"פ ך\"ג)</b>: שמו\"ר שם [ולכאו' כצ\"ל בסה\"מ תר\"ל ע' עה]. הובא גם בסה\"מ תרכ\"ט כאן ע' קמד. וש\"נ."],["832","39","<b>(תילי' צ\"ג) נכון כסאך מאז</b>: פסוק ב."]]],[2001910135,"שירה לכך נא' נכון כסאך מאז כו', אמרו ישראל באמת עד שלא בראת עולמך היית אתה, ומשבראת<sup data-n=\"833\">40</sup> אותו אתה הוא אלא כביכול<sup data-n=\"834\">41</sup> עומד שנא' עמד וימודד ארץ (חבקוק ג' וא\"ו) אבל משעמדת בים ואמרנו שירה לפניך באז ישיר<sup data-n=\"835\">42</sup> נתיישבה מלכותך וכסאך נכון הוי נכון כסאך מאז, מאז<sup data-n=\"836\">43</sup> ישיר, נמצא שמשירת הים נתוסף בבחי' עולם ים ויבשה שנברא בשי\"ב. והענין הוא דהנה אז ישיר, ושיר הוא בחי' העלאה מלמטלמ\"ע כענין כל בעלי השיר יוצאים בשיר<sup data-n=\"837\">44</sup> שע\"י בחי' השירה וזמרה יוצאים מהגבלתם להכלל ולהבטל באוא\"ס ב\"ה, וכן יובן בענין ישיר שבשירת הים שהוא בחי' ההעלאה מלמטלמ\"ע ואז הוא בחי' המשכה מלמעלמ\"ט, כי אז הוא בחי' אלף, זיין<sup data-n=\"838\">45</sup>, זיין הוא בחי' ז' מדות כו'<sup data-n=\"839\">46</sup> ואל\"ף רומז לבחי' אלופו של עולם<sup data-n=\"840\">47</sup> שז\"ע המשכה מבחי' אלופו ש\"ע בבחי' ז' מדות, וכשנעשה התחברות בחי' אז עם בחי' ישיר דהיינו משה ובנ\"י, כי אז קאי על שרש ומקור הנשמה<sup data-n=\"841\">48</sup> וכמ\"ש נכון כסאך מאז, ולמדו מזה במד\"ר בראשית פ\"א שכסה\"כ קדמה לעולם<sup data-n=\"842\">49</sup> שנא' נכון כסאך מאז, ונת' שגם נש\"י קדמו לעולם לכן הם נק' בשם אז<sup data-n=\"843\">50</sup> וכמ\"ש כגר כאזרח<sup data-n=\"844\">51</sup>, שפי' אזרח הוא תושב דהיינו שהוא מכבר מאז ומקדם, שנמצא אזרח הוא כמו אז, וכתי' כל האזרח\n\n)\n<i>נרשם בשולי היריעה ולא צויין מקומו בפנים<sup data-n=\"8199\">*</sup>:</i>\nאברהם אל עולם[ftnref_8200_ט], שהודיע שברא העולם, ומ\"מ ושמי הוי' לא נודעתי להם[ftnref_8201_י], אבל ע\"י קרי\"ס וידעו מצרים כי אני הוי'[ftnref_8202_יא].",[["833","40","<b>ומשבראת</b>: כ\"ה גם בסה\"מ תרכ\"ט כאן. בשמו\"ר שם: משבראת."],["834","41","<b>כביכול</b>: ראה ”מ\"מ הגהות והע\"ק\" לתניא פ\"ב (לב, א). ובאג\"ק שלו חכ\"ו ע' רד."],["835","42","<b>ישיר</b>: בסה\"מ תרכ\"ט ובשמו\"ר שם ליתא."],["836","43","<b>מאז</b>: בשמו\"ר שם: באז."],["837","44","<b>כל בעלי השיר יוצאים בשיר</b>: שבת נא, ב (במשנה). ראה גם סה\"מ מלוקט ו' ס\"ע צה ובהערה לשם. באוה\"ת בשלח כאן ע' תצד: כנודע מהמגיד נ\"ע.\nראה גם בשם המגיד — לקו\"ת ברכה צח, א. סידור שער החנוכה ערה, ד [ובשניהם: בלק\"א הגדול]. מאמרי אדה\"ז תקס\"ה ח\"א ע' רל. מארז\"ל ע' קכ. סה\"מ תרנ\"ג ע' ריח. ויש להוסיף תורה זו בהוספות (לספרי הרב המגיד) שבסו\"ס לקו\"א ואו\"ת הוצאת קה\"ת.\nאבל בסה\"מ תקס\"ו ע' ק (ובמהדורת תשס\"ד ע' רד — שהוא מקביל ללקו\"ת וסידור) לא הובא זה בשם המגיד כ\"א: כמ\"ש במ\"א]."],["838","45","<b>אז הוא בחי' אלף זיין</b>: ראה זהר בשלח נד, א. לקו\"ת שמע\"צ פח, ב. לקמן ספ\"ה. מאמר ד\"ה מגילה נקראת על יד הערה 190. סה\"מ תרל\"א ח\"א ס\"ע קנז. וש\"נ."],["839","46","<b>כו'</b>: בסה\"מ תרכ\"ט כאן ע' קנ ליתא."],["840","47","<b>אלופו של עולם</b>: לשון ב\"ר פ\"כ, ב."],["841","48","<b>אז . . הנשמה</b>: ראה גם סה\"מ תרכ\"ט כאן."],["842","49","<b>במד\"ר בראשית פ\"א שכסה\"כ קדמה לעולם</b>: סימן ד."],["843","50","<b>ונת' שגם נש\"י . . אז</b>: ראה גם אוה\"ת בשלח כאן ע' תצד. סה\"מ תרכ\"ט כאן."],["844","51","<b>כגר כאזרח</b>: אמור כד, טז. כב. יהושע ח, לג."],["8199","*","ראה לקמן פ\"ד.\n\n[ftn_8200_ט])אל עולם: וירא כא, לג. סוטה י, סע\"א ואילך.\n\n[ftn_8201_י])ושמי הוי' לא נודעתי להם: ראה לקמן פ\"ד ובהערה 93.\n\n[ftn_8202_יא])וידעו מצרים כי אני הוי: בשלח יד, יח."]]],[2001910136,"בישראל<sup data-n=\"845\">52</sup>, ואפ\"ל שז\"ע בעבר הנהר כו', כי נהר הוא בינה<sup data-n=\"846\">53</sup> ובחי' אזרח הוא מעבר הנהר דהנה נודע שהשבירה הי' בז\"ת דש'<sup data-n=\"848\">55</sup> ס\"ג<sup data-n=\"847\">54</sup>, שז\"ע עולם התהו<sup data-n=\"849\">56</sup>, ובחי' התיקון הוא בחי' ש'<sup data-n=\"852\">59</sup> מ\"ה<sup data-n=\"851\">58</sup>, שב' שמות אלו שניהם בחי'<sup data-n=\"853\">60</sup> מחודשי'<sup data-n=\"850\">57</sup> לצורך הבריאה שהרי בנין וסתירת התהו הי' בונה ע\"מ לסתור<sup data-n=\"855\">62</sup> בכוונה, בכדי שיתוקן ע\"י בחי' התיקון, כמ\"ש מזה במ\"א בהגהות ע\"פ ראה אנכי נותן שבלק\"ת פ' ראה<sup data-n=\"854\">61</sup>, אבל ש' ע\"ב הוא למעלה מתהו ותיקון, וזהו בחי' אזרח<sup data-n=\"857\">64</sup> שפי' שהוא מאז ומקדם, שלמעלה מבחי' עלמין דעולם התהו ועולם התיקון, וזהו בעבר הנהר למעלה מבחי' ש' ס\"ג שהוא בבינה<sup data-n=\"858\">65</sup> כ\"א בבחי' ש' ע\"ב שלמעלה מתהו ותיקון, וזהו נש\"י עלו במחשבה מח' הוא בחי' חכ'<sup data-n=\"859\">66</sup> כמ\"ש בזהר מח' ויובלא<sup data-n=\"860\">*67</sup> כו' ועלו במח' היינו בבחי' היותר עליונה שבחכמה<sup data-n=\"862\">68</sup> שזהו בחי' ש'<sup data-n=\"861\">67</sup> ע\"ב<sup data-n=\"856\">63</sup> בחי' אזרח שזהו ענין מה שהם בשרשן בעבר מבחי' הנהר דבינה כו', אך באמת שרש הנשמה עוד גבוה יותר כי פי' בעבר הנהר היינו בחי' אריך אנפין וכמשי\"ת<sup data-n=\"863\">69</sup>, ולכן כשהאיר בים שרש הנשמה נתבטל",[["845","52","<b>כל האזרח בישראל</b>: אמור כג, מב. ראה אוה\"ת ויחי ח\"ב ס\"ע שצב ואילך. ע' שפז."],["846","53","<b>נהר הוא בינה</b>: ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]."],["848","55","<b>דש' ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["847","54","<b>שהשבירה הי' בז\"ת דש' ס\"ג</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"א. שער התיקון ש\"י, פ\"ב. מבוא שערים ש\"ב ח\"א, פ\"א (ובהגה ג). תו\"א מג\"א צז, ג. לקו\"ת פ' ראה לא, ב. תו\"ח בא ח\"א קיז, רע\"ג. (וארא פה, ג. וש\"נ)."],["849","56","<b>ס\"ג . . התהו</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"א. תו\"ח בראשית ט, א ובהערה 2."],["852","59","<b>ש' מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["851","58","<b>התיקון . . ש' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"א ואילך."],["853","60","<b>ש' מ\"ה . . בחי' מחודשי'</b>: ראה ע\"ח שער שבה\"כ ש\"ט, פ\"ז. סה\"מ תר\"ם ח\"א ע' רמד. וש\"נ. אוה\"ת ויחי ח\"ב ס\"ע שצב ואילך. פ' ראה כרך ה ס\"ע ב'לט."],["850","57","<b>ס\"ג . . ובחי' . . מחודשי'</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תשלז. וש\"נ."],["855","62","<b>בונה ע\"מ לסתור</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. סה\"מ תר\"ם ח\"א ע' רנא. וש\"נ."],["854","61","<b>בנין וסתירת התהו . . בהגהות . . פ' ראה</b>: ראה אוה\"ת פ' ראה ע' תרלו. סה\"מ תרכ\"ו ע' רח ואילך."],["857","64","<b>ש' ע\"ב . . אזרח</b>: ראה רמ\"ז לזהר אמור קג, סע\"א. ראה גם אוה\"ת פ' ראה כרך ה ס\"ע ב'לט. סה\"מ תר\"ם ח\"ב ע' תשלז. וש\"נ.\nמובא בשמו באוה\"ת פ' ראה ע' תרלו [נדפס גם בסה\"מ תרכ\"ו ס\"ע רח ואילך]. ר\"ה ס\"ע א'תמו [נדפס גם בביאוה\"ז לכ\"ק אדמו\"ר הצ\"צ ח\"א ע' תיח-ט]. סה\"מ תרע\"ט ע' תריב.\nבאוה\"ת שם נדפס: שם מ\"ב. וצ\"ל כבסה\"מ תרכ\"ו שם: שם ע\"ב."],["858","65","<b>ש' ס\"ג שהוא בבינה</b>: ראה ע\"ח שער הכללים פ\"ח. הנסמן בסמוך הערה 68."],["859","66","<b>מח' הוא בחי' חכ'</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 79."],["860","*67","<b>מח' ויובלא</b>: ראה זהר ח\"ש קכג, א."],["862","68","<b>שבחכמה . . ש' ע\"ב</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["861","67","<b>ועלו במח' . . ש' ע\"ב</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן שמפרש: היינו בחילוקי פרטי שמות פרטים יש שם ע\"ב דע\"ב."],["856","63","<b>ש' ע\"ב</b>: ראה זהר תרומה קלב, ב. ועוד. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב כ\"ק אדמו\"ר זי\"ע להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["863","69","<b>בעבר הנהר . . וכמשי\"ת</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן שכותב: ובאמת י\"ל פי' בעבר הנהר הוא בחי' א\"א שלמעלה גם מבחי' אזרח. ראה לקו\"ת בחוקותי מז, א."]]],[2001910137,"ונתבקע כמ\"ש בוקע ים לפני משה<sup data-n=\"864\">70</sup> היינו לפני בחי' הארת משה שיש בכאו\"א, שהוא מה שע\"י בחי' הדעת שבכאו\"א מתקשר שרש הנשמה עם הנשמה המלובשת בגוף כמ\"ש בד\"ה אז ישיר<sup data-n=\"865\">71</sup> בענין כי תקנה עבד עברי<sup data-n=\"866\">72</sup>.\nג) <b>וזהו</b> מ\"ש ברבות כמגדל דוד צוארך<sup data-n=\"867\">73</sup> מה שגידל אתכם דוד בספרו כו' לגוזר י\"ס לגזרים<sup data-n=\"868\">74</sup>, שנת' בד\"ה אז ישיר<sup data-n=\"869\">75</sup> שלכאו' בפ' בשלח סיפר גדולות ונוראות יותר מקרי\"ס. אך הענין הוא שדוד הודיע לנו, שזה שנבקע הים ובטל לפניהם זהו מצד שרשם שהם למעלה מהים, כי בתורה בסיפור שלפני קרי\"ס ובשירת הים לא נא' כ\"א ובנ\"י הלכו ביבשה בתוך הים<sup data-n=\"870\">76</sup>, שמזה משמע שע\"י הים נתעלו ישראל שהלכו ביבשה בתוך הים ונתגלה להם העלם דעלמא דאתכסי' כנ\"ל<sup data-n=\"871\">77</sup> שעי\"ז זכו לנבואה שה\"ע גילוי ההעלם, ואמרו זה אלי<sup data-n=\"872\">78</sup> כו', שכ\"ז הוא מעלת הים, רק שמפני שבנ\"י הלכו בים זכו לזה, אבל דוד חילק ענין העברת בנ\"י בים בחרבה, ובקיעת הים לב' דברים ואמר עליהם ב\"פ כי לעולם חסדו, כמ\"ש והעביר ישראל בתוכו כל\"ח<sup data-n=\"873\">79</sup>, ותחלה אמר לגוזר י\"ס לגזרים כל\"ח, והיינו שהודיע שמה שנבקע הים וגזר אותו לגזרים זהו שמצד שרש הנשמה נתבטל הים לפניהם להיותם במעלה ומדריגה גבוה יותר מהים, שהרי הים אם היותו עדאת\"כ, מ\"מ הוא מבחי' עלמין כו' אבל שרש נש\"י הם מבחי' עבר הנהר כנ\"ל<sup data-n=\"874\">80</sup>, וגם קדמו לכ\"ד היינו בהשבעה דברים שקדמו לעולם<sup data-n=\"875\">81</sup>, ואח\"כ אמר והעביר ישראל בתוכו שז\"ע מה שע\"י הים נתעלו בני ישראל היא הנשמה שמלובש בגוף, וזהו שחלקם לב' דברים שלכאורה אינו מובן שהרי הם בחי' אחת שהרי מה שנגזר הים לגזרים זהו בכדי שיעברו ישראל בתוכו, דאילו לא העביר ישראל בתוכו מאי מעליותא במה שנגזר הים לגזרים ולמה חלקם לומר ב\"פ כל\"ח ע\"ז, אך לפי הנ\"ל יובן היטיב שבאמת הוא חסד בפ\"ע, שמה שגזר הים לגזרים גילה לנו ששרש הנשמות הם למעלה מהים עד שהים נתבטל לפניהם לכן א' ע\"ז כל\"ח בפ\"ע שזהו חסד בפ\"ע, ולכן א\"א בנוסח ההגדה אילו קרע לנו את הים<sup data-n=\"876\">82</sup> ולא העבירנו בתוכו בחרבה דיינו, לפי שבזה עצמו הי' די",[["864","70","<b>בוקע ים לפני משה</b>: נוסח ברכת אמת ואמונה (תפלת ערבית)."],["865","71","<b>בד\"ה אז ישיר</b>: קרוב לסיום המאמר שלפנ\"ז."],["866","72","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["867","73","<b>ברבות כמגדל דוד צוארך</b>: שה\"ש ד, ד. שהש\"ר שם."],["868","74","<b>לגוזר י\"ס לגזרים</b>: תהלים קלו, יג."],["869","75","<b>שנת' בד\"ה אז ישיר</b>: נדפס לפנ\"ז. ראה שם פ\"א ופ\"ה."],["870","76","<b>ובנ\"י . . בתוך הים</b>: בשלח יד, כט."],["871","77","<b>כנ\"ל</b>: במאמר ד\"ה אז ישיר פ\"ה ד\"ה וענין."],["872","78","<b>לנבואה . . זה אלי</b>: בשלח טו, ב. ראה רש\"י שם. לעיל שם פ\"א. וש\"נ."],["873","79","<b>והעביר ישראל בתוכו כל\"ח</b>: תהלים קלו, יד. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שסז. אוה\"ת בשלח כאן ע' תצג. סה\"מ תרכ\"ט כאן ע' קנא. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 85."],["874","80","<b>כנ\"ל</b>: פ\"ב."],["875","81","<b>בהשבעה דברים שקדמו לעולם</b>: ראה ב\"ר פ\"א, ד. פי' מהרז\"ו הארוך שם. מאמרי אדה\"א דברים ח\"ב ע' שע בהערה. סה\"מ תרל\"ט ח\"ב ע' תנד. וש\"נ."],["876","82","<b>אילו קרע לנו את הים</b>: ראה גם סה\"מ תרכ\"ט כאן."]]],[2001910138,"לנו במה שהודיע ששרש נש\"י הוא למעלה מבחי' עלמין, ולכן יש להם כח להמשיך תוס' אור בבחי' עלמין אפי' בבחי' ים עלמא דאתכסיא כו'.\nד) <b>ומעתה</b> יובן ענין מה שכל פרגמטיא של משה לא היתה אלא באז קינטר באז, ומאז באתי אל פרעה כו' הרע לעם הזה, פי' פרעה הוא אותיות הערף<sup data-n=\"877\">83</sup>, והיינו שמקבל מעורף בחי' אחוריים דא\"א<sup data-n=\"878\">84</sup> כנודע, ולכן אמר משה שפרעה אינו מניח לקשר בחי' שרש הנשמה עם בחי' הנשמה המלובשת בגוף, וזהו עבדים היינו אנו בנ\"י דלעילא שהוא בחי' ז\"א, לפרעה בחי' ערף דא\"א כמ\"ש בסידור ד\"ה עבדים היינו<sup data-n=\"879\">85</sup>, וזהו ומאז באתי שהקנטור שלו הי' באז הוא בחי' שרש הנשמה כמו שהיא בבחי' לבנון כמ\"ש ונוזלי' מן לבנון<sup data-n=\"880\">86</sup>, והייתה טענתו שע\"י שהרע פרעה לעם הזה, פי' זה היינו שהרגישו בחי' זה שהוא מורה על בחי' גילוי אלקות ופרעה הרע להם ע\"י קושי שעבודם שיפץ העם בכל ארץ מצרים לקשש קש לתבן<sup data-n=\"881\">87</sup>, בכדי ליגעם שלא יתנו לב לעבוד את ה' כאמרו נרפים כו' ע\"כ אתם אומרים נלכה נזבחה להוי'<sup data-n=\"882\">88</sup>, אמנם ע\"י קרי\"ס דכתיב וידעו מצרים כי אני הוי' בהכבדי בפרעה<sup data-n=\"883\">89</sup>, שזהו היפך מה שא' פרעה מי הוי'<sup data-n=\"884\">90</sup>, אמר משה שירה אח\"כ והתחיל באז דוקא, לרמז על שרש הנשמה שנק' אז כנ\"ל<sup data-n=\"885\">91</sup>, ושעי\"ז נמשך תוס' אור בבחי' עלמין כו'. ויובן זה ע\"פ המד\"ר הנ\"ל<sup data-n=\"886\">92</sup> שהעיר לפסוק אז ישיר מפסוק נכון כסאך מאז אע\"פ שמעולם אתה לא נתיישבה כסאך ולא נודעת בעולמך עד שאמרו בניך שירה באז, פי' ולא נודעת בעולמך זהו כמ\"ש על האבות וארא כו' ושמי הוי' לא נודעתי להם<sup data-n=\"887\">93</sup>, שהגם שנזכר כמ\"פ ש' הוי' אצל האבות זהו רק בבחי' ידיעה לבד, אבל לא נודעתי להם בבחי' יעוד וחיבור<sup data-n=\"888\">94</sup>, כי נודעתי הוא אותיות ונועדתי<sup data-n=\"889\">95</sup> כו' כמ\"ש במ\"א, וכל ענין שעבוד ויציאת מצרים הי' בכדי שיתגלה ש' הוי'<sup data-n=\"890\">96</sup> כמ\"ש לכן אמור לבנ\"י אני הוי'<sup data-n=\"891\">97</sup>,",[["877","83","<b>פרעה הוא אותיות הערף</b>: ראה לקו\"ת להאריז\"ל שמות עה\"פ (א, ח) ויקם מלך חדש בתחילתו. שער הפסוקים פ' וישב (לט, א) סט\"ל. סה\"מ תר\"ם ח\"ב ע' תרנה. וש\"נ."],["878","84","<b>פרעה . . דא\"א</b>: ראה פע\"ח שער חג המצות שכ\"א, פ\"ז. מ\"ח מסכת סדר ליל פסח פ\"ז, מ\"א ואילך. סידור סדר הגדה רצד, ג. מאמרי אדה\"א ויקרא ח\"א ע' תכ. וש\"נ. בהערה שלפנ\"ז."],["879","85","<b>עבדים היינו . . בסידור ד\"ה עבדים היינו</b>: נוסח ההגדה. סדר הגדה רצג, ג."],["880","86","<b>ונוזלי' מן לבנון</b>: שה\"ש ד, טו. ראה לקו\"ת האזינו עא, ד."],["881","87","<b>שיפץ העם . . קש לתבן</b>: שמות ה, יב."],["882","88","<b>נרפים . . אתם אומרים . . להוי'</b>: שמות שם, ח [ושם: הם צעקים . . לאלקינו]."],["883","89","<b>וידעו מצרים . . בהכבדי בפרעה</b>: בשלח יד, יח (צויין לקמן בפנים רפ\"ה)."],["884","90","<b>מי הוי'</b>: שמות ה, ב."],["885","91","<b>כנ\"ל</b>: פ\"ב על יד הערה 48."],["886","92","<b>הנ\"ל</b>: פ\"ב על יד הערה 38 ואילך."],["887","93","<b>וארא . . ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 24."],["888","94","<b>נודעתי . . יעוד וחיבור</b>: ראה גם לקו\"ת במדבר א, סע\"ב. ב, ד. נשא כא, ג. פינחס עז, סע\"א. סידור שחרית לו, ד. אוה\"ת וארא ס\"ע קמז ואילך. ע' ר. סה\"מ תרכ\"ח ע' עד. ע' קנא. תרל\"ח ע' כה. לקמן מאמר ד\"ה וידבר כו' קדושים תהיו פ\"א."],["889","95","<b>נודעתי . . ונועדתי</b>: ראה גם לקו\"ת במדבר ונשא שם."],["890","96","<b>שעבוד ויציאת מצרים . . שיתגלה ש' הוי'</b>: ראה גם תו\"א וארא נו, ד. אוה\"ת וארא ע' רמ. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' רל-רלא. סה\"מ תרכ\"ט ע' צד וע' ק."],["891","97","<b>לכן אמור לבנ\"י אני הוי'</b>: וארא ו, ו."]]],[2001910139,"שיצ\"מ הי' הקדמה למ\"ת<sup data-n=\"892\">98</sup> שיהי' אח\"כ ונועדתי לך שם<sup data-n=\"893\">99</sup> כו' כמ\"ש במ\"א, ואמנם בשעת קרי\"ס לפי שעה נתגלה שאפי' מצרים ידעו עכ\"פ בבחי' ידיעה כללית שאני הוי' כולא חד<sup data-n=\"894\">100</sup> וכמשי\"ת<sup data-n=\"895\">101</sup>, וכדכתיב וידעו מצרים כי אני הוי' היפך מה שאמר פרעה תחלה לא ידעתי את הוי'<sup data-n=\"896\">102</sup> כו'. ופי' וענין אע\"פ שמעולם אתה לא נתיישבה כסאך, לפי שמתחלה כביכול עמד וימודד ארץ<sup data-n=\"897\">103</sup>, שנחשב בחי' עמידה עדיין, ובקרי\"ס נתיישבה כסאך בבחי' ישיבה, והענין הוא דהנה בשבת אנו אומרים ביום השביעי נתעלה וישב על כסא כבודו<sup data-n=\"898\">104</sup>, ולכאו' צ\"ל האיך מרומז זה בתורה שביום השביעי נתעלה וישב כו', אמנם יובן זה ע\"פ מה שאנו רואים ההפרש בין עמידה לישיבה<sup data-n=\"899\">105</sup> שכשהאדם הוא טרוד במלאכתו אז הוא עומד, משא\"כ ענין בחי' הישיבה מורה על בחי' המנוחה, וכמ\"ש בשלמה (דה\"א ך\"ט ך\"ג) וישב שלמה על כסא ה', וכתי' בו (דה\"א ך\"ב ט') והוא יהי'<sup data-n=\"900\">106</sup> איש מנוחה, וכן ביעקב כתיב וישב יעקב<sup data-n=\"901\">107</sup> ופרש\"י ביקש לישב בשלוה<sup data-n=\"902\">108</sup> לפי שענין הישיבה מורה על מנוחה כו', ועד\"ז יובן ענין מה שביום השביעי נתעלה וישב כו' שזהו מפני שבשי\"ב נתלבשו החכ' והמדות בבחי' עשייה, והגם כי לא בעמל ולא ביגיעה<sup data-n=\"903\">109</sup> ברא הקב\"ה את עולמו כ\"א במאמר וברוח פיו, אבל מ\"מ דבורו של הקב\"ה חשיב מעשה<sup data-n=\"904\">110</sup>, וע\"מ נק' מילין דהדיוטא<sup data-n=\"905\">111</sup> לגבי בחי' אוא\"ס, וע' בד\"ה ולקחתם אגודת אזוב<sup data-n=\"906\">112</sup>, ובלק\"ת פ' אחרי בד\"ה כי ביום הזה יכפר דרוש הראשון<sup data-n=\"907\">113</sup>, ולאו אורחא דמלכא<sup data-n=\"908\">114</sup> לאשתעי במילין דהדיוטא ולכן נק' עש\"מ בשם עשייה שזהו ענין בחי' עמידה שעמד וימודד ארץ, אבל בשבת שהוא בחי' שביתה ומנוחה לכן נק' בשם ישיבה, וביום השביעי שהוא יום השבת",[["892","98","<b>שיצי\"מ הי' הקדמה למ\"ת</b>: ראה תו\"א שמות מט, א. נד, סע\"א. וארא נו, ד."],["893","99","<b>ונועדתי לך שם</b>: תרומה כה, כב."],["894","100","<b>שאני הוי' כולא חד</b>: ראה גם המשך תער\"ב ח\"ב ריש ע' תתקיט: ”דאני הוי' אני והוי' כולא חד\". שם ע' תתקכג: ”וכמ\"ש אני הוי' אני והוי' כולא חד\". זהר בראשית בהקדמה ו, א [בפי' אני הוי']: ”אקרי אני . . יי' וכלא חד\". אוה\"ת ויקרא כרך א ע' רלד. סה\"מ תרל\"ח ע' שלז (ובהנסמן בריש המאמר שם). פלח הרמון בחוקותי ע' תצה. לקמן מאמר והנחה ד\"ה ועבדתם את ה\"א פ\"א."],["895","101","<b>וכמשי\"ת</b>: לקמן פ\"ה."],["896","102","<b>לא ידעתי את הוי'</b>: שמות ה, ב."],["897","103","<b>אע\"פ שמעולם . . וימודד ארץ</b>: ראה לעיל פ\"ב על יד הערה 38 ואילך."],["898","104","<b>ביום השביעי . . כסא כבודו</b>: בברכת יוצר ד\"ה לא-ל אשר שבת."],["899","105","<b>ההפרש בין עמידה לישיבה</b>: ראה אוה\"ת חנוכה כרך ז ע' תתתנז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קכב. סה\"מ תרכ\"ט כאן ע' קנא. וש\"נ."],["900","106","<b>והוא יהי'</b>: בדה\"י שם: הוא יהי'. וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 44."],["901","107","<b>וישב יעקב</b>: וישב לז, א."],["902","108","<b>ופרש\"י ביקש לישב בשלוה</b>: וישב שם, ב בדילוג."],["903","109","<b>לא בעמל ולא ביגיעה</b>: ראה ב\"ר פ\"ג, ב. פי\"ב, י. סה\"מ תרל\"ב ח\"ב ע' שפז. ע' שפט. ראה גם לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א. סה\"מ עטר\"ת ע' לח."],["904","110","<b>דבורו . . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח. אוה\"ת יתרו כרך ז ע' ב'תשב ואילך. סה\"מ תרס\"ח ע' צט."],["905","111","<b>וע\"מ נק' מילין דהדיוטא</b>: נסמן לעיל במאמר ד\"ה קדש ישראל לה' פ\"ב הערה 83."],["906","112","<b>בד\"ה ולקחתם אגודת אזוב</b>: סה\"מ תרכ\"ז ס\"ע רטו ואילך. תרל\"א ח\"א ס\"ע קמה ואילך."],["907","113","<b>ובלק\"ת פ' אחרי . . הראשון</b>: כה, ד."],["908","114","<b>ולא אורחא דמלכא</b>: ראה בהערות שלפנ\"ז."]]],[2001910140,"נתעלה שהוא בחי' החזרת המוחין והמדות למקורן, וישב על כסא כבודו, שהכסא היא ג\"כ בחי' שביעאה, כי שית דרגין לכורסייא, ושביעאה עלייהו<sup data-n=\"909\">115</sup>, היא בחי' הכסא עצמה, וזהו ביום השביעי שבת מנוחה ישב על כסא ג\"כ שביעאה, ועד\"ז יובן ענין שבקרי\"ס נתיישבה כסאך, לפי שמ\"ש בשירת הים ה' איש מלחמה<sup data-n=\"910\">116</sup> קאי על קודם קרי\"ס שהי' ע\"ד בחי' מלחמה, א\"כ אין זה מנוחה עדיין וזהו כביכול עומד כו', אבל כשעברו בנ\"י בים ואמרו שירה באז נתיישבה כסאך שלא הי' צריך למלחמה, כ\"א שממילא בטלו וכמ\"ש שמעו עמים ירגזון<sup data-n=\"911\">117</sup> כו' תפול עליהם אימתה<sup data-n=\"912\">118</sup> כו' שכולם קיבלו אימת הקב\"ה כו' וא\"צ למלחמה כלל* כ\"א מנוחה וזהו ענין בחי' ישיבה שנתיישבה כסאך.\nה) <b>ולהבין</b> ענין מ\"ש ה' איש מלחמה, שלכאו' אינו מובן כלל איך שייך בחי' מלחמה עם ש' הוי', והענין הוא שקודם קרי\"ס כתי' (בשלח י\"ד י\"ח) וידעו מצרים כי אני הוי' בהכבדי בפרעה, והנה ארז\"ל ברבות מקץ פ\"צ<sup data-n=\"913\">119</sup> ע\"פ אני\n\n)\n<i>נרשם בשולי היריעה בצד השמאלי של העמוד ולא נרשם מקומו בפנים ואולי שייך לכאן:</i>\nכ\"א עמלק[ftnref_8203_יב] לבדו שהי' יודע[ftnref_8204_יג] כו'.\nנרשם בשולי היריעה ולא נסמן מקומו בפנים:\nרק עמלק שהי' מנגד לדעת[ftnref_8205_יד], יודע רבונו[ftnref_8206_טו], לא פעל בו מה שידעו מצרים ולכן אין הכסא שלם[ftnref_8207_טז] כו' עד שיתברר.",[["909","115","<b>שית דרגין . . עלייהו</b>: זהר תזריע מז, ב [ושם: שיתא דרגין לכורסייא הוא על כורסייא. התיבות: ”ושביעאה עלייהו\" הובא שם לפנ\"ז. אבל כ\"ה גם בסה\"מ תרכ\"ט כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58].\nראה אוה\"ת ויקרא כרך א' ע' רסב ואילך. ביאוה\"ז לכ\"ק אדמו\"ר הצ\"צ ח\"ב תזריע ע' תתפז. ע' תתצד. (יהל אור) תהלים ריש ע' תרמה. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ס\"ע י ואילך. תרכ\"ט כאן ע' קנב. וש\"נ."],["910","116","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["911","117","<b>שמעו עמים ירגזון</b>: בשלח טו, יד."],["912","118","<b>תפול עליהם אימתה</b>: בשלח שם, טז."],["913","119","<b>ברבות מקץ פ\"צ</b>: סימן ב. ראה לקו\"ת שלח מח, א.\nהובא גם בלקו\"ת שלח מז, סע\"ד, ושם: מקץ [ר\"פ צ'] ובפ' קדושים [ס\"פ כ\"ד].\n\n[ftn_8203_יב])<i>למלחמה . . עמלק:</i> בשלח יז, ח ואילך.\n\n[ftn_8204_יג])<i>עמלק . . יודע:</i> ראה בסמוך הערה טו.\n\n[ftn_8205_יד])<i>עמלק שהי' מנגד לדעת:</i> ראה מאורי אור מערכת עמלק אות עט. תו\"א תצוה פג, סע\"ד [ושם מציין: ועיין בהרמ\"ז ר\"פ ויקהל — ראה אוה\"ת בלק ע' א'נד. בסהמ\"צ להצ\"צ צד, ריש ע\"ב מציין: והרמ\"ז והמק\"מ — ראה מקדש מלך בשלח סה, ב. ר\"פ ויקהל]. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ראה גם אוה\"ת פרשה זכור ע' א'תשעה.\n\n[ftn_8206_טו])<i>עמלק . . יודע רבונו:</i> כ\"ה בכ\"מ בדא\"ח ומהם: תו\"א תצוה פג, סע\"ד. פה, ד. (וראה שם פד, ב). מאמרי אדה\"ז תקס\"ה ח\"א ע' תטו. אוה\"ת וארא ס\"ע רג. סה\"מ תרל\"ב ח\"א ע' קטו. ע' רמט. ח\"ב ע' תצו. תרל\"ג ח\"א ע' עד. ע' קסח. תרנ\"ו ע' תלב. סה\"מ תרס\"ה ע' ריג ובהערה שם. לקו\"ש תצא כרך יט ע' 224 הערה 29. פ' זכור כרך כא ע' 193 הערה 38. לקמן מאמר ד\"ה מגילה נקראת פ\"ג.\n\n[ftn_8207_טז])<i>אין הכסא שלם:</i> ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. לקו\"ש י\"ג סיון כרך כג ע' 268 הערה 33. וראה גם לקמן מאמר ד\"ה מגילה נקראת פ\"ד."]]],[2001910141,"פרעה<sup data-n=\"914\">120</sup>, מן אני של ב\"ו את<sup data-n=\"915\">121</sup> למד אני של הקב\"ה, שע\"י<sup data-n=\"916\">122</sup> שפרעה אמר<sup data-n=\"917\">123</sup> ליוסף אני פרעה זכה לכל<sup data-n=\"918\">124</sup> הכבוד הזה לכשיבא אני של הקב\"ה (ישעי' מ\"ו ד') אני עשיתי ואני אשא<sup data-n=\"919\">125</sup> עאכ\"ו. והענין הוא דהנה כתי' רם כו' על השמים כבודו<sup data-n=\"920\">126</sup> שפרעה אמר שהקב\"ה הוא רם שהוא בבחי' רוממות ולכן על השמים כבודו שהנבראים שבשמים הם בחי' שכלים נבדלים<sup data-n=\"921\">127</sup>, אבל למטה בארץ עזב ה' את הארץ<sup data-n=\"922\">128</sup> בידי המזלות לפי שאמר שהוא השפלה וירידה נגדו ית' להשגיח בעלולים השפלים, אבל באמת הנה כתי' המגביהי לשבת המשפילי לראות<sup data-n=\"923\">129</sup> בשמים ובארץ, כי באמת גם השמים הוא בחי' השפלה נגדו, ולכן כשם שהוא יכול להשפיל א\"ע בבחי' שמים כן הוא כל יכול להשפיל א\"ע בארץ, ששמים וארץ שוין לפניו ית', ומקום גדולתו שם אתה מוצא ענותנותו<sup data-n=\"924\">130</sup> שמשפיל א\"ע בשמים ובארץ בשוה כו', וזהו וידעו מצרים כי אני הוי', והיינו שפרעה הוא אותיות הערף ומקבל ממקום גבוה שהוא בחי' ערף דא\"א שהוא בחי' רם היינו שפרעה הי' מקבל מבחי' רוממות ששם כחשיכה כאורה<sup data-n=\"925\">131</sup> כו', ועוד שהי' מקבל ג\"כ מבחי' הצמצום דש' אלקים<sup data-n=\"926\">132</sup> וכמו שא' לו יוסף אלקים יענה את שלום פרעה<sup data-n=\"927\">133</sup>, אבל מבחי' שם הוי' לא הי' יכול לקבל<sup data-n=\"928\">*134</sup>, לפי שכדי שיקבל מש' הוי' הי' צריך להיות בבחי' ביטול, לכן אמר פרעה לא ידעתי את הוי', ולא הי' רוצה לקבל משם הוי', כ\"א הגביה א\"ע בבחי' רוממות ואמר מי הוי' אשר אשמע בקולו כו', וא\"כ זהו מלחמה להוי', אבל ע\"י קרי\"ס (בהכבדי בפרעה, ע\"ד מה כבוד שאמרו ברבות<sup data-n=\"929\">134</sup>) וידעו מצרים ג\"כ כי אני הוי' כו' פי' אני הוא כמ\"ש אני ראשון ואני אחרון<sup data-n=\"930\">135</sup>, אני אחרון הוא בחי' מל' ש' אלקים<sup data-n=\"932\">137</sup>, וא\"כ פי' אני הוי' שבחי' אני אחרון וש' הוי' כולא חד, וגם י\"ל שקאי על אני ראשון שאני ראשון הוא בחי' כתר<sup data-n=\"931\">136</sup>",[["914","120","<b>ע\"פ אני פרעה</b>: מקץ מא, מד. בלקו\"ת ליתא."],["915","121","<b>את</b>: כ\"ה בב\"ר. בלקו\"ת ובויק\"ר: אתה."],["916","122","<b>שע\"י</b>: בב\"ר ובויק\"ר: (ו)מה אני של בשר ודם ע\"י. בלקו\"ת: כו' ע\"י."],["917","123","<b>שפרעה אמר</b>: בב\"ר: שאמר פרעה הרשע. בלקו\"ת ובויק\"ר: שאמר פרעה."],["918","124","<b>זכה לכל</b>: כ\"ה גם בלקו\"ת ובויק\"ר. ובב\"ר: הי' לו כל."],["919","125","<b>אני עשיתי ואני אשא</b>: בלקו\"ת ובויק\"ר: הובא כתוב אחר."],["920","126","<b>רם . . על השמים כבודו</b>: תהלים קיג, ד. ראה גם תו\"א מקץ לד, ד. סידור שער תפלת ר\"ה רלז, ב ואילך. מאמרי אדה\"א דברים ח\"ג ס\"ע א'לג ואילך. וש\"נ."],["921","127","<b>שכלים נבדלים</b>: ראה מו\"נ ח\"ב פ\"ב-פ\"ו. תו\"ח בשלח ח\"א קסה, סע\"ב. וש\"נ. (וראה גם סה\"מ תר\"ם ח\"א ע' י. וש\"נ. לעיל מאמר ד\"ה הקבצו ושמעו ספ\"א)."],["922","128","<b>עזב ה' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["923","129","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה. ו."],["924","130","<b>ומקום גדולתו . . ענותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. ה'ש\"ת ע' 40 בהערה. תו\"ח יתרו ח\"ב רנט, ב הערה 122."],["925","131","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["926","132","<b>הצמצום דש' אלקים</b>: ראה גם לקמן מאמר ד\"ה ועבדתם את ה\"א פ\"ב. שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["927","133","<b>אלקים . . שלום פרעה</b>: מקץ מא, טז."],["928","*134","<b>מבחי' שם הוי' . . לקבל</b>: ראה גם לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי פ\"ז ד\"ה דהנה פרעה."],["929","134","<b>מה כבוד שאמרו ברבות</b>: שמו\"ר רפכ\"ג."],["930","135","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["932","137","<b>מל' ש' אלקים</b>: ראה זהר בראשית כב, א. אחרי סה, א. תו\"ח וארא ח\"א עה, ב הערה 202."],["931","136","<b>אני . . מל' . . כתר</b>: ראה לקו\"ת שלח מז, ד."]]],[2001910142,"בחי' רוממות וש' הוי' כולא חד וזהו אני הוי', והיינו כי ב' הפי' אמת כי ש' הוי' הוא המחבר ב' בחי' דאני ראשון, ואני אחרון, וכמ\"ש ראו עתה כי אני אני הוא<sup data-n=\"933\">138</sup>, שבחי' זו יתגלה לע\"ל ועכשיו העבודה לראות, ע\"ד שאו מרום עיניכם וראו<sup data-n=\"934\">139</sup> כו' לראות ולהבין איך שבאמת אני אני הוא, ועמ\"ש מזה בד\"ה את ה' האמרת<sup data-n=\"935\">140</sup> ושם בענין ההפרש בין ג\"ע לתחה\"מ, וזהו מה שמסיים פסוק ה' איש מלחמה, הוי' שמו פי' שמו הוא כמארז\"ל בפדר\"א עד שלא נברא העולם הי' הוא ושמו בלבד<sup data-n=\"936\">141</sup>, ושמו זה עם ש' הוי' כולא חד כו', וזהו וידעו מצרים כי אני הוי' בהכבדי בפרעה, שלא כמו שא' פרעה מי הוי' שהגביה א\"ע לקבל מבחי' רם רוממות, או מבחי' הצמצום דש' אלקי', אלא אני כפי שני הפירושים והוי' כולא חד ממש, וזה נעשה ע\"י שהוי' איש מלחמה, הוי' שמו כמשי\"ת.\n<b>והנה</b> קודם קרי\"ס כל העשר מכות שהביא על פרעה ומצרים הי' בדרך מלחמה כמו שארז\"ל<sup data-n=\"937\">142</sup> הובא בפרש\"י (בפ' וארא ח' י\"ז) בענין סדר המכות שהביא שזהו כדרך הנלחמים שמתחלה מקלקל מעינותי' כו', אבל בקי\"ס וידעו כו' שאני והוי' כולא חד וא\"צ למלחמה לפי שהוי' שמו שנמשכה המשכה מלמעלה מהשתלשלות בשם הוי', אז א\"צ למלחמה כלל כי ממילא נתבטלו כמ\"ש שמעו עמים, תפול עליהם אימתה כו'. ודוגמא להבין זה, זהו ע\"ד ההפרש בין דוד לשלמה כי דוד הוא איש מלחמה<sup data-n=\"938\">*143</sup> שכל ימיו הי' צריך למלחמה ולהכניע שונאיו, ולא הי' לו מנוחה<sup data-n=\"939\">143</sup>, ולכן לא בנה הבהמ\"ק<sup data-n=\"940\">*144</sup>, אבל שלמה נק' איש מנוחה בפסוק כנ\"ל<sup data-n=\"941\">144</sup>, מפני שלא הי' צריך למלחמה כלל כי כולם היו בטלים אליו והיו באים לשמוע חכמתו<sup data-n=\"942\">*145</sup>, לכן נק' איש מנוחה, ועד\"ז יובן למעלה כבי' שעד שלא בראת עולמך היית אתה, ומשבראת עולמך אתה הוא אלא כבי' עומד כו' וע\"י שירת הים באז ישיר נתיישבה מלכותך בחי' ישיבה הוא מנוחה היפך המלחמה, לפי שבקי\"ס הי' הגילוי בחי' אז, אלף הוא בחי' אלופו ש\"ע האצילות שהוא בחי' א\"א בזיין הוא בחי' ז' מדות, ובבחי' זו אינו שייך מלחמה כלל, כי מ\"ש הוי' איש מלחמה זהו רק בש' הוי' דז\"א כו' אבל למעלה בא\"א אינו שייך מלחמה כלל כי ממילא בטלים, שזהו ענין הוי' שמו שאמר אח\"כ אחר ה' איש מלחמה לפי מ\"ש בפדר\"א עד שלא נברה\"ע הי' הוא ושמו כנז' לעיל שזהו אני ראשון והוי' כולא חד שזה קאי על אחר קרי\"ס, שלפי שעה נתגלה בים כמו הגילוי שיהי' לע\"ל שיתחברו ב' בחי' אני הנ\"ל.",[["933","138","<b>ראו עתה . . אני הוא</b>: האזינו לב, לט."],["934","139","<b>שאו מרום עיניכם וראו</b>: ישעי' מ, כו."],["935","140","<b>בד\"ה את ה' האמרת</b>: ראה סה\"מ תרל\"ב ח\"ב ע' תעא ואילך. ס\"ע תעט ואילך ובהנסמן שם (ובריש המאמר שם)."],["936","141","<b>בפדר\"א עד . . ושמו בלבד</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["937","142","<b>כמו שארז\"ל</b>: ברש\"י מציין: באגדה . . במדרש רבי תנחומא בא ד. ראה גם לקו\"ש וארא כרך יא ע' 27 ואילך."],["938","*143","<b>דוד הוא איש מלחמה</b>: שמו\"ב יז, ח. דבהי\"א כח, ג."],["939","143","<b>דוד . . ולא הי' לו מנוחה</b>: מלכים-א ה, יז ואילך."],["940","*144","<b>ולכן לא בנה הבהמ\"ק</b>: דבהי\"א כב, ח."],["941","144","<b>כנ\"ל</b>: פ\"ד על יד הערה 106."],["942","*145","<b>והיו באים לשמוע חכמתו</b>: מלכים-א ה, יד."]]],[2001910143,"וא\"ו) <b>ובכ\"ז</b> יובן מה שקרי\"ס נק' זיווג כמארז\"ל קשה לזווגם כקרי\"ס שמשמע שקרי\"ס נק' זיווג, שלכאו' א\"מ מהו ענין קרי\"ס לזיווג, אך הענין יובן ע\"פ משנ\"ת בד\"ה אז ישיר<sup data-n=\"943\">145</sup> דהתו' נק' מאורסה לפי שהתורה נק' ראשית כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"944\">*146</sup>, שראשית הוא בחי' מקבל<sup data-n=\"945\">146</sup>, אבל נש\"י, ישראל לי ראש<sup data-n=\"946\">147</sup>, הם ממשיכים בתורה מבחי' אשר בחי' תענוג<sup data-n=\"947\">148</sup> עליון שהוא למעלה מהחכמה, וכן מארז\"ל במד\"ר הנ\"ל כנס\"י הוא בן זוגך לשבת שזהו דבור זכור את יום השבת לקדשו שלכאורה א\"מ הלא שבת מקדשא וקיימא כנ\"ל, אלא שזהו ג\"כ מטעם הנ\"ל שבתורה, שהרי השבת נק' ג\"כ שבת בראשית (בגמ' נדרים דף ע\"ח<sup data-n=\"948\">149</sup>), וכמ\"ש בתשובת הרשב\"א שששת ימים עם השבת נקראים ז' ימי ההיקף<sup data-n=\"949\">150</sup>, ולכן כל שבת נק' שבת בראשית, והגם שמקדשא וקיימא שהוא בחי' קדש בחי' חכמה<sup data-n=\"951\">152</sup>, ולא כמו יו\"ט שנק' מקרא קדש<sup data-n=\"950\">151</sup> נה\"י דאבא מתלבשים במוחין דאימא שזה תלוי בישראל כמ\"ש אשר תקראו אתם חסר כתיב כנ\"ל, משא\"כ שבת מקדשא כו' שהשבת הוא בחי' קדש בעצם היינו בחי' מוחין דאבא כמ\"ש ושמרתם את השבת<sup data-n=\"952\">153</sup> כי קדש היא, וזה אינו תלוי בישראל כלל שלכן מברכין רק מקדש השבת בלבד ולא מקדש ישראל והשבת, מ\"מ מאחר שנק' שבת בראשית הרי השבת ג\"כ בחי' מקבל, וישראל לי ראש ל' דכר<sup data-n=\"953\">154</sup> הם משפיעים בשבת וכמ\"ש לעשות את השבת היינו להמשיך בשבת מבחי' אשר, הוא בחי' תענוג עליון שלמעלה מהחכמה, וז\"ע מאה ברכות<sup data-n=\"954\">155</sup> א\"ת מ\"ה אלא מאה<sup data-n=\"955\">156</sup>, תוס' בחי' אלף כו', שמברכי' על הבירורי' שמבררי' ומברכים אקב\"ו<sup data-n=\"956\">157</sup>, שמהם נמשך בשבת הענג מבחי' אשר תענוג עליון, (וע' בד\"ה את ה' האמרת הנ\"ל<sup data-n=\"957\">158</sup> מענין בחי' הענג שנמשך מהבירורים דמעשה המצות), וכמ\"ש וקראת לשבת ענג<sup data-n=\"958\">159</sup> שעבודת נש\"י לקרות ולהמשיך בשבת מבחי' ענג העליון, שזהו ע\"י העשיית המצות בששת ימי החול, וזהו ששת ימים תעבוד בבחי' עבודת הבירורים<sup data-n=\"959\">160</sup>",[["943","145","<b>בד\"ה אז ישיר</b>: נדפס לפני מאמר זה ושם ספ\"א. פ\"ג."],["944","*146","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["945","146","<b>שראשית . . מקבל</b>: ראה תו\"א יתרו ע, א. סה\"מ תר\"ם ח\"א ע' קסב. וש\"נ. ראה גם (ולהבא בסמוך) לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"ג."],["946","147","<b>ישראל לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["947","148","<b>אשר . . תענוג</b>: ראה תו\"א תולדות יח, סע\"ב. ויצא כג, ג. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."],["948","149","<b>נדרים דף ע\"ח</b>: ע\"א ואילך."],["949","150","<b>בתשובת הרשב\"א . . ז' ימי ההיקף</b>: ח\"א ס\"ט."],["951","152","<b>קדש בחי' חכמה</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א."],["950","151","<b>שבת . . קדש . . יו\"ט שנק' מקרא קדש</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. לקו\"ת צו יב, א. סה\"מ תר\"ם ח\"א ס\"ע קפז ואילך. וש\"נ."],["952","153","<b>ושמרתם את השבת</b>: תשא לא, יד."],["953","154","<b>ראש ל' דכר</b>: ראה לעיל הערה 146."],["954","155","<b>מאה ברכות</b>: מנחות מג, ב."],["955","156","<b>א\"ת מ\"ה אלא מאה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["956","157","<b>ומברכים אקב\"ו</b>: נוסח ברכת המצות."],["957","158","<b>בד\"ה את ה' האמרת הנ\"ל</b>: תרל\"ב ח\"ב ע' תפב ואילך."],["958","159","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["959","160","<b>ששת ימים . . עבודת הבירורים</b>: ראה גם מאמר ד\"ה וידעת היום שבהערה 161."]]],[2001910144,"דתומ\"צ, ועי\"ז יבא לבחי' לעשות את השבת מי שטרח בע\"ש<sup data-n=\"960\">*161</sup> כו' וכן ארז\"ל מונה ששה ימים<sup data-n=\"961\">161</sup> ומשמר יום אחד לפי שצ\"ל לעשות את השבת היינו שע\"י הבירורים דששת ימי החול יהי' נמשך אח\"כ בחי' הענג עליון בשבת, ובחי' ענג זה הוא כמ\"ש אז תתענג על הוי'<sup data-n=\"962\">162</sup> שהוא למעלה גם כן מבחי' ש' הוי' דחכמה כמ\"ש הוי' בחכ'<sup data-n=\"963\">163</sup> שזהו בחי' שבת בעצם, וישראל משפיעים בחי' העונג בשבת, וזהו זכור את יוה\"ש שנש\"י ממשיכים ומשפיעים בשבת ולכן א\"ל הקב\"ה כנס\"י היא בן זוגך כו', ועד\"ז יובן בבחי' ים סוף שנק' ג\"כ זיוג, לפי ששרש נש\"י הם למעלה מבחי' ים, וממשיכים בבחי' ים, לפי שהים סוף הוא בחי' סופא דכל דרגין<sup data-n=\"964\">164</sup> בחי' מ\"מ כל עולמים<sup data-n=\"965\">165</sup>, ונש\"י הם בחי' ז\"א<sup data-n=\"966\">166</sup> כו', ואפי' אם נפרש שים הוא בחי' ים החכמה<sup data-n=\"967\">167</sup>, אעפ\"כ שרש נש\"י הם למעלה גם מבחי' חכמה כנ\"ל בפי' זכור את יום השבת לקדשו שממשיכים בחי' ענג בחכמה כו', וכמשנ\"ת בד\"ה אז ישיר<sup data-n=\"968\">168</sup> ששרשם מבחי' לבנון לובן העליון<sup data-n=\"969\">169</sup> כמ\"ש ונוזלים מן לבנון כו'. ומ\"מ מה שפי' רבינו ז\"ל שהשבת גבוה מישראל זהו ג\"כ אמת, וכמשנ\"ת בד\"ה אז ישיר<sup data-n=\"970\">170</sup> שמצד בחי' הנשמה המלובשת בגוף המצות גבוהים יותר מישראל, לפי שרמ\"ח פקודין הם רמ\"ח איברים דמלכא<sup data-n=\"971\">171</sup>, והם מגביהים את הנשמה המלובשת בגוף שתתקשר לשרש ומקור הנשמה, ואז מצד שרש הנשמה נש\"י משפיעים תוס' אור בבחי' מצות הוי' רמ\"ח פקודין כו' מבחי' מצותי<sup data-n=\"972\">172</sup> שהקב\"ה עצמו מקיים המצות<sup data-n=\"973\">173</sup> היינו בחי' מה שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך ע\"א<sup data-n=\"974\">174</sup> בחי' כתר, וב' בחי' אלו ז\"ע וזכרתם את כל מצות הוי'<sup data-n=\"975\">175</sup>, ובחי' למען תזכרו כו' מצותי<sup data-n=\"976\">176</sup> ע\"ש. ועד\"ז יובן בשבת שעצם מצות שבת כמו שהיא ברמ\"ח מ\"ע ושס\"ה ל\"ת<sup data-n=\"977\">177</sup> הוא גבוה מישראל היינו מבחי' דנשמה המלובשת בגוף, אמנם כשמתעלים",[["960","*161","<b>מי שטרח בע\"ש</b>: ע\"ז ג, א."],["961","161","<b>מונה ששה ימים</b>: שבת סט, ב. ראה שו\"ע אדה\"ז הל' שבת סשד\"מ. לקמן מאמר והנחה ד\"ה וידעת היום (סוף פיסקא וידעת היום). ד\"ה ושאבתם מים בששון קיצר ח. סה\"מ תר\"ם ח\"א ע' רמה. וש\"נ."],["962","162","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קי. וש\"נ. תו\"ח וארא ח\"א נ, ב. וש\"נ."],["963","163","<b>הוי' בחכ'</b>: משלי ג, יט."],["964","164","<b>שהים סוף . . דכל דרגין</b>: ראה זהר בשלח נו, א. רע\"מ פינחס רנה, א."],["965","165","<b>מ\"מ כל עולמים</b>: תהלים קמה, יג."],["966","166","<b>ונש\"י הם בחי' ז\"א</b>: ראה תו\"א יתרו סט, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שב ואילך."],["967","167","<b>שים . . ים החכמה</b>: ראה עה\"כ לבעל סה\"ד מערכת ים. תו\"א מקץ לח, ד. סידור שחרית נח, ב. שחרית לשבת קעח, ד. סה\"מ תרל\"ח ע' תפח. וש\"נ. לקמן מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע פיסקא ועוי\"ל בפי' ספק."],["968","168","<b>בד\"ה אז ישיר</b>: נדפס לפני מאמר זה ושם פ\"ב. וראה גם לעיל רפ\"ד."],["969","169","<b>לבנון לובן העליון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפ. תקס\"ב ח\"א ע' פו. תקס\"ד ע' קעד."],["970","170","<b>בד\"ה אז ישיר</b>: נדפס לפני מאמר זה ושם פ\"ד."],["971","171","<b>שרמ\"ח פקודין הם רמ\"ח איברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["972","172","<b>מצות הוי' . . מצותי</b>: ראה גם לעיל מאמר ד\"ה אז ישיר פ\"ד ובהערה 88."],["973","173","<b>שהקב\"ה עצמו מקיים המצות</b>: ראה גם לעיל פ\"ד שם ובהנסמן לשם."],["974","174","<b>שתרי\"ג . . וז' . . תר\"ך ע\"א</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' ובהערות 131-135."],["975","175","<b>וזכרתם את כל מצות הוי'</b>: שלח טו, לט."],["976","176","<b>למען תזכרו כו' מצותי</b>: שלח שם, מ."],["977","177","<b>ברמ\"ח מ\"ע ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."]]],[2001910145,"לשורש ומקור הנשמה ע\"י בחי' המצות כנ\"ל אזי כנס\"י הוא בן זוגך שנש\"י משפיעים בשבת שז\"ע לעשות את השבת ומי שטרח בע\"ש בעבודת הבירורים שמזה נעשה ענג למעלה ואז וקראת לשבת בחי' מוחין דאבא (היינו גם בחי' יום השבת כו') מבחי' הענג, שבחי' ענג זה הוא למעלה גם מש' הוי' דחכמה כמ\"ש אז תתענג על הוי', וזהו זכור שתהי' משפיע גם ביום השבת מבחי' הענג הנ\"ל דתר\"ך ע\"א בחי' כתר מצותי ממש כו'."],[2001910146,"<h3>ועבדתם את הוי' אלקיכם</h3>\n<b>בס\"ד משפטים ך\"ג ך\"ה</b>\n<b>ועבדתם</b> את הוי' אלקיכם<sup data-n=\"978\">1</sup> ובירך כו' והסירותי<sup data-n=\"979\">2</sup> כו', וארז\"ל בפרק ח' דב\"ק דף צ\"ב ע\"ב ועבדתם את הוי' אלקיכם זו ק\"ש ותפלה<sup data-n=\"980\">3</sup>, וכמאמרז\"ל ע\"פ ולעבדו בכל לבבכם<sup data-n=\"981\">4</sup> איזהו עבודה שבלב זו תפלה<sup data-n=\"982\">5</sup> כו', ולהבין זה צ\"ל מה שתחלת הפסוק נא' בלשון נסתר ועבדתם, ולא אמר מי הוא האומר זה, וסוף הפסוק נאמר לשון נוכח<sup data-n=\"983\">6</sup> והסירותי מחלה, כמדבר בעד עצמו שהוא יסור המחלה כו', וגם צ\"ל מי הוא האומר ועבדתם שא\"א לומר שמשה הוא האומר ועבדתם את כו' שהרי תחלת הפרשה הוא הנה אנכי שולח מלאך לפניך<sup data-n=\"984\">7</sup> שזהו מאמר הקב\"ה למשה, וגם א\"א לומר שהמדבר ועבדתם הוא ש' הוי' דהל\"ל והייתם לי עבדים, וברכתי את לחמך, אלא שצ\"ל כמ\"ש הרמב\"ן בהקדמתו לפי' התורה<sup data-n=\"985\">8</sup>, וז\"ל לא כתב מרע\"ה<sup data-n=\"986\">9</sup> את<sup data-n=\"987\">10</sup> התורה כמדבר בעד עצמו כמו<sup data-n=\"988\">11</sup> שנא' ביחזקאל ויהי<sup data-n=\"989\">12</sup> דבר ה' אלי לאמר<sup data-n=\"990\">13</sup>, וכן",[["978","1","<b>ועבדתם את הוי' אלקיכם</b>: מאמר זה והמשכו מאמר ד\"ה ובירך את לחמך הם מאמר ד\"ה והי' עקב תרל\"ג (בהשמטת ההתחלה ובהוספות וכו') שנדפס בסה\"מ תרל\"ג ח\"ב ס\"ע תכט ואילך. וש\"נ. ונעתקו במאמר ד\"ה זה בסה\"מ תרס\"ב ע' ערב ואילך עם הוספות וכו'.\nהמאמר נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו."],["979","2","<b>ועבדתם . . ובירך כו' והסידותי</b>: משפטים כג, כה (כמצויין בהכותרת כאן)."],["980","3","<b>דב\"ק דף צ\"ב ע\"ב ועבדתם . . ק\"ש ותפלה</b>: מובא גם באוה\"ת משפטים ע' א'רמב."],["981","4","<b>ולעבדו בכל לבבכם</b>: עקב יא, יג."],["982","5","<b>איזהו עבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. אוה\"ת עקב ע' תרח."],["983","6","<b>שתחלת הפסוק . . נסתר . . נוכח</b>: ראה גם אוה\"ת משפטים כאן ע' א'ריט. ע' א'רלט."],["984","7","<b>הנה אנכי . . לפניך</b>: משפטים כג, כ."],["985","8","<b>הרמב\"ן בהקדמתו לפי' התורה</b>: ראה פתיחת הרמב\"ן על התורה. הועתק גם באוה\"ת משפטים כאן ע' א'ריט. דברים ע' א. יתרו ע' תתקעט. ראה גם אוה\"ת משפטים כאן כרך ח ע' ג'לא. סה\"מ תרל\"ח ע' שלג. וש\"נ. לקמן מאמר ד\"ה ובירך את לחמך בסופו."],["986","9","<b>מרע\"ה</b>: כ\"ה גם באוה\"ת משפטים כאן ע' א'ריט. דברים ע' א. יתרו ע' תתקעט. ברמב\"ן שם: משה רבינו."],["987","10","<b>את</b>: כ\"ה גם באוה\"ת שבהערה שלפנ\"ז. ברמב\"ן שם ליתא."],["988","11","<b>עצמו כמו</b>: כ\"ה גם באוה\"ת משפטים ודברים שבהערה 9. ברמב\"ן שם: עצמו . . כמו."],["989","12","<b>ביחזקאל ויהי</b>: כ\"ה גם באוה\"ת שבהערה שלפנ\"ז. ברמב\"ן שם: ביחזקאל . . ויהי."],["990","13","<b>לאמר</b>: כ\"ה גם באוה\"ת שבהערה שלפנ\"ז. ברמב\"ן שם ניתוסף: בן אדם — יחזקאל ג, טז-יז. ראה סה\"מ תרל\"ח שם הערה 14."]]],[2001910147,"בירמיהו<sup data-n=\"991\">14</sup>, אבל<sup data-n=\"992\">15</sup> מרע\"ה כתב כשלישי<sup data-n=\"993\">16</sup> המדבר כו' עכ\"ל<sup data-n=\"994\">17</sup>, ופי' שלישי המדבר ז\"ע בחי' עצמיות המאציל<sup data-n=\"995\">18</sup> שע\"ז רמז הרמב\"ן ז\"ל כשלישי המדבר, וכענין שנא' בהרבה פרשיות שבתורה ובציוי המצות שמסיים אני הוי', שלכאו' צ\"ל הלא אינו ידוע<sup data-n=\"996\">19</sup> מי הוא האני, אלא שצריך לומר שאני מורה על בחי' עצמיות המאציל אני ראשון<sup data-n=\"997\">20</sup> (כמ\"ש בד\"ה זכור את יוה\"ש לקדשו<sup data-n=\"998\">21</sup>, ושם בענין ה' שמו כו'), וע\"ז הוא שאומר אני הוי', שאני הוא בחי' עצמותו והוי' כולא חד<sup data-n=\"999\">22</sup>, ובחי' עצמותו זהו ידוע ושגור בפי הכל<sup data-n=\"1000\">23</sup>.\n<b>והנה</b> בענין העבודה יש בגמרא<sup data-n=\"1001\">24</sup> ובפסיקתא<sup data-n=\"1002\">25</sup> הובא בילקוט האזינו<sup data-n=\"1003\">26</sup> שמהם משמע שהעבודה צורך גבוה<sup data-n=\"1004\">27</sup>, ויש במדרש תנחומא פ' שמיני<sup data-n=\"1005\">28</sup> ובמדת\"ל סי' י\"ח<sup data-n=\"1006\">29</sup>\n\n<i>נרשם בשולי היריעה:</i>\nובזה יובן מה שחותם בהרבה ציווים אני הוי' שלכאו' צ\"ל הלא אינו ידוע מי הוא האני, אלא מפני ששם שמים שגור בפי הכל[ftnref_8208_א] וזהו אני הוא ש' ה' כו'.",[["991","14","<b>וכן בירמיהו</b>: כ\"ה גם באוה\"ת דברים. ובאוה\"ת משפטים (וכן בירמי'). ברמב\"ן שם: וכמו שנאמר בירמי'. ראה סה\"מ תרל\"ח שם הערה 15."],["992","15","<b>בירמיהו אבל</b>: ראה גם באוה\"ת שבהערה שלפנ\"ז. ברמב\"ן שם: בירמיה . . אבל."],["993","16","<b>כתב כשלישי</b>: כ\"ה גם באוה\"ת שבהערה שלפנ\"ז. ברמב\"ן שם: כתב . . כשלישי."],["994","17","<b>עכ\"ל</b>: ראה שדי חמד מערכת כללי הפוסקים כרך ט סט\"ז אות סג."],["995","18","<b>שלישי המדבר . . עצמיות המאציל</b>: ראה גם אוה\"ת יתרו ע' תשעא. ובשם אדה\"ז בפלח הרמון יתרו ע' ריז. אמור ע' רל וע' רלב."],["996","19","<b>אני הוי' . . אינו ידוע</b>: שמיני יא, מד. מה. ועוד. ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה שוש תשיש הא' והב' על יד הערות 74-75. אוה\"ת יתרו ס\"ע תתקלח ואילך. סה\"מ תרל\"ח ע' שלב. וש\"נ. פלח הרמון אמור ע' רלב."],["997","20","<b>אני ראשון</b>: ישעי' מד, ו."],["998","21","<b>בד\"ה זכור . . לקדשו</b>: נדפס לפני מאמר זה ושם פ\"ה."],["999","22","<b>שאני . . והוי' כולא חד</b>: ראה גם לעיל שם ובהערה 100."],["1000","23","<b>עצמותו . . בפי הכל</b>: ראה הנסמן בשולי היריעה כאן."],["1001","24","<b>בגמרא</b>: שבת פט, א הועתק בסמוך בפנים.\nהובא בעבודת הקדש בהקדמה [ירושלים תשנ\"ב ח, ב]. חלק העבודה פ\"א [סט, סע\"א]."],["1002","25","<b>ובפסיקתא</b>: ראה פסיקתא דר\"כ פסקא סליחות (פסקא כו) בשינויים."],["1003","26","<b>בילקוט האזינו</b>: לב, יח רמז תתקמה (צויין אליו בסה\"מ תרכ\"ז ע' קמ. תרל\"ח ע' מח. עזר\"ת ע' קצה]."],["1004","27","<b>שהעבודה צורך גבוה</b>: ראה עבודת הקודש בהקדמה. חלק העבודה פ\"א ואילך. סה\"מ תר\"ם ח\"ב ע' תשכב. וש\"נ. עבודת הקודש דבסמוך בפנים."],["1005","28","<b>במדרש תנחומא פ' שמיני</b>: סי' ז-ח. הובא בעבודת הקדש חלק העבודה פ\"ג ע\"פ אוה\"ת משפטים כאן ע' א'ריט.\nבעבודת הקדש שם מציין: במדרש ילמדנו. ראה מבוא לתנחומא באבער אותיות ב-ג."],["1006","29","<b>ובמדת\"ל </b> [ ובמדרש תהלים]<b> סי' י\"ח</b>: פסוק לא (אות כה).\n\n[ftn_8208_א])ששם שמים שגור בפי הכל: ראה גם מאמרי אדה\"א קונטרסים ע' קמב. וש\"נ. שע\"ת ח, ב ובהערה 24 . סה\"מ תרל\"ב ח\"ב ע' תלו. ע' תס. וש\"נ. תרל\"ח ע' שיז. תניא פי\"ח (ע' כד)."]]],[2001910148,"ובמד\"ר ויקרא פי\"ג<sup data-n=\"1007\">30</sup> וכי מאי איכפת לי' אם שוחט בהמה, או נוחר, ומסיים לא ניתנה מצות אלא לצרף בהם<sup data-n=\"1008\">31</sup> כו' משמע שאינם צורך גבוה. ואיתא בספר<sup data-n=\"1009\">32</sup> עבודת הקדש שמ\"ש ועבדתם קאי על למעלה<sup data-n=\"1010\">33</sup> שעבודה זו היא צורך גבוה כבי', והיינו שע\"י העבודה ממשיכים כח וגבורה<sup data-n=\"1011\">34</sup> בפשמ\"ע, וכמ\"ש צור ילדך תשי<sup data-n=\"1012\">35</sup> יו\"ד<sup data-n=\"1014\">37</sup> זעירא<sup data-n=\"1013\">36</sup>, שע\"י העדר העבודה ח\"ו מתישין כבי' כח וגבורה של מעלה, ולהיפך ע\"י העבודה מוסיפין כח וגבורה בפשמ\"ע, וכמ\"ש ועתה יגדל נא כח אד'<sup data-n=\"1015\">38</sup>, יו\"ד רבתי<sup data-n=\"1016\">39</sup>, וכמארז\"ל בפרק ט' דשבת ע\"פ ועתה יגדל נא, כלום יש עבד<sup data-n=\"1018\">41</sup> שנותן שלום לרבו כו' הי' לך לעזרני כו' מיד אמר ועתה יגדל נא הרי שהעבודה מוסיף כח למעלה, ע' בתולע\"י בהקדמה דף ה' ע\"א<sup data-n=\"1019\">42</sup> הביא מארז\"ל זה<sup data-n=\"1017\">40</sup>, וע\"פ הקבלה<sup data-n=\"1020\">43</sup> יו\"ד רבתי הוא בחי' חכמה סתימאה שבכתר, והיינו שע\"י העבודה של האדם למטה עי\"ז ממשיכים מבחי' ח\"ס שבכתר תוס' אור, ויו\"ד זעירא הוא רק בחי' חכמה תתאה<sup data-n=\"1021\">44</sup>, אבל בחי' העליונות שבאצי' אינם מאירים כו', נמצא שע\"י העבודה של האדם הוא נותן כח ועוז בגבורה של מעלה. ולכאו' אינו מובן זה איך שייך לומר שיהי' נצרך למעלה העבודה של האדם שהרי אנו רואים למטה שענין העבודה של העבד היינו שהוא משרת אותו שע\"י שירותו משלים לו חסרונו שחסר לו, אבל למעלה ידוע אנת הוא שלימותא דכולהו<sup data-n=\"1022\">45</sup>, וכלום חסר ח\"ו, וא\"כ איך שייך ענין העבודה למעלה שיהי' צורך גבוה כבי' כו', וגם מה תופס מקום העבודה שם, שהרי כתיב אם חטאת כו'",[["1007","30","<b>ובמד\"ר ויקרא פי\"ג</b>: סימן ג."],["1008","31","<b>וכי מאי . . אלא לצרף בהם</b>: ראה גם ב\"ר רפמ\"ד. סה\"מ תרל\"ח ע' מח ואילך. תר\"ם ח\"א ע' צג. וש\"נ."],["1009","32","<b>ואיתא בספר</b>: מכאן עד סוף הפיסקא ראה סה\"מ תרל\"ג ח\"ב כאן ע' תל (בשינוים והוספות)."],["1010","33","<b>בספר עבודת הקדש . . ועבדתם . . על למעלה</b>: חלק העבודה פט\"ו [קה, א]."],["1011","34","<b>כח וגבורה</b>: כ\"ה בילקוט שבהערה 26. אבל בפסיקתא שבהערה 25 כח בגבורה. ראה (הנסמן בהערות שם) אוה\"ת איוב כרך א ע' תרעט ואילך (מג\"א ע' ב'שצז ואילך. ובמהדורת תש\"נ ע' ריג ואילך). שלח ע' תסט. (ע' תעב. ע' תעט). סה\"מ תרל\"ג כאן ע' תל. תרכ\"ז ע' קלד. ע' קמ-קמא. תרל\"ח ע' לד. ע' מח. ע' רסג. ע' תעד. תר\"ם ח\"ב ע' תשא. תרס\"ב כאן ע' רעג. המשך תער\"ב ח\"ב ע' תתקיג. עזר\"ת ע' קצה. תש\"ט ע' 27 הב' [ושם: במד\"ר איכה . . וגבורה. באוה\"ת וכ\"ה לפנינו שם: בגבורה]."],["1012","35","<b>צור ילדך תשי</b>: האזינו לב, יח."],["1014","37","<b>יו\"ד זעירא . . יו\"ד רבתי</b>: ראה גם תו\"ח סנהדרין דמ\"ו בד\"ה קלני הועתק באוה\"ת איוב שם. הובא גם (ברשימות על איכה ע' 12 נדפס) באוה\"ת איכה כרך ב ע' א'מא."],["1013","36","<b>תשי יו\"ד זעירא</b>: מסורה קטנה האזינו שם. ראה אנציקלפדי' תלמודית חכ\"א מערכת יו\"ד ע' קלו הערה 80. אוה\"ת איוב שם. סה\"מ תרל\"ח ע' תעד."],["1015","38","<b>ועתה יגדל נא כח אד'</b>: שלח יד, יז."],["1016","39","<b>יגדל . . יו\"ד רבתי</b>: מסורה ריש בראשית. ראה אנציקלפדי' שם הערה 76. אוה\"ת איוב שם."],["1018","41","<b>בפרק ט' דשבת . . כלום יש עבד</b>: ראה שם פט, א."],["1019","42","<b>בתולע\"י . . ה' ע\"א</b>: הובא גם באוה\"ת משפטים ע' א'רמב. שלח ע' תעא."],["1017","40","<b>וכמארז\"ל . . מארז\"ל זה</b>: הוספה על סה\"מ תרל\"ג כאן."],["1020","43","<b>וע\"פ הקבלה</b>: וכ\"ה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 29. ראה גם אוה\"ת איוב שבהערה 34: ורבינו ז\"ל פי' יו\"ד רבתי דיגדל זהו מו\"ס. ובמג\"א שבהערה 34: יו\"ד דיגדל שהיא גדולה והיינו שהיא חכמה שבכתר מו\"ס ע' ביאור כי אתה נרי."],["1021","44","<b>תתאה</b>: בסה\"מ תרל\"ג כאן: שבמל'."],["1022","45","<b>אנת הוא שלימותא דכולהו</b>: ראה ת\"ז בהקדמה יז, ב."]]],[2001910149,"ורבו פשעיך מה תעשה לו<sup data-n=\"1023\">46</sup>, אם צדקת מה תתן לו<sup data-n=\"1024\">47</sup> ומה מידך יקח<sup data-n=\"1025\">48</sup>, וכמו שהקשה בלק\"ת בד\"ה לא הביט<sup data-n=\"1026\">49</sup>.\nב) <b>אך</b> הענין<sup data-n=\"1028\">51</sup> הוא דהנה במעשה המצות כתי' וצדקה תהי' לנו כי נשמר לעשות את כל המצוה (בפ' ואתחנן ס\"פ וא\"ו פסוק ך\"ה) שנקראו כל המצות בשם צדקה<sup data-n=\"1027\">50</sup>, ולכן האדם המקיים המצות נק' בשם צדיק<sup data-n=\"1029\">52</sup> שהוא פועל הצדקה של המצות שנקראו בשם צדקה. והנה ארז\"ל בפ\"ק דכתובות דף ה' סע\"א גדולים מעשה צדיקים<sup data-n=\"1030\">53</sup> יותר ממעשה שמים וארץ, דאילו במעשה שמים וארץ נאמר<sup data-n=\"1031\">54</sup> אף ידי<sup data-n=\"1032\">55</sup> יסדה וימיני<sup data-n=\"1033\">56</sup> טפחה שמים, משא\"כ במעשה צדיקים<sup data-n=\"1034\">57</sup> נא' מקדש אד' כוננו ידיך<sup data-n=\"1035\">58</sup> ב' ידות, וע\"ש בתוספת<sup data-n=\"1036\">59</sup>. והענין הוא דהנה בבריאת העולמות כתי' בראשית ברא אלקים<sup data-n=\"1037\">60</sup>, שבריאת העולמות נמשך רק מבחי' ש' אלקים שהרי לא נז' ש' הוי' בכל ששת ימי בראשית בכל העשרה מאמרות, רק שלאחר שבת אז נזכר שם הוי', כמ\"ש ביום עשות ה' אלקים<sup data-n=\"1038\">61</sup> ארץ ושמים, משא\"כ מתחלה לא נזכר ש' הוי' רק ש' אלקים לבד.\n<b>והנה</b> שרש ההפרש בין ש' הוי' לש' אלקים<sup data-n=\"1039\">62</sup>, ששם הוי' הוא בחי' שמו הגדול<sup data-n=\"1040\">63</sup>, וכמארז\"ל עד שלא נברה\"ע הי' הוא ושמו בלבד<sup data-n=\"1041\">64</sup>, שהוא בחי' שמו הגדול,",[["1023","46","<b>אם חטאת . . תעשה לו</b>: איוב לה, ו."],["1024","47","<b>אם צדקת מה תתן לו</b>: איוב שם, ז."],["1025","48","<b>ומה מידך יקח</b>: סיום הכתוב אם צדקת [ושם: או מה — ראה גם סה\"מ תרל\"ח ע' תיג. וש\"נ. תר\"ם ח\"א ע' שיב. וש\"נ]."],["1026","49","<b>בלק\"ת בד\"ה לא הביט</b>: בלק ע, ג. ראה גם מאמרי אדה\"א במדבר ח\"ד ע' א'תקיז ואילך. וש\"נ. סה\"מ תרכ\"ז ע' שלה. וש\"נ."],["1028","51","<b>וצדקה תהי' לנו. . כל המצות בשם צדקה</b>: ראה גם לקמן מאמר ד\"ה [נקדישך] וביאור הענין ובהערה 51."],["1027","50","<b>אך הענין . . בשם צדקה</b>: הוספה על סה\"מ תרל\"ג כאן."],["1029","52","<b>המקיים המצות . . צדיק</b>: ראה לקו\"ת מסעי צא, א. שה\"ש טז, ג. סה\"מ תרל\"ח ע' תז. וש\"נ."],["1030","53","<b>גדולים מעשה צדיקים</b>: ראה גם בסיום הפרק ובהנסמן שם.\nמכאן עד סיום הפרק נדפס גם בסה\"מ תרל\"ד ע' קד ואילך. ע' עדר ואילך (הנוסח כפי שמופיע בסה\"מ תרל\"ג כאן. וש\"נ)."],["1031","54","<b>נאמר</b>: בכתובות ובסה\"מ תרל\"ג: כתיב — וכ\"ה לקמן בפנים קרוב לסיום הפרק."],["1032","55","<b>אף ידי</b>: ישעי' מח, יג."],["1033","56","<b>יסדה וימיני</b>: וכ\"ה בסה\"מ תרס\"ב כאן ע' רעג. להלן קרוב לסיום הפרק: יסדה ארץ וימיני."],["1034","57","<b>משא\"כ במעשה צדיקים</b>: וכ\"ה בסה\"מ תרל\"ג ותרס\"ב כאן. בכתובות: ואילו במעשה ידיהם של צדיקים. ראה גם לקמן מאמר ד\"ה ראה קראתי בשם ובהערה 71."],["1035","58","<b>מקדש אד' כוננו ידיך</b>: בשלח טו, יז. [בכתובות שם מובאים גם התיבות: מכון לשבתך פעלת ה']."],["1036","59","<b>וע\"ש בתוספת</b>: ד\"ה דאילו. בסה\"מ תרל\"ג כאן ליתא."],["1037","60","<b>בראשית ברא אלקים</b>: בראשית א, א. ראה גם לקו\"ת שה\"ש לב, א. סידור שער התפלה כז, א. מאמרי אדה\"ז תקס\"ט ס\"ע לה ואילך. תו\"ח יתרו ח\"ב רסו, ב ואילך ובהנסמן שם. לקמן מאמר ד\"ה ראה קראתי בשם ספ\"ב ואילך."],["1038","61","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["1039","62","<b>ההפרש בין ש' הוי' לש' אלקים</b>: ראה לקו\"ת בלק עג, ד. עד, ב. תו\"ח וארא ח\"א עג, ב. וש\"נ."],["1040","63","<b>ששם הוי' . . שמו הגדול</b>: ראה תו\"א שמות נ, רע\"א. לקו\"ת פ' ראה נ, ב. אוה\"ת שמות ע' יא. כרך ז שמות ע' ב'תעט. ע' ב'תפג. סה\"מ תר\"ם ח\"א ע' רכו ובהנסמן שם."],["1041","64","<b>עד שלא . . ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."]]],[2001910150,"והוא בחי' סוכ\"ע שלמעלה מבחי' השתלשלות העולמות, וכנ\"ל שהי' קודם שנברה\"ע, ושם אלקים הוא בחי' ממכ\"ע<sup data-n=\"1042\">65</sup> שמתלבש בתוך העולמות, וזהו ג\"כ ענין מ\"ש וארא אל אברהם כו' ושמי הוי' לא נודעתי להם<sup data-n=\"1043\">66</sup>, כ\"א בש' שדי לפי ששם שדי הוא שאמר לעולמו די<sup data-n=\"1044\">67</sup>, כי העולמות נמשכו בבחי' גבול ומדה וכמו שארז\"ל מן הארץ לרקיע<sup data-n=\"1045\">68</sup> מהלך ת\"ק שנה כו', ואפי' עולמות עליונים ג\"כ הם בבחי' גבול ומדה, ואפי' ג\"ע הוא בבחי' גבול כי ג\"ע הוא השגה, וענין ההשגה הוא בחי' גבול כמובן.\n<b>והנה</b> כדי שיומשך העולמות שהם בבחי' גבול מאוא\"ס הבלתי בע\"ג בתכלית אין זה ע\"פ השתלשלות, כי אין ערוך כלל בחי' הגבול לגבי בחי' בלתי בע\"ג<sup data-n=\"1046\">69</sup>, ואינו בגדר וסוג כלל, שאפי' אחד במספר לגבי אלף אלפי' או ריבו רבבות, הגם שהם רחוקים מאד זה מזה בריחוק הערך בבחי' המספר, אעפ\"כ יש להם ערך וסוג קצת זה לזה, שהרי הוא חלק א' מאלף אלפי' או מריבו רבבות וה\"ה בגדר חשבון עכ\"פ והם מסוג אחד עכ\"פ, משא\"כ גבול לגבי בלתי בע\"ג אינו בערך כלל, ולגבי בחי' בלתי בע\"ג שוה מספר ריבו רבבין כמו מספר א' והיינו שגם מספר היותר גדול ג\"כ אינו בערך כלל, ולכן כדי שיתהוה התהוות העולמות שהם בע\"ג מאוא\"ס הבלתי בע\"ג זהו ע\"י שם אלקים דוקא, כי ש' אלקים הוא בחי' הצמצום<sup data-n=\"1047\">70</sup> שצמצם א\"ע כבי' שיהי' מקור לעולמות בע\"ג ומדה, וזהו שבכל ששת ימי בראשית לא נא' כ\"א שם אלקים לבד, משא\"כ ש' הוי' מורה על בחי' הי' הוה ויהי' כאחד<sup data-n=\"1048\">71</sup>, שהוא בחי' שמו הגדול, הנה מבחי' זה לא הי' יכול להיות התהוות העולמות בבחי' גבול, רק בשבת אחר שנאמר ויברך אלקים את יום השביעי ויקדש אותו<sup data-n=\"1049\">72</sup>, אז נא' שם הוי', כי בשבת הוא התגלות ש' הוי' וכמ\"ש שער החצר הפנימיות כו' סגור יהי'<sup data-n=\"1050\">73</sup> ששת ימי המעשה וביום השבת יפתח, ר\"ת ש' הוי'<sup data-n=\"1051\">74</sup>, לפי שבשבת הוא התגלות ש' הוי', והיינו לפי שבשבת הוא שביתה בחי' תענוג שחוזר למקורו, כי בששת ימי החול הוא בחי' ירידת",[["1042","65","<b>סוכ\"ע . . ממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["1043","66","<b>וארא . . לא נודעתי להם</b>: וארא ו, ג."],["1044","67","<b>שדי . . שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה על יד הערה 80."],["1045","68","<b>מן הארץ לרקיע</b>: ראה חגיגה יג, א. לקמן מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 23 ואילך."],["1046","69","<b>אין ערוך כלל בחי' הגבול . . בלתי בע\"ג</b>: ראה גם תניא פמ\"ח. לקו\"ת שה\"ש לח, ג. שערי אורה לא, א ובהערה 23. סה\"מ תר\"ם ח\"ב ע' תשכז. וש\"נ."],["1047","70","<b>אלקים . . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["1048","71","<b>הוי' . . הי' הוה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["1049","72","<b>ויברך אלקים . . ויקדש אותו</b>: בראשית ב, ג."],["1050","73","<b>שער החצר הפנימיות כו' סגור יהי'</b>: יחזקאל מו, א [ושם: הפנימית . . יהי' סגור].\nאבל כהלשון שבפנים ”סגור יהי'\" מובא בכ\"מ ומהם: לקו\"ת תצא לז, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתפ. וש\"נ. אוה\"ת יתרו ע' תשלז. ע' תשנג. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 50. סה\"מ תרכ\"ז ע' עה. תרל\"ג כאן ע' תלא. תרל\"ד כאן ע' קה וע' ערה. תר\"ם ח\"א ע' קלז. וש\"נ. תרס\"ב כאן ע' ערה. תרפ\"ז ע' קנה. תש\"ג ע' 63 (ושם: הפנימי)]."],["1051","74","<b>ימי המעשה . . יפתח ר\"ת ש' הוי'</b>: בסה\"מ (תרפ\"ז ו)תש\"ג שם: ימי המעשה וביום השבת ר\"ת הוי' כסדרו, או המעשה וביום השבת יפתח ר\"ת הוי' למפרע — שער הפסוקים להאריז\"ל ס\"פ פנחס. פע\"ח שער ר\"ח שי\"ט, פ\"ב. ראה גם אוה\"ת יחזקאל כרך א ע' תכו. לקמן שם. סה\"מ תרל\"ג־ תרל\"ד ותרס\"ב שבהערה שלפנ\"ז."]]],[2001910151,"והמשכת החכ' בבחי' דבור שנק' עשי' כו', משא\"כ בשבת הוא בחי' עליה למקורו שמאיר שם התגלות עצמותו כו', וזהו שפי' רש\"י ז\"ל ע\"פ ושמי הוי' לא נודעתי להם לא נכרתי להם במדת אמיתית שלי, והיינו כי שם הוי' בחי' ומדריגת אמת<sup data-n=\"1052\">75</sup> (הגם ששארי שמות הם ג\"כ אמת<sup data-n=\"1053\">76</sup> כמ\"ש במ\"א), שג' אותיות אמת<sup data-n=\"1054\">77</sup> הם אני ראשון ואני אחרון ומבלעדי<sup data-n=\"1055\">78</sup> כו', ולהאבות לא נתגלה עדיין בחי' אמיתית שם הוי' רק הגילוי הי' להם מבחי' שאר שמות כו', וזהו דכתי' יהללו את ש' הוי' כי הוא צוה ונבראו<sup data-n=\"1056\">79</sup>, ולא כתי' ברא והיינו כי ברא הוא לנוכח שהוא בחי' כח הפועל בנפעל<sup data-n=\"1057\">80</sup> ולכן בש' אלקים שהוא מדת הצמצום כנ\"ל נא' ברא היינו שנתלבש בעולמות בבחי' ממכ\"ע, משא\"כ אצל ש' הוי' נא' רק ונבראו לשון ממילא לפי שש' הוי' אינו מתלבש בעולמות רק בבחי' מקיף והעלם שהוא בחי' סוכ\"ע. ובזה יובן משארז\"ל גדולים מעשה הצדיקים<sup data-n=\"1058\">81</sup> העוסקים בתומ\"צ<sup data-n=\"1059\">82</sup> ממעשה שמים וארץ, דאילו במעשה שמו\"א כתי' אף ידי יסדה ארץ וימיני טפחה שמים שהארץ נברא ביד שמאל כמארז\"ל נטה ימינו וברא שמים<sup data-n=\"1060\">83</sup>, נטה שמאלו וברא ארץ, ולכן בארץ נעשה העלם והסתר גמור כו' ושמים שנברא בבחי' יד ימין שם מאיר אלקות בבחי' גילוי יותר, אך מ\"מ הגילוי שבשמים אינו מאיר בארץ, וכמ\"ש השמים שמים לה'<sup data-n=\"1061\">84</sup> והארץ נתן לבני אדם, לפי שכל אחד נברא ביד אחת אך במעשה הצדיקים נא' בהם מקדש אד' כוננו ידיך ב' ידות בחד מעשה, והיינו בחי' ההתחברות בחי' שמים וארץ וכמ\"ש כי כל בשמים ובארץ<sup data-n=\"1062\">85</sup>, דאחיד בשמי' ובארעא<sup data-n=\"1063\">86</sup>, והיינו כי בבהמ\"ק הי' מאיר גילוי אלקות למטה ממש, וכמ\"ש ועשו לי מקדש<sup data-n=\"1064\">87</sup> ושכנתי בתוכם שהי' מאיר גילוי שם הוי' למטה",[["1052","75","<b>שם הוי' . . אמת</b>: ראה גם לקמן [במאמר שנדפס לאח\"ז] פ\"ו. אוה\"ת ויחי כרך ז ע' 2544. ע' תתתעה."],["1053","76","<b>הגם ששארי שמות הם ג\"כ אמת</b>: ראה גם סה\"מ תר\"ל ע' סא. ע' סז. תרל\"ח ע' תלה."],["1054","77","<b>שג' אותיות אמת</b>: ב\"ר פפ\"א, ב. ראה גם יפ\"ת שם. סה\"מ תרכ\"ז ע' שטו."],["1055","78","<b>אני ראשון ואני אחרון ומבלעדי</b>: ישעי' מד, ו."],["1056","79","<b>יהללו . . צוה ונבראו</b>: תהלים קמח, ה. ראה תו\"א מג\"א צו, ג. לקו\"ת פ' ראה כ, סע\"ג ואילך. שה\"ש יד, ג. סה\"מ תרל\"ח ע' יב. וש\"נ. לקמן מאמר ד\"ה ראה קראתי בשם ספ\"ב ואילך. ד\"ה וירא ישראל את היד הגדולה פ\"א."],["1057","80","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["1058","81","<b>גדולים מעשה הצדיקים</b>: ראה להבא בסמוך סה\"מ תרל\"ג ח\"ב ע' שסה ואילך."],["1059","82","<b>העוסקים בתומ\"צ</b>: תיבות אלו הם הוספה על המארז\"ל המובא גם לעיל בריש הפרק."],["1060","83","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א וארא נו, ב בפנים. לעיל הערה 81."],["1061","84","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["1062","85","<b>כי כל בשמים ובארץ</b>: דברי הימים-א כט, יא."],["1063","86","<b>דאחיד בשמי' ובארעא</b>: ראה זהר בראשית לא, א. ראה גם סה\"מ תרל\"ח ע' עט. וש\"נ. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 164."],["1064","87","<b>ועשו לי מקדש</b>: תרומה כה, ח."]]],[2001910152,"וכמ\"ש והוי' בהיכל קדשו<sup data-n=\"1065\">88</sup> כו', ולכן גדולים מעשה צדיקים ממעשה שמים וארץ, לפי שמעשה שמים וארץ הוא בחי' העלם וע\"י מעשה צדיקים נמשך גילוי ש' הוי' למטה.\nג) <b>ובזה</b> יובן מ\"ש ועבדתם את הוי' אלקיכם, דלכאורה קשה איך שייך למעלה בחי' עבודה שהרי נא' אם צדקת מה תתן לו כנ\"ל, אך הענין הוא דבאמת לגבי עצמותו ומהותו אין שייך כלל לומר לשון עבודה שהרי אם צדקת כו', אך מה ששייך העבודה זהו דוקא בבחי' הוי' אלקיך שם שייך העבודה, דהיינו להמשיך את בחי' שם הוי', כי אע\"פ ששם הוי' הוא בחי' שמו הגדול בחי' סוכ\"ע שלמעלה מהשתלשלות, מ\"מ הוא רק בחי' שם לבד, והוא למעלה מהשתלשלות מבחי' העולמות שהם בבחי' גבול ממש, אבל לגבי עצמותו ומהותו ממש הוא רק בחי' שם לבד, וכדי שיומשך בחי' שם הוי' הוא ע\"י צמצום<sup data-n=\"1066\">89</sup>, וזהו ששם הוי' הוא מתחיל ביו\"ד שהוא בחי' צמצום*, וזהו ועבדתם את הוי' אלקיכם, דהיינו שע\"י העבודה ממשיכים שיתהוה בחי' ש' הוי' ואח\"כ אלקיכם דהיינו שיומשך מבחי' ש' הוי' בשם אלקים, עד שיהא נקרא הוי' אלקיכם, אלקיכם ממש, וזהו ג\"כ מ\"ש ואהבת את הוי' אלקיך<sup data-n=\"1067\">90</sup> שיהי' נק' הוי' אלקיך ממש**.\n<b>והנה</b> ע\"י מה ממשיכים שיהי' הוי' אלקיך או אלקיכם זהו ע\"י העבודה, וארז\"ל איזהו עבודה שבלב זו תפלה, והענין הוא דהנה תפלה הוא לשון התחברות, וכמשארז\"ל התופל כלי חרס<sup data-n=\"1068\">91</sup>, דהנה כתיב סולם מוצב ארצה וראשו מגיע השמימה<sup data-n=\"1069\">92</sup>, והיינו שענין הסולם הוא מחבר מעלה ומטה, ואיתא סולם דא צלותא<sup data-n=\"1070\">93</sup>\n\n)\n<i>נרשם בשולי היריעה ולא נסמן מקומו בפנים ואולי שייך כאן:</i>\nצמצם דיו\"ד י\"ל בכדי שיהי' הגילוי שיהי' ביטול היש וביטול אמיתי ומ\"מ צמצום זה דיו\"ד זהו כמו צמצם שכינתו[ftnref_8209_ב] בכדי שיוכל להיות הגילוי ואינו דומה לצמצום דש' אלקים שבברה\"ע שהוא בכדי שיהי' מציאות היש.\n**)<i>נרשם בשולי היריעה ולא נסמן מקומו בפנים ואולי שייך כאן:</i>\nהוי' אלקיך ממש י\"ל כמו במ\"ת אנכי הוי' אלקיך[ftnref_8210_ג] שמאנכי נמשך שהוי' יהי' אלקיך.",[["1065","88","<b>והוי' בהיכל קדשו</b>: חבקוק ב, כ."],["1066","89","<b>שיומשך בחי' שם הוי' . . צמצום</b>: ראה לקו\"ת שמע\"צ צב, ד. סה\"מ תרכ\"ט ע' קכו. וש\"נ."],["1067","90","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה. ראה תו\"א תצוה פב, רע\"ג. לקו\"ת שה\"ש מב, ב."],["1068","91","<b>תפלה . . התופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה פ\"א. וש\"נ."],["1069","92","<b>סולם מוצב ארצה . . השמימה</b>: ויצא כח, יב."],["1070","93","<b>סולם דא צלותא</b>: ראה זח\"א בהשמטות רסו, ב. ח\"ג תוספת שו, ב. ת\"ז תמ\"ה פג, א. סה\"מ תרל\"ח ע' מה. וש\"נ. תש\"ח ע' 80.\n\n[ftn_8209_ב]) צמצם שכינתו: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12.\n\n[ftn_8210_ג]) אנכי הוי' אלקיך: יתרו כ, ב.\nסדר כתיבת שתי הערות אלו הם: בשולי הגליון בצד הימיני של העמוד נרשמו בג' שורות קצרות (התיבות שעל יד הערה ב) ”צמצם . . אמיתי\", ואח\"כ רשם קו קצר באורך הע', והתחיל ממעל מתחלת השורה ורשם התיבות ”ומ\"מ . . היש\", ואח\"כ המשיך בהיפך הע' ממעל לשורות אלו ונרשמה ההערה ”הוי' אלקיך . . אלקיך\". בבוך תרמ\"א 2086 — כת\"י מעתיק — נרשמו שתי הערות אלו ביחד."]]],[2001910153,"שהתפלה היא מחבר מלמטה למעלה ולכן נק' התפלה בחי' סולם, דהנה כתי' ארוממך אלקי המלך<sup data-n=\"1071\">94</sup>, והיינו כי מתחלה צריך לרומם את בחי' אלקי המלך לעצמות אוא\"ס, וזהו ארוממך, ופי' אלקי המלך, אלקי הוא בחי' ומדריגת בראשית ברא אלקים, והמלך הוא בחי' מלכותך מלכות כל עולמים<sup data-n=\"1072\">95</sup> שפי' עולם שנעשה בחי' העלם<sup data-n=\"1073\">96</sup> והסתר, וכדי שיהי' המשכת בחי' גילוי אור א\"ס למטה צריך לרומם את בחי' המלכות מקור כל העולמות לעצמות אוא\"ס, והתרוממות זו נעשה ע\"י התפלה, וכמו והחיות נושאות את הכסא<sup data-n=\"1074\">97</sup> שחיות הקדש ע\"י עבודתם בבחי' ביטול ורוצים להכלל בעצמות אוא\"ס עי\"ז הם מנשאים את בחי' כסא שהוא בחי' מל' מקור העולמות, וכך ע\"י התפלה שכנגד תמידין תקנו<sup data-n=\"1075\">98</sup> שהוא להקריב את נה\"ב ששרשו ג\"כ מבחי' חיות הקדש<sup data-n=\"1076\">99</sup> ושמרי האופנים<sup data-n=\"1077\">100</sup>, הנה ע\"י הקרבה זו שהוא בחי' תפלה נעשה העלאת בחי' מל' מקור העולמות, וזהו ארוממך אלקי המלך. ועפ\"ז יובן ענין ועבדתם את הוי' היינו שתיבת את הוא בחי' אותיות שמאלף ועד תי\"ו<sup data-n=\"1078\">101</sup>, שהוא בחי' מלכות בחי' דבור<sup data-n=\"1079\">102</sup> דעשרה מאמרות שבהם נברה\"ע<sup data-n=\"1080\">103</sup>, וצריך לרומם את בחי' המל' לש' הוי' עד שיהי' בבחי' את הוי' ממש דהיינו טפל<sup data-n=\"1081\">104</sup> לש' הוי' וכמ\"ש יראו את הוי' קדושיו<sup data-n=\"1082\">105</sup>, דהנה כתיב יראו מהוי' כל הארץ<sup data-n=\"1083\">106</sup>, שמשמע כל הארץ, וכתי' יראו את הוי' קדושיו שמשמע שהוא רק קדושיו, והתירוץ ע\"ז הוא דמ\"ש יראו מהוי' כל הארץ זהו בחי' יר\"ת וע\"כ כתי' יראו מה', אך יראו את הוי' היינו יר\"ע<sup data-n=\"1084\">107</sup>, וזהו את הוי' שהוא טפל לשם הוי' ממש בבחי' ביטול במציאות וכמ\"ש את בשרו<sup data-n=\"1085\">108</sup> ודרשו רז\"ל את הטפל לבשרו<sup data-n=\"1086\">109</sup>, ועי\"ז נמשך אח\"כ בחי' ש' הוי' כו'.\n<b>והנה</b> כדי שיומשך בחי' ש' הוי' זהו בדרך כלל ע\"י בחי' ש' הוי' שבנפש האדם<sup data-n=\"1087\">110</sup>, וזהו שארז\"ל ועבדתם את ה' אלקיכם זו ק\"ש ותפלה, דהנה יו\"ד ה\"א הוא",[["1071","94","<b>ארוממך אלקי המלך</b>: תהלים קמה, א. ראה תו\"א מקץ מ, ג. מא, סע\"א ואילך."],["1072","95","<b>מלכותך מלכות כל עולמים</b>: תהלים שם, יג."],["1073","96","<b>עולם . . העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["1074","97","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["1075","98","<b>התפלה שכנגד תמידין תקנו</b>: ראה ברכות כו, ב. לקו\"ת פינחס עז, ג."],["1076","99","<b>נה\"ב ששרשו . . חיות הקדש</b>: ראה תו\"א וישב כט, סע\"ב. יתרו עא, סע\"א. לקו\"ת אמור לו, ב. נשא כח, ג."],["1077","100","<b>נה\"ב ששרשו . . ושמרי האופנים</b>: ראה לקו\"ת ויקרא ב, ב. האזינו עד, ג."],["1078","101","<b>את . . אותיות שמאלף ועד תי\"ו</b>: ראה זהר בראשית כט, ב. רקאנטי בראשית ב, א. לקו\"ת עקב טו, א. מאמרי אדה\"א שמות ח\"ב ע' שלז. וש\"נ."],["1079","102","<b>מלכות בחי' דבור</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["1080","103","<b>דעשרה מאמרות שבהם נברה\"ע</b>: אבות רפ\"ה."],["1081","104","<b>את . . טפל</b>: ראה בסמוך הערה 109."],["1082","105","<b>יראו את הוי' קדושיו</b>: תהלים לד, י."],["1083","106","<b>יראו מהוי' כל הארץ</b>: תהלים לג, ח."],["1084","107","<b>יראו מהוי' . . יר\"ת . . יראו את הוי' . . יר\"ע</b>: ראה לקו\"ת במדבר יג, ב. לקמן מאמר ד\"ה וירא ישראל את היד הגדולה פ\"א. וש\"נ."],["1085","108","<b>את בשרו</b>: משפטים כא, כח."],["1086","109","<b>את הטפל לבשרו</b>: ב\"ק מא, ב."],["1087","110","<b>ש' הוי' שבנפש האדם</b>: ראה גם בענין שם ה' שבנפש לקו\"ת פ' ראה יח, א. סה\"מ תר\"ם ח\"א ע' ט. וש\"נ."]]],[2001910154,"בחי' רצוא ושוב וז\"ע ק\"ש ותפלה, כי ק\"ש הוא בחי' רצוא<sup data-n=\"1088\">111</sup>, וכדאיתא אם רץ לבך<sup data-n=\"1089\">112</sup>, וז\"ע ואהבת את הוי' אלקיך שהוא בחי' אהבה בחי' רצוא, ותפלה הוא בחי' שוב<sup data-n=\"1090\">113</sup>, ברוך אתה הוי' שהוא בחי' המשכה<sup data-n=\"1091\">114</sup> למטה בחי' יר\"ע שהוא בחי' יו\"ד של ש' הוי', ואה\"ר שבק\"ש הוא בחי' ה' ראשונה של ש' הוי', והוא\"ו הוא בחי' תורה, הקל קול יעקב<sup data-n=\"1092\">115</sup> קלא קדמאה חסר וא\"ו שהוא קול תפלה, וקלא בתראה מלא וא\"ו שהוא קול תורה, כי תורה היא וא\"ו של ש' הוי'<sup data-n=\"1095\">*117</sup>, שיתא סדרי משנה<sup data-n=\"1094\">116</sup> בחי' מדות<sup data-n=\"1093\">*116</sup> כשר פסול כו', וה' אחרונה הוא בחי' דבור של תורה, וע\"י ד' בחי' אלו עי\"ז ממשיכים בחי' ש' הוי', והיינו כי הגם ששם הוי' נמשך מתחלה בבריאות העולמות<sup data-n=\"1096\">117</sup> אחר שבת כו', אך מ\"מ בגלותא דמצרים קודב\"ה סליק לעילא ולעילא<sup data-n=\"1097\">118</sup>, וצריך להמשיך את בחי' ש' הוי' כו'. וזהו ועבדתם את הוי' שע\"י העבודה יומשך ש' הוי', ואח\"כ אלקיכם שהוא המשכה למטה עד שיהי' נק' אלקיכם, ויהי' התחברות ש' הוי' בשם אלקים, וזהו ע\"י מעשה המצות, כי הנה כתי' (ישעי' נ\"ט ב) עונותיכם היו מבדילים<sup data-n=\"1098\">119</sup> ביניכם לבין אלקיכם, שע\"י העון נעשה מסך מבדיל כו' שלא יהי' מאיר גילוי אלקות למטה, אך ע\"י המצות נעשה אלקיכם ממש ואין דבר מפסיק בנינו לבין אבינו שבשמים, נמצא שע\"י ק\"ש ותפלה ותורה עי\"ז ממשיכים את ש' הוי', וע\"י המצות נמשך מבחי' ש' הוי' בשם אלקים כו'.\nד) <b>וענין</b> ועבדתם את ה' אלקיכם עפה\"ק<sup data-n=\"1099\">120</sup>, היינו להמשיך בחי' מוחין לז\"א וט\"ס לנוק', דהנה בסוד שרש לא נאצלו ז\"א רק ששה מדות<sup data-n=\"1100\">121</sup>, ומל' נאצלה רק",[["1088","111","<b>ק\"ש . . רצוא</b>: ראה תו\"א בראשית א, ד. לקו\"ת שה\"ש מז, א. שער האמונה עז, ב. מאמרי אדה\"א שמות ח\"ב ס\"ע שכח ואילך. וש\"נ."],["1089","112","<b>אם רץ לבך</b>: ס\"י פ\"א, מ\"ח."],["1090","113","<b>ותפלה . . שוב</b>: ראה תו\"א. לקו\"ת. שה\"א. הנסמן במאמרי אדה\"א שבהערה 111."],["1091","114","<b>ברוך . . המשכה</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' רפ\"ג. וש\"נ."],["1092","115","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. מאמרי אדה\"א בראשית ע' שמח. וש\"נ. תו\"ח מקץ רכז, ב ובהערות 32-4. וראה גם לקמן מאמר ד\"ה וידבר כו' קדושים תהיו ובהערות 171-172."],["1095","*117","<b>שיתא סדרי משנה בחי' מדות</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 87."],["1094","116","<b>שיתא סדרי משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. לקו\"ש בשלח כרך יא ע' 56 הערה 13."],["1093","*116","<b>תורה היא וא\"ו של ש' הוי'</b>: ראה גם זהר רע\"מ תצא רעח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע קס ואילך. ש\"א נא, ב ובהערה 33. סה\"מ תר\"ם ח\"א ע' קמב ובהערה לשם. לקמן שם על יד הערה 170."],["1096","117","<b>בבריאות העולמות</b>: ראה גם תניא פכ\"א כז, א ובליקוטי לוי יצחק שם.\nבסה\"מ תרל\"ג כאן ס\"ע תלג: בבריאת העולמות. וראה גם לקמן מאמר ד\"ה מגילה נקראת ובהערה 163. ד\"ה להבין וכו' בענין הציץ ובהערה 78. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר משה ובהערה 90."],["1097","118","<b>קודב\"ה סליק לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א קונטרסים ע' שסג. וש\"נ. תו\"ח שמות ח\"א לט, סע\"א ואילך ובהערה 72. סה\"מ תר\"ם ח\"א ע' שיב. וש\"נ."],["1098","119","<b>עונותיכם היו מבדילים</b>: ראה גם לעיל מאמר ד\"ה והי' אור הלבנה פ\"ב."],["1099","120","<b>עפה\"ק</b>: ע\"פ הקבלה."],["1100","121","<b>ז\"א רק ששה מדות</b>: ראה ע\"ח שער המלכים שי\"א, פ\"ה. שער המוחין ש\"כ, פ\"א. שער מיעוט הירח של\"ו, פ\"א."]]],[2001910155,"בבחי' נקודה<sup data-n=\"1101\">122</sup> כו', וזהו מ\"ש ויהיו חיי שרה<sup data-n=\"1102\">123</sup> מאה שנה ועשרים שנה ושבע שנים, והיינו כי עשרים קאי על חו\"ב שנאצלו בע\"ס שלימים, משא\"כ זו\"נ הוא רק שבע שנים, וצריך להמשיך מוחין לז\"א וט\"ס לנוק'. והיינו כי כדי שיומשך למטה צריך שיומשך דוקא מבחי' מוחין, כי קטן אינו מוליד<sup data-n=\"1103\">124</sup> והוא מפני שלא נגמר עדיין המוחין שלו בשלימות וע\"כ אינו יכול להוליד, וכך כדי שיומשך למטה צריך שיומשך מבחי' מוחין עליונים. וזהו ועבדתם את הוי' היינו המשכת ש' הוי' לז\"א שהוא בחי' המשכת מוחין, וזהו מה שארז\"ל הקב\"ה מניח תפילין<sup data-n=\"1104\">125</sup>, כי הקב\"ה הוא בחי' ז\"א<sup data-n=\"1105\">126</sup>, ומניח תפילין הוא המשכת מוחין לז\"א, כי תפילין הוא ד' מוחין<sup data-n=\"1106\">127</sup>, ואח\"כ נמשך בחי' אלקיכם דהיינו ט\"ס לנוק' שיבנה בבחי' פרצוף שלם, ואז יכול להיות הגילוי למטה ממש עד שיהי' נק' אלקיכם, לפי שכשהוא רק בבחי' נקודה לבד אזי אינו יכול להיות בבחי' גילוי למטה, רק כשנבנה בבחי' פרצוף שלם יכול להיות נמשך למטה ג\"כ כו'.\n<b>וענין</b> ההפרש שבין ש' הוי' לש' אלקים עפה\"ק, ז\"ע ההפרש שבין אורות לכלים, דהנה ש' הוי' נק' ש' העצם<sup data-n=\"1107\">128</sup>, דהיינו בחי' אורות המאיר בכלים דאצי', ושארי שמות הם רק בחי' כלים<sup data-n=\"1108\">129</sup> כמו ש' אל בחסד<sup data-n=\"1109\">130</sup> וש' אלקים בגבורה<sup data-n=\"1110\">131</sup> שהוא רק בחי' כלי החסד וכלי הגבורה, והנה כלים הם מגבילים את האור<sup data-n=\"1111\">132</sup>, והיינו שהם בבחי' גבול ממש לפ\"ד הע\"ח<sup data-n=\"1112\">133</sup>, וכמ\"ש בפרקי היכלות שיעור קומה של יוצר בראשית רל\"ו אלפים רבו רבבות פרסאות<sup data-n=\"1113\">134</sup> (ע' במק\"מ פ' בשלח<sup data-n=\"1114\">135</sup>) שהוא בחי' גבול וקאי על בחי' כלים דאצילות, ואפי' לדעת הפרד\"ס<sup data-n=\"1115\">136</sup> שהכלים הם למעלה מבחי'",[["1101","122","<b>ומל' . . נקודה</b>: ראה ע\"ח שער המלכים שם. שער מיעוט הירח שם, פ\"א. פ\"ב. לקו\"ת צו יא, ב."],["1102","123","<b>ויהיו חיי שרה</b>: ח\"ש כג, א. ראה זהר שם קכג, א. ביאוה\"ז ח\"ש קלא, ב ואילך."],["1103","124","<b>קטן אינו מוליד</b>: ראה סנהדרין סח, ב ואילך. סה\"מ תר\"ם ח\"א ע' קסז. וש\"נ."],["1104","125","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 126."],["1105","126","<b>הקב\"ה הוא בחי' ז\"א</b>: ראה ע\"ח שער הכללים פי\"ב. לקוטי הש\"ס להאריז\"ל ברכות ו, א (ה, א בדפי הספר)."],["1106","127","<b>תפילין הוא ד' מוחין</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 127."],["1107","128","<b>ש' הוי' נק' ש' העצם</b>: ראה כ\"מ לרמב\"ם הל' ע\"ז פ\"ב, ה\"ז. פרדס שער שם בן ד' שי\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכו."],["1108","129","<b>ש' הוי' . . אורות . . ושארי שמות . . כלים</b>: ראה תו\"א בא ס, א. תו\"ח בא ח\"א קיג, ב ואילך. סה\"מ תרמ\"ג ע' עה ואילך."],["1109","130","<b>ש' אל בחסד</b>: ראה זהר אחרי סה, א. תו\"ח נח סד, ג הערה 39."],["1110","131","<b>וש' אלקים בגבורה</b>: ראה זהר יתרו פג, ב. הנסמן בתו\"ח שם הערה 41."],["1111","132","<b>כלים הם מגבילים את האור</b>: ראה תו\"א בראשית ג, א. לקו\"ת אחרי כח, ג. ביאוה\"ז בשלח מ, א. בלק ק, ב."],["1112","133","<b>כלים . . גבול . . הע\"ח</b>: ראה שם שער דרושי אבי\"ע שמ\"ב, פ\"ב. סה\"מ תר\"ם ח\"ב ע' תרמח ובהנסמן שם."],["1113","134","<b>בפרקי היכלות רל\"ו אלפים רבו רבבות פרסאות</b>: ראה גם לקמן מאמר ד\"ה להבין וכו' בענין הציץ פ\"א. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן בסופה. סה\"מ תרל\"ח ע' ז ובהערות שם."],["1114","135","<b>במק\"מ פ' בשלח</b>: בסה\"מ שם מציין נו, ב."],["1115","136","<b>הפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."]]],[2001910156,"גבול<sup data-n=\"1116\">137</sup> אעפ\"כ הם מקור לגבול שמהם יכול להיות נמשך בבחי' גבול ומדה כו', אבל אורות הם למעלה מבחי' גדר גבול כלל, וז\"ע ש' הוי' שהוא למעלה מבחי' גדר גבול לפי שהוא בחי' אור כו', ומ\"ש במ\"א שש' הוי' הוא בת\"ת<sup data-n=\"1117\">138</sup>, היינו שבת\"ת אפי' הכלי הוא ג\"כ בחי' ש' הוי'<sup data-n=\"1118\">139</sup>, לפי שת\"ת הוא מחבר חו\"ג<sup data-n=\"1119\">140</sup>, וכדי שיוכל לחבר חו\"ג נמשך מלמעלה מב' הבחי' ששרשו מבחי' כתר כו', וע\"כ הכלי של הת\"ת הוא ג\"כ בחי' ש' הוי' כו', וזהו שש' הוי' נק' ש' העצם לפי שהוא בחי' האור כו' וע\"כ הוא מצטרף עם כל השמות כמו ה' אלקים ה' צבאות<sup data-n=\"1120\">141</sup> וכדומה והיינו לפי שהוא בחי' האור כו'.",[["1116","137","<b>הפרד\"ס שהכלים הם למעלה מבחי' גבול</b>: באוה\"ת בהר כרך ג ע' תתפו כותב: בפרדס שער עצמות וכלים פ\"ב שדעת הרדב\"ז בספר מגן דוד שהספירות הם עצם אלקות. והוא [הפרדס] ז\"ל כתב בפר\"ז [ראה אוה\"ת על ענינים ע' רסז: פ\"ד]. שהספירות הם עצמות וכלים, וא\"כ לדבריו הכלים הם . . בחי' גבול. ראה גם הנסמן בסה\"מ תרל\"ג ח\"ב כאן ס\"ע תלד ואילך. ולהעיר מסה\"מ תרמ\"ג ע' קיח ואילך.\nולהעיר שהובא באוה\"ת דלעיל ”דעת הרדב\"ז בספר מגן דוד\" ובאוה\"ת על ענינים ע' רסו כותב ע\"ז: ”ולא מצאתי זה עדיין במג\"ד\".\nויש לציין שבפרדס שם כתב בשם ר' דוד בספר מגן דוד. וכבר העירו שהכוונה לר' דוד וספר מגן דוד אחר."],["1117","138","<b>שש' הוי' הוא בת\"ת</b>: ראה זהר ויקרא יא, א. ע\"ח שער השמות שער מ\"ד, פ\"ג. פ\"ו. סידור שער המועדים ריז, ג. תו\"ח בראשית מא, א הערה 7."],["1118","139","<b>שבת\"ת אפי' הכלי . . ש' הוי'</b>: ראה תו\"א נח י, סע\"ב ואילך. תו\"ח נח סד, ג ואילך. הנסמן במאמרי אדה\"א בראשית ע' תשפד."],["1119","140","<b>שת\"ת הוא מחבר חו\"ג</b>: ראה גם לקו\"ת תזריע כג, ג. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 49. סה\"מ תר\"ם ח\"א ע' רלא-רלג."],["1120","141","<b>ה' צבאות</b>: שמו\"א א, יא."]]],[2001910157,"<h3>ובירך את לחמך</h3>\n<b>תרומה</b>\nה) <b>ובירך</b> את לחמך<sup data-n=\"1121\">1</sup> ואת מימיך<sup data-n=\"1122\">2</sup>, לחם קאי על התורה<sup data-n=\"1123\">3</sup>, דהנה כתי' לכו לחמו בלחמי<sup data-n=\"1124\">4</sup> שהתורה נק' לחם למטה לנפש האדם וכמ\"ש ותורתך בתוך מעי<sup data-n=\"1125\">5</sup>, וגם נק' לחם למעלה ג\"כ כמ\"ש בלחמי, ולכאו' אינו מובן איך שייך לומר",[["1121","1","<b>ובירך את לחמך</b>: מאמר זה הוא המשך למאמר ד\"ה ועבדתם את הוי' אלקיכם שנדפס לפנ\"ז ששניהם הם מאמר ד\"ה והי' עקב תרל\"ג (בהוספות וכו') שנדפס בסה\"מ תרל\"ג ח\"ב ס\"ע תלה ואילך. וראה הנסמן שם בריש המאמר ע' תכט.\nמאמר זה והקודמו מאמר ד\"ה ועבדתם את ה\"א נעתקו במאמר ד\"ה ועבדתם בסה\"מ תרס\"ב ע' רפ ואילך עם הוספות וכו'.\nהמאמר נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש. הכותרת נכתבה בצד הימני של העמוד באותה שורה ששם מתחיל המאמר. מזה משמע שהכותרת ניתוספה לאח\"ז. בבוך תרמ\"א 2086 — כת\"י מעתיק — הכותרת: פ' תרומה.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו."],["1122","2","<b>ובירך את לחמך ואת מימיך</b>: משפטים כג, כה."],["1123","3","<b>לחם . . התורה</b>: ראה שבת קכ, א. לקו\"ש בהעלותך כרך ד ע' 1038 הערה 26. תניא פ\"ה ובמ\"מ הגהות והע\"ק לשם. סה\"מ תרכ\"ז ע' קמט. וש\"נ. תרל\"ג ח\"ב כאן ע' תלה. וש\"נ."],["1124","4","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה זח\"א בהשמטות רס, א."],["1125","5","<b>ותורתך בתוך מעי</b>: תהלים מ, ט. ראה תניא שם."]]],[2001910158,"שהתורה היא בחי' לחם למעלה, בשלמא לנפש האדם שייך לומר לשון לחם שהתורה מחי' את נפש האדם, אבל למעלה איך שייך לומר בחי' לחם כו', אך הענין הוא דהנה ענין הלחם הוא שמחבר הנפש עם הגוף, ובלעדו הי' נפרד הנפש מן הגוף, והלחם הוא מחבר אותם, והנה איתא בזהר איהו וחיוהי חד, איהו וגרמוהי חד<sup data-n=\"1126\">6</sup>, פי' גרמוהי הם בחי' כלים<sup data-n=\"1127\">7</sup> שהוא בחי' מדות דאצי' לך הוי' הגדולה והגבורה<sup data-n=\"1128\">8</sup> כו', וכדי שיהי' בחי' איהו וגרמוהי חד היינו שיומשך המשכת אוא\"ס במדות, שבאמת אין ערוך אליך כלל, וכמ\"ש בת\"ז כולא לאחזאה איך מתנהג עלמא, אבל לאו דאית לך כו' ולא מכל אינון מדות כלל<sup data-n=\"1129\">9</sup>, ולכן כדי שיהי' איהו וגרמוהי חד, זהו ע\"י בחי' איהו וחיוהי חד שהוא בחי' חכמה, כי חכמה נק' חיוהי ע\"ש והחכמה תחי'<sup data-n=\"1130\">10</sup>, ובחכמה שורה אוא\"ס<sup data-n=\"1131\">11</sup>, כי ראשית הגילוי הוא בחכמה, ואורייתא מחכמה עילאה נפקת<sup data-n=\"1132\">12</sup> ע\"כ התורה מחבר המשכת אוא\"ס בבחי' מדות ג\"כ, כי אורייתא וקוב\"ה כולא חד<sup data-n=\"1133\">13</sup>, והתורה נמשכה בבחי' מדות כשר פסול כו', ועי\"ז התורה מחבר אוא\"ס בבחי' מדות, וכן יובן מענין הנדרים שהם בבינה<sup data-n=\"1134\">14</sup> שארז\"ל כל הנודר כאילו נודר בחיי המ'<sup data-n=\"1135\">15</sup>, והיינו כי מ' הוא בחי' ז\"א<sup data-n=\"1136\">16</sup> דאצי' וחיי המ' הוא בחי' בינה<sup data-n=\"1137\">17</sup> שנק' ג\"כ איהו וחיוהי חד<sup data-n=\"1138\">18</sup> כי חו\"ב הם תרין ריעין דלא מתפרשין<sup data-n=\"1139\">19</sup>,",[["1126","6","<b>איהו וחיוהי . . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. סה\"מ תר\"ם ח\"א ע' מג. וש\"נ."],["1127","7","<b>גרמוהי . . כלים</b>: ראה סה\"מ תרמ\"ג ע' עז: ”כן פי' בע\"ח ובאגה\"ק ד\"ה איהו וחיוהי\" רס\"כ. סה\"מ תר\"ם שם. וש\"נ."],["1128","8","<b>לך הוי' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["1129","9","<b>כולא לאחזאה . . מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."],["1130","10","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם רקאנטי פ' מטות (פ, ג). (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 13. (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר על יד הערה 15. מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. תו\"ח שמות ח\"א ב, ב הערה 84. סה\"מ תרל\"ח ע' נג. וש\"נ. סה\"מ תר\"ם ח\"א ע' קלה. וש\"נ]."],["1131","11","<b>ובחכמה שורה אוא\"ס</b>: ראה תניא פי\"ח. פל\"ה בהג\"ה [ראה במ\"מ הגהות והע\"ק לפי\"ח. ופל\"ה]. אגה\"ק ס\"כ קל, ב. לקו\"ת במדבר יד, ב [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" (ולפנינו הוא פ\"ב) ”ושער ב' במה\"ב פ\"א פ\"ג\" — ולפנינו הוא בשער סדר אצי' ש\"ג]. תו\"ח שמות ח\"א ז, ד הערה 333. סה\"מ תרנ\"ח ע' יב."],["1132","12","<b>ואורייתא מחכמה עילאה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1133","13","<b>אורייתא וקוב\"ה כולא חד</b>: מובא בתניא (פ\"ד ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["1134","14","<b>הנדרים שהם בבינה</b>: ראה רמב\"ן מטות ל, ג בסופו: בתבונה. רקאנטי מטות ל, ג (פ, ג). פרדס שערה\"כ שכ\"ג, פי\"ד מערכת נדר. שער ההקדמות סוד השבועות והנדרים וליל יוה\"כ (קעט, ב). שער רוח הקדש תיקון ו. טעהמ\"צ פ' מטות. ע\"ח שער הכללים פ\"ז. מאו\"א מערכת נדר אות ט וביאיר נתיב שם.\nבסהמ\"צ להצ\"צ מב, סע\"ב מציין: ”ובטעמי המצות\" [פ' מטות הנ\"ל] . . ”ובסוף שער היחודים ותיקון עונות באורך\" (ראה שם פ\"ח. והוא נוסח אחר משער רוה\"ק הנ\"ל)."],["1135","15","<b>כל הנודר . . בחיי המ'</b>: ראה זהר רע\"מ פינחס רנה, סע\"א. ספרי מטות ל, ג."],["1136","16","<b>מ' . . ז\"א</b>: ראה רקאנטי ופרדס שם: ת\"ת. שער רוח הקדש שם (קרוב לסופו). לעיל מאמר ד\"ה אז ישיר ובהערה 82."],["1137","17","<b>וחיי המ' . . בינה</b>: ראה בהנסמן לעיל הערה 14."],["1138","18","<b>בינה . . איהו וחיוהי חד</b>: ראה גם (סה\"מ תש\"ח) הנסמן בסה\"מ תרל\"ח המצויין בסמוך בהערה 20."],["1139","19","<b>חו\"ב . . תרין ריעין דלא מתפרשין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."]]],[2001910159,"והמוחין נק' חיוהי<sup data-n=\"1140\">20</sup>, וזהו עד\"מ כמו שאנו רואים למטה שהמוח הוא ממוצע ומחבר את הנפש עם הגוף שמתחלה מתלבש הנפש במוח, ואח\"כ מהמוח מתפשט החיות לכל האברים, וכך התורה הוא מחבר את המשכת אוא\"ס במדות כי התורה היא מוחין אורייתא מחכ' נפקת כו' וזהו נק' לחם למעלה כי כמו שהלחם הוא מחבר הנפש עם הגוף כך התורה היא מחבר אוא\"ס בבחי' מדות כו', וגם למטה לנפש האדם הוא ג\"כ בחי' לחם, והיינו שיהי' התקשרות והתחברות נה\"א לאלקות, זהו ג\"כ ע\"י התורה, כי תלת קשרין<sup data-n=\"1141\">21</sup> מתקשראן דא בדא, ישראל מתקשראין באורייתא ואורייתא בקוב\"ה, נמצא שע\"י התורה דוקא מתקשראין נש\"י לאלקות, וע\"כ נק' לחם לנפש כו', ועוד זאת שגם לנה\"ב הוא ג\"כ בחי' לחם, והיינו שהתורה מחבר גם הנה\"ב לאלקות, וכמ\"ש (משלי ך\"ה ך\"א) אם רעב שנאך האכילהו לחם, מלחמה של תורה<sup data-n=\"1142\">22</sup>, ושונאיך הוא בחי' היצה\"ר שנק' שונא<sup data-n=\"1143\">23</sup>, וע\"י לחמה של תורה, או מלחמתה של תורה כמ\"ש רש\"י בסוכה דנ\"ב ע\"א הטרחהו במלחמתה של תורה, ועי\"ז וה' ישלם לך (משלי ך\"ה ך\"ב) שארז\"ל א\"ת ישלם לך<sup data-n=\"1144\">24</sup> אלא ישלימנו לך שגם היצה\"ר ישוב לעבודת ה' כו'.\nוא\"ו) <b>והנה</b> לחם זה צריך לברכה, וזהו ובירך את לחמך, והענין הוא דהנה כתי' (ירמי' ט' י\"א) מי האיש החכם ויבן את זאת על מה<sup data-n=\"1145\">25</sup> אבדה הארץ, וארז\"ל נדרים דף פ\"א<sup data-n=\"1146\">26</sup> דבר זה נשאל לחכמים ולנביאים ולא פירשוהו עד שפירשה<sup data-n=\"1147\">27</sup> הקב\"ה בעצמו דכתיב ויאמר ה' על עזבם את תורתי (שם י\"ב) וא\"ר<sup data-n=\"1148\">28</sup> יהודא אמר רב שאין מברכין בתורה תחלה, דאם כפשוטו שלא למדו תורה, א\"כ למה לא הבינו, אלא ודאי שעסקו בתורה אלא שלא ברכו בתורה, ולכן לא פירשוהו, וכן פי' הרי\"ו זצ\"ל<sup data-n=\"1149\">29</sup>, ע' בר\"ן שם, ולכאו' אינו מובן איך ע\"י חטא קל כזה שלא ברכו בתורה יאבד הארץ<sup data-n=\"1150\">30</sup>. אך הענין הוא דהנה התורה נק' זאת וכמ\"ש זאת חקת התורה<sup data-n=\"1151\">31</sup> ות\"א דא גזירת אורייתא, וכן ארז\"ל במנחות יבא זה ויקבל זאת מזה<sup data-n=\"1152\">32</sup> כו', נמצא שהתורה נק' זאת, וכתי' וזאת<sup data-n=\"1153\">33</sup> התורה אשר שם משה<sup data-n=\"1154\">34</sup>, וכן וזאת המצוה<sup data-n=\"1155\">35</sup>",[["1140","20","<b>והמוחין נק' חיוהי</b>: ראה גם סה\"מ תרל\"ח ע' יד. וש\"נ. תר\"ם ח\"א ע' תכד. וש\"נ."],["1141","21","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צט. קונטרסים ע' שלט."],["1142","22","<b>מלחמה של תורה</b>: רש\"י משלי שם."],["1143","23","<b>ושונאיך . . היצה\"ר שנק' שונא</b>: סוכה נב, א (המצויין בסמוך בפנים)."],["1144","24","<b>אל תקרי ישלם לך</b>: סוכה שם."],["1145","25","<b>זאת על מה</b>: בירמי' שם: זאת . . על מה. [אבל כ\"ה גם בהקדמת מהר\"ל לתפארת ישראל ע' ב. אוה\"ת ואתחנן דלהלן].\nלהבא להלן ראה גם אוה\"ת ואתחנן ס\"ע רנב ואילך. הנסמן בסה\"מ תרל\"ג ח\"ב כאן ע' תלו."],["1146","26","<b>נדרים דף פ\"א</b>: ע\"א. ראה שם."],["1147","27","<b>שפירשה</b>: שם: שפירשו."],["1148","28","<b>תורתי (שם יב) וא\"ר</b>: שם: תורתי . . אמר ר'."],["1149","29","<b>הרי\"ו זצ\"ל</b>: הובא בר\"ן נדרים שם [ושם: ה\"ר יונה ז\"ל. תיבות: זצ\"ל — מובא גם בסה\"מ תרל\"ג ותרס\"ב כאן]."],["1150","30","<b>ע\"י חטא קל כזה . . יאבד הארץ</b>: ראה גם פי' הרי\"ף לע\"י נדרים שם."],["1151","31","<b>זאת חקת התורה</b>: חוקת יט, ב."],["1152","32","<b>יבא זה ויקבל זאת מזה</b>: מנחות נג, ב."],["1153","33","<b>שהתורה נק' זאת . . וזאת</b>: ראה גם הנסמן בסה\"מ תרל\"ג כאן ע' תלז."],["1154","34","<b>וזאת התורה אשר שם משה</b>: ואתחנן ד, מד."],["1155","35","<b>וזאת המצוה</b>: ואתחנן ו, א."]]],[2001910160,"כו' שניתוסף אות וא\"ו על תיבת זאת, ונודע כי וא\"ו הוא המשכה גבוה מאד, וכמ\"ש בזהר ונתתם לי אות אמת<sup data-n=\"1156\">36</sup> דא אות וא\"ו, והיינו שהוא\"ו הוא המשכה מבחי' אמת שהוא אני ראשון ואני אחרון<sup data-n=\"1157\">37</sup> כו' שהוא בחי' ש' הוי' שנק' אמת כנ\"ל<sup data-n=\"1158\">38</sup>, וכמ\"ש ואמת הוי'<sup data-n=\"1159\">39</sup>. והנה כתי' פיה פתחה בחכמה ותורת חסד על לשונה<sup data-n=\"1160\">40</sup> ופריך בגמ' וכי יש תורה של חסד<sup data-n=\"1161\">41</sup> ותורה שאינה של חסד, ומשני כאן כשלומד לשמה היינו לשם התורה<sup data-n=\"1162\">42</sup> שז\"ע להמשיך אוא\"ס בתורה אז נק' תורת חסד, וכמ\"ש כי אם ה' החסד<sup data-n=\"1163\">43</sup>, וכשנמשך המשכה מבחי' ש' הוי' בתורה נק' תורת חסד, ואז נק' וזאת התורה שנמשך בה המשכת בחי' וא\"ו אות אמת, וזהו כשלומד לשמה, משא\"כ כשאינו לומד לשמה אז נק' זאת לבד ות\"א דא גזירת אורייתא שנק' גזירות ודינין<sup data-n=\"1164\">44</sup> כו'. וזהו מי האיש החכם ויבן את זאת, כשהתורה היא בבחי' זאת בלא וא\"ו שז\"ע גזירות ודינין, שעי\"ז אבדה הארץ והוא על שלא ברכו בתורה תחלה שלא המשיכו המשכת אוא\"ס בתורה, שזהו הגרם שאבדה הארץ, והיינו שלא מחמת חטא זה בלבד נאבד הארץ, רק זהו הגורם שנאבדה מחמת שאר עוונות שאם היו ברכו בתורה אזי לא הי' נאבדה וכמארז\"ל וויתר הקב\"ה על עכומ\"ז ועל ג\"ע ועל ש\"ד ולא וויתר על ביטול תורה<sup data-n=\"1165\">45</sup>, והיינו לפי שע\"י התורה הי' נתקן גם החטאים אלו הגדולים וכמשארז\"ל המאור שבה מחזירן למוטב<sup data-n=\"1166\">46</sup> כו', ולכן אם היו ממשיכים בתורה מבחי' ש' הוי' היו נמתקים הדינים ע\"י החסדים של ש' הוי', אבל כשלא המשיכו בתורה אז עי\"ז אבדה הארץ שנתגבר בה תוקף הדין של אורייתא, כי שאלו לחכמה<sup data-n=\"1167\">47</sup> חוטא מה עונשו א\"ל חטאים תרדף רעה<sup data-n=\"1168\">48</sup>, וזהו כשלא המשיכו בתורה, אבל אם היו",[["1156","36","<b>ונתתם לי אות אמת</b>: יהושע ב, יב. זהר ויקרא ב, א. ויחי רמא, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' ח ואילך. ביאורי הזהר להצ\"צ כרך א ע' שיג ואילך."],["1157","37","<b>אמת . . אני ראשון ואני אחרון</b>: ישעי' מד, ו. ב\"ר פפ\"א, ב. ראה בהערה הבאה."],["1158","38","<b>ש' הוי' שנק' אמת כנ\"ל</b>: לעיל (במאמר שנדפס לפנ\"ז) פ\"ב."],["1159","39","<b>ואמת הוי'</b>: תהלים קיז, ב."],["1160","40","<b>פיה פתחה בחכמה ותורת חסד על לשונה</b>: משלי לא, כו."],["1161","41","<b>וכי יש תורה של חסד</b>: ראה סוכה מט, ב."],["1162","42","<b>לשמה היינו לשם התורה</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה פ\"ב ופ\"ג ובהנסמן לשם."],["1163","43","<b>כי אם ה' החסד</b>: תהלים קל, ז [ושם: עם — ראה אוה\"ת (שבהערה 25). סה\"מ תרל\"ג כאן. תרס\"ב כאן ע' רפא. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 46: עם]."],["1164","44","<b>זאת . . גזירות ודינין</b>: ראה זהר חוקת קעט, ב. ראה גם מג\"א הל' תענית סו\"ס תק\"פ."],["1165","45","<b>וויתר הקב\"ה . . ולא וויתר על ביטול תורה</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב. הל' ת\"ת לאדה\"ז פ\"ד, ה\"ז."],["1166","46","<b>המאור שבה מחזירן למוטב</b>: ראה הערה שלפנ\"ז. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה ספ\"ב. וש\"נ."],["1167","47","<b>שאלו לחכמה</b>: ירושלמי מכות פ\"ב, ה\"ו. ילקוט שמעוני יחזקאל יח, ד (רמז שנח). תהלים כה, ח (רמז תשב). ילקוט המכירי לתהלים שם (בשינוי הסדר ובהוספות). לקו\"ש עשי\"ת ח\"ד ע' 1358 ואילך. רשימות חוב' קסד (לש\"פ וילך) ע' 3 ואילך. סה\"מ תרכ\"ז ע' תמב. תרל\"ג כאן ע' תלז. ע' תקיח. וש\"נ. תרס\"ב כאן ע' רפא. מאמר ד\"ה דרשו הוי' תרצ\"א נדפס בסה\"מ קונטרסים ח\"א קלג, ב. בסה\"מ תרצ\"א — נמצא בדפוס. לקמן מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים פ\"ח. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה את חג המצות תשמור על יד הערה 111. (לקמן בחלק ההנחות) בהנחה הנ\"ל על יד הערה 124."],["1168","48","<b>חטאים תרדף רעה</b>: משלי יג, כא."]]],[2001910161,"ממשיכים בתורה אז היו נמתקים הדינים, כי חכמה נק' לבנון<sup data-n=\"1169\">49</sup> מקור הלבנוניות והרחמים<sup data-n=\"1170\">50</sup>, והיינו כשנמשך מבחי' לובן העליון<sup data-n=\"1171\">51</sup> שהוא בחי' כתר<sup data-n=\"1172\">52</sup> כח\"ב<sup data-n=\"1173\">53</sup>, ואז נק' החכמה ג\"כ לבנון ונמתקו הדינים, וזהו ובירך את לחמך, שהלחם של תורה צריך לברכה, דהיינו להמשיך אוא\"ס בתורה מבחי' אמת אני ראשון וזהו ע\"י לימוד התורה לשמה.\nז) <b>ואת</b> מימיך, הנה מימיך קאי על תושבע\"פ<sup data-n=\"1174\">54</sup>, דהנה ארז\"ל אכל ולא שתה אכילתו דם<sup data-n=\"1175\">55</sup>, והיינו כי ע\"י המאכל שאדם אוכל המאכל מתהפך לדם, והדם מתפשט בכל האברים, וכתי' כי הדם הוא הנפש<sup data-n=\"1176\">56</sup>, שעי\"ז נמשך חיות הנפש בכל האברים כו', אך כשאכל ולא שתה אז אכילתו דם, והיינו שהגם שהמאכל נעשה דם אמנם מ\"מ אין לו התפשטות בגוף כ\"א ע\"י השתי', שפעולת השתי' הוא שמתפשטת הדם בכל האברים, ואם לא השתי' הדם הוא רק כמו נקודה שאין לה התפשטות כו', וזהו אכילתו דם לבד אבל אין להדם זה התפשטות בגוף, וז\"ע שהתורה שבע\"פ נק' בחי' מים, והיינו שתושב\"כ הגם שנק' לחם למעלה ולמטה<sup data-n=\"1177\">57</sup> מ\"מ הרי הוא כמו נקודה ורמז בלבד, ואינו נתבאר בה עדיין פרטי הלכות כמו עד\"מ ענין מצות תפילין אף שנאמר בתושב\"כ וקשרתם כו' והיו לטטפת<sup data-n=\"1178\">58</sup> כו', מ\"מ אינו ידוע עדיין איך לעשות התפילין, ועיקר הביאור בא בתושבע\"פ שבה נתבאר טט בכתפי שתיים פת באפריקי שתים<sup data-n=\"1179\">59</sup>, ורצועות שחורות הלמ\"מ<sup data-n=\"1180\">60</sup>, ואף שנרמז זה גם בתושב\"כ מ\"מ הוא רק בדרך רמז נקודה, ולא היו יודעים עדיין איך לעשות, אך",[["1169","49","<b>חכמה נק' לבנון</b>: זהר ויצא קסב, ב ובמק\"מ שם ד\"ה מאן. שמות ג, א ובמק\"מ שם ד\"ה דעיקרא. אחרי טז, א ובמק\"מ שם ד\"ה בלבנון. האזינו רצז, א ובמק\"מ שם ד\"ה דא עדן. ביאוה\"ז שמות לו, ב. לקמן הערה 53."],["1170","50","<b>לבנון מקור הלבנונית והרחמים</b>: ראה גם פרדס שבהערה 52."],["1171","51","<b>לבנון . . לובן העליון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשפ. תקס\"ב ותקס\"ד שבהערה 53."],["1172","52","<b>לבנון . . כתר</b>: פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לבנון. ראה בהערה הבאה. מאמרי אדה\"ז מארז\"ל ס\"ע רעא (יסוד דעתיק). לקו\"ת שה\"ש יא, א: לבנון . . שאינו יכול להתלבש כלל בע\"ס ומאיר רק בבחינת מקיף."],["1173","53","<b>לבנון . . כח\"ב</b>: מאמרי אדה\"ז תקס\"ב ח\"א ע' פו. תקס\"ג ח\"ב ע' תרסט (ידוע בכתבי האריז\"ל). תקס\"ד ע' קעד. תקס\"ו ע' שי. שע\"ת קד, א (ג\"ר כח\"ב דע\"י). מאמרי אדה\"א נ\"ך ע' קצג."],["1174","54","<b>מימיך קאי על תושבע\"פ</b>: ראה גם ערה\"כ לבעל סדה\"ד מערכת לחם. מאמרי אדה\"ז תקס\"ח ח\"א כאן ע' תיא. אוה\"ת משפטים כאן ע' א'רכז. ע' א'רלה. וראה גם תו\"א משפטים עח, ד. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 51 ואילך."],["1175","55","<b>אכל ולא שתה אכילתו דם</b>: שבת מא, א. ראה תו\"א שם עח, ג. מאמרי אדה\"א בראשית ע' קטו. שמות ח\"א ע' קפב. ויקרא ח\"א ע' קלט. סה\"מ תרל\"ג כאן ע' תלז ובהנסמן בהנ\"ל."],["1176","56","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["1177","57","<b>שתושב\"כ . . לחם למעלה ולמטה</b>: ראה לעיל בריש המאמר כאן."],["1178","58","<b>וקשרתם כו' והיו לטטפת</b>: ואתחנן ו, ח. עקב יא, יח. ראה גם אגה\"ק סכ\"ט (קנ, ב). תו\"ח ויקהל ח\"ב תכד, ב ובהערה 1329."],["1179","59","<b>טט בכתפי . . שתים</b>: מנחות לד, ריש ע\"ב. רש\"י בא יג, טז. ואתחנן ו, ח. ראה גם לקו\"ש ואתחנן כרך ט ע' 49 ואילך."],["1180","60","<b>ורצועות שחורות הלמ\"מ</b>: שבת כח, ב. מנחות לה, א. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ס. סע\"ה. סל\"ג, ס\"ד-ס\"ה."]]],[2001910162,"בתושבע\"פ בא באריכות כו', וזהו משארז\"ל גדול תלמוד<sup data-n=\"1181\">61</sup> שמביא לידי מעשה, שעיקר המביא לידי מעשה הוא בחי' תלמוד דוקא, וזהו שתושבע\"פ נק' מים. והנה בחי' מים אלו שהוא בחי' תושבע\"פ צריך ג\"כ ברכה מיוחדת ואינו מספיק בברכה של וברך את לחמך, אף על פי שבאמת תושבע\"פ נרמז בתושב\"כ, כי ליכא מידי בתושבע\"פ דלא נרמז באורייתא<sup data-n=\"1182\">62</sup> היינו בתושב\"כ, וכן בכל התלמוד מנלן אמר קרא<sup data-n=\"1183\">63</sup>, מ\"מ צריך תושבע\"פ ברכה בפ\"ע, וזהו שנתקן ג' ברכות בברכת התורה<sup data-n=\"1184\">64</sup> א' כנגד תושב\"כ, וב' כנגד תושבע\"פ* כמו המים שהם צריכים ברכה, ואדרבה שהמים צריך יותר לברכה, לפי שהמים הוא מגדל ומצמיח הכל, וע\"כ צריך יותר לברכה, וכך תושבע\"פ צריך יותר לברכה לפי שתלמוד גדול מפני שמביא לידי מעשה שהוא בחי' זריעה וכמ\"ש זורע צדקות<sup data-n=\"1185\">65</sup>, וע\"י התלמוד נעשה הצמיחה כמו ע\"י המים כנ\"ל. והענין הוא דהנה ארז\"ל ע\"פ ושמתם את דברי כו' סם תם<sup data-n=\"1186\">66</sup>, וזאת התורה אשר שם משה, למיימינים בה<sup data-n=\"1187\">67</sup> סמא דחיי למשמאילים בה סמא דמותא ח\"ו, והענין הוא דהנה תושבע\"פ הוא לברר עה\"ד טו\"ר<sup data-n=\"1188\">68</sup>, וכשלומד לשמה אז ממשיך מבחי' עה\"ח בעה\"ד טו\"ר ומתברר הרע כו' וזהו סמא דחיי, משא\"כ כשלומד ח\"ו להתגדל או לקנטר אז אינו מברר את הרע, ואדרבה שמגביר את הרע ע\"ע, וע\"כ נעשה לו ח\"ו סמא דמותא, לפי שע\"י התורה כשלומד ח\"ו להתגדל או לקנטר אז הוא נעשה בחי' יש ומגביר על עצמו את הרע, משא\"כ תושב\"כ הוא בחי' ביטול כו' וזהו ובירך כו' ואת מימיך שילמוד לשמה ואז יהי' נמשך מבחי' עה\"ח בעה\"ד לברר את הרע, ועיקר הברכה צריך בתושבע\"פ לפי שעיקר שלא לשמה יכול להיות בתושבע\"פ<sup data-n=\"1189\">69</sup>, משא\"כ בתושב\"כ אינו יכול להיות כ\"כ להתגדל או להתייהר, לפי שהוא בחי' ביטול וידבר ה' אל משה לאמר<sup data-n=\"1190\">70</sup> שהוא הכל בחי' ביטול כו' וע\"כ המים תושבע\"פ צריך יותר לברכה.\n\n*)נרשם בשולי היריעה ולא נסמן מקומו בפנים:\nב' כנגד תושבע\"פ ע' באבודרם[ftnref_8211_א], כדעת ה\"ר זרחי' הלוי.",[["1181","61","<b>גדול תלמוד</b>: ראה קדושין מ, ב."],["1182","62","<b>ליכא מידי . . דלא נרמז באורייתא</b>: ראה זהר פינחס רכא, א."],["1183","63","<b>מנלן אמר קרא</b>: ראה פסחים סא, סע\"א. סה, רע\"א. ועוד."],["1184","64","<b>ג' ברכות בברכת התורה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סמ\"ו, ס\"א. סמ\"ז ס\"ד-ס\"ה."],["1185","65","<b>זורע צדקות</b>: נוסח ברכת יוצר."],["1186","66","<b>ושמתם . . סם תם</b>: עקב יא, יח. קדושין ל, ב."],["1187","67","<b>למיימינים בה</b>: ראה שבת פח, ב."],["1188","68","<b>תושבע\"פ . . עה\"ד טו\"ר</b>: ראה אגה\"ק סכ\"ו. סה\"מ תרל\"ח ע' ר ואילך."],["1189","69","<b>שעיקר שלא לשמה . . בתושבע\"פ</b>: ראה גם סה\"מ תרל\"ג כאן ע' תלח ובשולי היריעה שם. תרס\"ב כאן ע' רפב ואילך."],["1190","70","<b>וידבר ה' אל משה לאמר</b>: וארא ו, י. כט. בא יג, א. ועוד.\n\n[ftn_8211_א]) <i>באבודרם:</i> ראה אבודרהם ברכות השחר ד\"ה הערב נא ע' מד. וראה גם רבינו יונה לברכות יא, ב ד\"ה והא דרב המנונא."]]]]});
